INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (66, 54, '1983510', 'Product Owner', NULL, NULL, '1 năm', 'Nhân viên', '2026-05-23 19:07:55.655775', '2026-07-03 19:07:55.655775', 7, 'Never settle, think bigger. Vulcan Labs is a leading mobile application development company based in Ho Chi Minh City, Vietnam, with flexibility for some remote work. Since 2017, we have published over 40 mobile applications with several hundred thousand Daily Active Users and over 10 million downloads combined. We welcome individuals from diverse backgrounds to join our team and embrace challenges in a fast-changing industry. As Product Owner in our team, you will:Join to build product plan and manage product portfolioBuild product/market research, product proposals with AI domain, as well as the calculation of business casesCollaborate with business leaders, engineers, and other stakeholders to define an ambitious strategy, and develop and maintain a prioritized product backlog, to deliver delightful and impactful product experiences for customers.Work closely and cross-functionally with all the teams building, marketing, UI/UX, Developers and supporting a well-defined go-to-market plan.Foster a culture of testing, data-driven decision making, and accountability for metrics and resultsDefinition, monitoring of product portfolio/goals relevant KPIs and control of the measures to achieve the objectives set', '1-3+ years of relevant product management experience;Experience in a prior startup or other high-ambiguity environment;Prior consumer-facing product development experience, ideally with mobile orsubscription-based productsExperience with AI platform is a huge plusPrior experience with psychology-based products, gamification, or other user behavior-oriented appsAdditional PO skills we highly value:Consumer user empathy & perspectiveExperience with data analysis, metrics, and goal-settingAnalytical dexterity a.k.a. critical problem solvingScrappy–execution & outcome-focusedCurious and teachable', 'Grow Yourself: Work with young, talented teammates on global apps across a diverse portfolio and varying app sizes (Mainly in AI domain)Attractive Package: 13th-month salary, performance bonus, and biannual performance reviews based on achievements and contributions.Healthy Culture: 12 days of annual leave and 5 days of sick leave, health-care insurance, annual health check, and a dedicated team-bonding budget.Well-equipped Facility: MacBook provided, with an additional monitor available if needed.Diverse Activities: Complimentary coffee, tea, and snacks; company trips; team-building activities; and quarterly happy-hour events.Innovative Environment: Flexible working hours, one remote day per month, seminars and internal sharing sessions, and a culture with no barriers to ideas.', 'Trụ sở chính công ty', 8, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (96, 83, '2001214', 'Product Designer', NULL, NULL, '2 năm', 'Nhân viên', '2026-05-23 19:07:55.655775', '2026-06-13 19:07:55.655775', 5, 'I. MỤC ĐÍCH CÔNG VIỆCBạn sẽ tham gia thiết kế các sản phẩm Mobile App của TP Entertainment, với trọng tâm UI/Visual Design (bố cục, typography, màu sắc, design system, tính nhất quán, độ “sạch” của giao diện) đồng thời phối hợp cùng team để đảm bảo trải nghiệm end-to-end (UX).Bạn phù hợp nếu:Yêu thích UI craft và muốn nâng cấp “visual taste” mỗi ngày.Làm tốt trong môi trường phát triển sản phẩm: làm rõ yêu cầu, thiết kế giải pháp dựa trên data-driven, tiếp nhận user feedback và liên tục cải tiến.II. MÔ TẢ CÔNG VIỆC1.  Thiết kế giao diện người dùng (UI/Visual Design):Thiết kế high-fidelity UI cho mobile app: layout, màu sắc, typography, iconography, spacing, component usage.Tạo và duy trì Design System / UI Kit: component, variant, states, guideline, token cơ bản (màu, text style, spacing…).Đảm bảo consistency giữa các màn hình, luồng, và giữa các tính năng.Nâng chất lượng “craft” qua việc polish: alignment, hierarchy, readability, density, empty states, error states, loading states…Phối hợp với Developer để đảm bảo UI đúng thiết kế; hỗ trợ handoff: spec, trạng thái, interaction notes, asset export.2. Thiết kế trải nghiệm người dùng (UX Design):Làm rõ yêu cầu với PO/PM/Stakeholders; hiểu mục tiêu tính năng và luồng chính.Tạo wireframe/flow đơn giản khi cần để thống nhất hướng trước khi lên UI.Thiết kế các trạng thái trải nghiệm quan trọng: onboarding, paywall/subscription, list-detail, search/filter, settings…3. Nghiên cứu người dùng & thị trường:Tham gia các hoạt động kiểm thử tính khả dụng (usability test) cơ bản, hỗ trợ thu thập và phân tích dữ liệu người dùng.Hiểu sự khác biệt giữa nghiên cứu định tính và định lượng, biết cách khai thác insight của người dùng.Hỗ trợ thành viên cấp cao trong việc xây dựng, thực hiện và tổng hợp nghiên cứu người dùng.Thu thập và phân tích dữ liệu từ nhiều nguồn (phỏng vấn, survey, dữ liệu hành vi người dùng, funnel…).4. Phân tích dữ liệu:Thiết lập và kiểm tra event tracking cho mobile app.Thực hiện các phân tích đơn giản như tỷ lệ chuyển đổi, so sánh A/B test cơ bản.Có kiến thức về data-driven để đưa ra quyết định thiết kế chính xác với nhu cầu của khách hàng.', 'Kiến thức:Có từ 02 năm kinh nghiệm làm UI/UX Designer hoặc vị trí liên quan.Hiểu biết cơ bản về nghiên cứu người dùng, quy trình thiết kế sản phẩm và hệ thống thiết kế (design system).Thành thạo công cụ thiết kế: Figma, Photoshop, Illustrator, hiểu biết về HTML/CSS là một lợi thế.Kỹ Năng:Kỹ năng giao tiếpKỹ năng phân tích và giải quyết vấn đềKhả năng làm việc nhómTố chất:Tư duy hệ thống Tư duy sáng tạoGiao tiếp tốt', 'Thử việc 02 tháng hưởng 100% mức lương chính thức.Có cơ hội làm việc cho Thị trường global – Có cơ hội nghiên cứu và hiểu insight của nhiều tệp khách hàng khác nhau đến từ các quốc gia khác nhau và được tiếp cận các công cụ tốt nhất thị trường.Thu nhập không giới hạn: Lương cứng + thưởng KPI, thưởng dự án, lương tháng 13, thưởng Tết,…Thu nhập lên tới 15-18 tháng lương/năm.Thưởng và review lương 2 lần/năm.Khám sức khỏe định kỳ hàng năm.Trợ cấp tiền ăn trưa khi là nhân viên thử việc.Du lịch hàng năm, dã ngoại hàng quý 4 lần/năm, du lịch cùng người thân.Hưởng đầy đủ các chế độ bảo hiểm theo quy định của nhà nước khi là nhân viên chính thức.3 Lý do bạn chọn TP Entertainment:1 là bạn có cơ hội phát triển bản thân thần tốc:Môi trường TP Entertainment luôn phát huy hết điểm mạnh và khả năng sáng tạo của bạn, nhờ đó bạn có cơ hội được tỏa sáng.Được làm việc và hướng dẫn trực tiếp bởi đội ngũ giàu kinh nghiệm.2 là bạn có cơ hội tăng thu nhập không giới hạn:Những đóng góp của bạn luôn được công ty ghi nhận rõ ràng nhờ đó thu nhập của bạn được cải thiện nhanh chóng và không giới hạn.3 là môi trường làm việc lý tưởng:Văn hoá công ty đậm đà sâu sắc với 4 giá trị cốt lõi: Hiệu quả, sáng tạo, lấy khách hàng là trung tâm, nhân văn.Làm việc tại công ty công nghệ hàng đầu về Mobile app với môi trường trẻ trung, năng động, thân thiện, sáng tạo.', 'Trụ sở chính công ty', 220, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (7, 1, '2029674', 'Lập Trình Viên AI/Xử Lý Ảnh - Tại Hà Nội - Có Nhận Phỏng Vấn Trước Tết & Sau Tết Nhận Việc', NULL, NULL, 'Dưới 1 năm', 'Nhân viên', '2026-05-02 19:07:55.655775', '2026-05-28 19:07:55.655775', 5, 'Phát triển các thuật toán trong lĩnh vực xử lý ảnh (AI, Computer Vision), phát triển từ các ý tưởng/bài toán trong lĩnh vực xử lý ảnh thành các ứng dụng có tính thực tiễn;Nhận và phân tích các yêu cầu về phần mềm từ khách hàng;Nghiên cứu và phát triển các sản phẩm liên quan tới Image AI của công ty;', 'Lập trình thành thạo sử dụng 1 ngôn ngữ Python, C/C++,....Đã từng tiếp xúc với thư viện OpenCV hoặc Tensorflow/PyTorch.Có kinh nghiệm sử dụng Google Colab là một lợi thế.Hoan nghênh cả những bạn chưa có kinh nghiệm về AI và xử lý ảnh, chỉ cần kiến thức toán cơ bản vững và chịu khó học hỏi, A.N.Lab sẽ có lộ trình đào tạo.Có khả năng (hoặc mong muốn) làm việc và giao tiếp với khách hàng đa quốc tịch.', 'Cơ hội phát triển bản thânĐược đào tạo kiến thức cần thiết để trở thành một Kỹ sư phần mềm chuyên nghiệp với một nền tảng công nghệ mới;• Được tích lũy kinh nghiệm và có cơ hội học tập, đào tạo bởi những kỹ sư nhiều kinh nghiệm;• Được trải nghiệm với những công nghệ, dự án mới lạ cùng khách hàng Nhật, Mỹ;• Nếu bạn có kinh nghiệm và năng lực, bạn sẽ được giao phó một mảng việc độc lập với những quyền chủ động nhất định (ví dụ: nhân sự, nội dung công việc, tài chính,....)Chế độ lương thưởng:• Hưởng lương, thưởng theo năng lực, không phân biệt bằng cấp, tuổi tác;• Đánh giá nhân sự và tăng lượng 2 lần/năm;• Chính sách thưởng 3 kỳ/năm;Đào tạo và phát triển:• Chương trình đào tạo kỹ thuật hàng tháng;• Thưởng đào tạo cho các chứng chỉ kỹ thuật, tiếng anh và tiếng nhật;• Tủ sách miễn phí và được đề xuất mua sách nghiên cứu và học tập;Chế độ phúc lợi:• Đóng BHXH, BHYT, BHTN theo quy định của pháp luật;• Ngày nghỉ phép lên tới 22 ngày/năm (bao gồm ngày nghỉ phép, nghỉ ốm, nghỉ sinh nhật,...);• Du lịch hè hàng năm, Golden Day, Dã ngoại mùa thu,...(ngày đặc biệt của công ty);• Khám sức khỏe định kỳ hàng năm;• Bảo hiểm sức khỏe dành cho nhân viên;• Trợ cấp thai sản đảm bảo hưởng nguyên lương;• Quà tặng cho cha mẹ và con nhân viên vào các dịp lễ truyền thống;', 'Trụ sở chính công ty', 969, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (52, 44, '2032904', 'AI Engineer', NULL, NULL, '2 năm', 'Nhân viên', '2026-05-22 19:07:55.655775', '2026-07-01 19:07:55.655775', 5, 'Tham gia nghiên cứu và phát triển các sản phẩm ứng dụng  (LLM). Hỗ trợ xây dựng và tối ưu hệ thống Agent / Multi-Agent nhằm giải quyết các bài toán phức tạp trong lĩnh vực NLP. Tham gia vào quá trình phân tích yêu cầu, thiết kế, và triển khai mô-đun AI trong các dự án thực tế. Làm việc cùng đội ngũ kỹ sư AI để tích hợp mô hình NLP vào hệ thống backend hoặc sản phẩm hoàn chỉnh.', 'Có ít nhất 2–3 năm kinh nghiệm thực tế trong lĩnh vực NLP, Machine Learning Nắm vững cấu trúc dữ liệu và giải thuật, tư duy logic tốt. Thành thạo Python và lập trình hướng đối tượng (OOP). Hiểu và tuân thủ coding convention, có khả năng viết code sạch, dễ đọc, dễ bảo trì. Có kinh nghiệm làm việc với Git, hiểu quy trình làm việc nhóm (branch, PR, review, CI/CD). Có kiến thức vững chắc về các mô hình NLP hiện đại như Transformer, BERT, GPT, LLaMA, DeepSeek, Qween. Kinh nghiệm fine-tuning / instruction-tuning mô hình LLM và triển khai – tối ưu hóa mô hình trong môi trường production. Có kinh nghiệm thiết kế, xây dựng và tối ưu hệ thống Chatbot, RAG hoặc Agent/MultiAgent Quen thuộc với các framework như LangChain, LangGraph, CrewAI, Agno, LlamaIndex, v.v. Có kinh nghiệm làm việc với Vector Database (Qdrant, Milvus, Chroma, v.v.). Hiểu biết về Relational Databases như MySQL hoặc PostgreSQL. Nice to Have: Kinh nghiệm phát triển Backend với Flask hoặc FastAPI. - Hiểu biết về triển khai và tối ưu hệ thống AI trong production (Docker, API Gateway, Cloud, GPU inference). - Có kinh nghiệm triển khai end-to-end dự án NLP, bao gồm hosting và serving các mô hình embedding và LLM.', 'Lương: Thỏa thuận theo năng lực, đảm bảo cạnh tranh thị trường + thưởng theo hiệu suất.Thử việc full lương. Bonus 1 năm /lần (theo hiệu suất công việc và kết quả kinh doanh). Thưởng tháng 13 theo quy định của công ty. Đóng BHXH theo quy định luật LĐVN, khám sức khỏe định kỳ 1 năm/lần. React Plus healthcare sau 6 tháng làm việc. Tham gia các hoạt động tea break hàng ngày, event sôi động, các hoạt động thể thao như bóng đá, game, open talk hàng  tháng. Teambuilding, du lịch hàng năm.', 'Trụ sở chính công ty', 707, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (36, 29, '2032872', 'Thực Tập Sinh Game Designer (6 -8M/Tháng)', 6.00, 8.00, 'Không yêu cầu', 'Nhân viên', '2026-05-21 19:07:55.655775', '2026-06-15 19:07:55.655775', 5, 'Hỗ trợ việc phát triển ý tưởng và thiết kế các tính năng game mới dưới sự hướng dẫn của các Game Designer có kinh nghiệm.Tham gia vào quy trình brainstorming và đóng góp ý kiến để cải thiện gameplay và trải nghiệm người chơi.Hỗ trợ việc tạo ra các tài liệu thiết kế chi tiết, bao gồm viết mô tả tính năng, lập kế hoạch cấp độ và tổ chức thông tin.Thực hiện nghiên cứu thị trường và phân tích đối thủ cạnh tranh để hiểu rõ về xu hướng hiện tại và yêu cầu của người chơi.Thử nghiệm prototype game, góp phần vào quá trình kiểm thử chất lượng sản phẩm.Học hỏi và áp dụng kiến thức về các công cụ thiết kế game và phần mềm liên quan.', 'Là sinh viên năm thứ 3, 4, 5 các trường Đại học chính quy.Có thể đi làm tối thiểu 6 buổi/tuần, ưu tiên có thể đi fulltime.Yêu thích chơi game, ham tìm hiểu về game, có khả năng phát triển ý tưởng cho game, mong muốn phát triển sự nghiệp trở thành game designer.Giỏi toán, số học, tư duy logic tốt, khả năng phân tích dữ liệu tốt.Thông minh, chăm chỉ, ham học hỏi, cầu tiến', 'Lương 6-8M/tháng tính theo số ngày công thực tế, được xét thưởng và tăng thù lao theo năng lực.Được trợ cấp bữa ăn trưa (chi phí 50.000 VNĐ/ suất), tea-break,... tại Công ty.Đào tạo: Được tham gia các khóa đào tạo chuyên môn nội bộ, các buổi hội thảo công nghệ cùng chuyên gia và các đối tác lớn như Google, Facebook,...Tham gia các công việc thực tế như thành viên dự án.Phúc lợi: Tham gia các hoạt động teambuilding, du lịch cùng Công ty.Được ưu tiên xét tuyển lên nhân viên chính thức của Công ty.', 'Trụ sở chính công ty', 4, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (106, 94, '2000227', 'Physical Design Engineer (STA Focus)', NULL, NULL, '3 năm', 'Nhân viên', '2026-05-23 19:07:55.655775', '2026-06-24 19:07:55.655775', 7, '•	Perform Static Timing Analysis (STA), validation, and debug across multiple PVT conditions using Tempus.
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (17, 9, '1949442', 'Technical Lead .Net', NULL, NULL, '5 năm', 'Nhân viên', '2026-04-24 19:07:55.655775', '2026-05-13 19:07:55.655775', 5, 'Quản lý nhóm phát triển .NET theo dự án hoặc dòng sản phẩm: phân công công việc, giám sát tiến độ, đảm bảo hoàn thành đúng hạn với chất lượng mong muốn.Thiết kế kiến trúc hệ thống, lựa chọn công nghệ và định hướng kỹ thuật phù hợp với mục tiêu sản phẩm.Phụ trách kỹ thuật chuyên sâu: giải quyết các vấn đề kỹ thuật phức tạp, rà soát mã nguồn, đảm bảo hiệu suất và khả năng mở rộng hệ thống.Đào tạo và phát triển nhân lực kỹ thuật: hướng dẫn, kèm cặp các thành viên trong nhóm, đề xuất chương trình đào tạo nội bộ.Đánh giá năng lực nhân sự kỹ thuật đang phụ trách: định kỳ phản hồi, góp ý và đề xuất nâng bậc, điều chuyển hoặc hỗ trợ phát triển cá nhân.Phối hợp chặt chẽ với các bộ phận liên quan để đảm bảo tiến độ chung và chất lượng sản phẩm', 'Tốt nghiệp Đại học trở lên các chuyên ngành Công nghệ thông tin, Kỹ thuật máy tính hoặc các chuyên ngành liên quan….Thành thạo ngôn ngữ lập trình C# và framework ASP.NET.Có từ 5 năm kinh nghiệm lập trình trên nền tảng .Net Core, trong đó có ít nhất 2 năm ở vai trò Team leader.Có kinh nghiệm thực tiễn với Entity Framework Core để tương tác với cơ sở dữ liệuCó khả năng phân tích thiết kế hệ thống, kiến thức tốt về OOP & Design Patterns, Network, Multithreading.Kinh nghiệm làm việc với các hệ quản trị cơ sở dữ liệu như SQL Server, MySQL, PostgreSQL.Có kinh nghiệm tham gia triển khai dự án theo mô hình Agile/ScrumƯu tiên hiểu biết về kiến trúc microservices và quy trình DataOps, kinh nghiệm tối ưu dữ liệu lớn.Ưu tiên có kinh nghiệm làm việc về xử lý video, xử lý đa luồng hiệu năng cao, đặc biệt là tăng tốc phần cứng với card đồ họaNhanh nhạy trong việc cập nhập các xu hướng công nghệ mới.Tư duy phản biện, giải quyết vấn đề nhanh và hiệu quả.Tiếng Anh đọc hiểu tốt tài liệu kỹ thuật.', 'LÝ DO ĐỂ ĐỒNG HÀNH VỚI ELCOMVới truyền thống 30 năm hình thành phát triển, Elcom chắc chắn sẽ là nơi làm việc khiến bạn an tâm gắn bó lâu dài, với:Sự tiên phong trong công nghệ:Tham gia ứng dụng công nghệ mới vào những sản phẩm lớn, bộ giải pháp toàn diện Top đầu thị trường thuộc các lĩnh vực Chuyển đổi số, An ninh Quốc phòng, giao thông thông minh,... Được tiếp cận với xu hướng công nghệ hàng đầu, phát triển giải pháp thông minh "powered by AI"Môi trường thân thiện, chia sẻ, đồng hành:Môi trường làm việc thân thiện, cởi mở,  tôn trọng sự khác biệt và đề cao sáng tạo, Elcomers được tự do phát triển các ý tưởng tiến bộ, cải tiến công việc.Đào tạo và phát triển liên tục với nhiều chương trình huấn luyện chuyên nghiệp, Manager hỗ trợ sát sao, nhiệt tình.Nền tảng vững chắc cho phát triển sự nghiệp, thăng tiến, quyền lợi:Thu nhập cạnh tranh: Lương theo năng lực +thưởng sáng kiến, thưởng các dịp lễ, ESOP và từ lợi nhuận công ty. Tổng thu nhập 1 năm lên tới 15 tháng lương.Phúc lợi cao cấp:Bảo hiểm sức khỏe cho bạn & người thân (tới $6.000/người)Khám sức khỏe định kỳ tại bệnh viện hàng đầuĂn trưa miễn phí tại văn phòngĐược hưởng toàn bộ các quyền lợi theo Luật lao động ban hành về chế độ tham gia bảo hiểm xã hội, nghỉ lễ, nghỉ phép năm.Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân…Văn hóa gắn kết – truyền cảm hứng:Du lịch, teambuilding, sự kiện công ty tại resort cao cấpCâu lạc bộ thể thao, âm nhạc, hoạt động cộng đồng ý nghĩa (“Trăng sáng yêu thương”, “Cơm có thịt”…)Thời gian làm việc: thứ 2 đến thứ 6.', 'Trụ sở chính công ty', 32, NULL, 0);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (13, 4, '2022820', 'UX/UI Designer (Up To 20M)', 10.00, 20.00, 'Dưới 1 năm', 'Nhân viên', '2026-05-17 19:07:55.655775', '2026-06-22 19:07:55.655775', 5, 'Tham gia phát triển sản phẩm Shopify themesConvert client’s brief / requirements thành giao diện websiteTối ưu các designs sẵn cóPhối hợp, làm việc nhóm với Product owners, developers, marketing team, BA để đảm bảo các tiêu chuẩn và chất lượngNghiên cứu và cập nhật các xu hướng thiết kế mới', 'Có kinh nghiệm thiết kế website thương mại điện tửTiếng Anh đọc hiểu tốtThành thạo Figma, PhotoshopCó khả năng nắm bắt các yêu cầu cụ thể của sản phẩm và đưa ra các giải pháp thiết kế phù hợpCó tinh thần trách nhiệm cao với sản phẩm cung cấp cho người dùng, khách hàng thay vì chỉ hoàn thành những gì được giaoChú ý cao đến các chi tiết, cẩn thận, tỉ mỉKhả năng làm việc nhóm tốtKhả năng giao tiếp, trình bày tốtCó tư duy phân tích và phản biện tốtHiểu biết về các công nghệ phát triển front-end như HTML, CSS và JavaScriptShowcase các dự án đã thiết kế', 'Lương gross up to 20M, đánh giá tăng lương 2 lần/nămThời gian làm việc 5 ngày/tuần, từ 8h30 đến 17h45Cơ hội phát triển sâu rộng các kỹ năng chuyên môn thông qua các buổi đào tạo nội bộ và chính sách tài trợ học/thi các khóa học, chứng chỉ chuyên môn  Nhiều phúc lợi hấp dẫn: 13.5 ngày nghỉ phép/năm (12 ngày nghỉ phép theo quy định và 1.5 ngày nghỉ phép du lịch hàng năm), bảo hiểm, hiếu hỉ, quà sinh nhật, thưởng thâm niên và các phúc lợi khác theo quy định của pháp luật.Môi trường làm việc trẻ trung (95% là 9x), làm hết sức, chơi hết mình. Văn phòng làm việc tiện nghi. Free trà, cafe và có tủ đồ uống.Tham gia các chương trình team building, dã ngoại, sinh nhật thành viên, du lịch, từ thiện… do BSS tổ chức thường xuyên.Tham gia các CLB chạy, đá bóng, boardgame, văn nghệ… sau giờ làm việc.Nghỉ hằng năm và các phúc lợi khác theo quy định của pháp luật.', 'Trụ sở chính công ty', 391, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (24, 14, '2023040', 'Product Owner/ Business Analyst (English)', NULL, 30.00, '2 năm', 'Nhân viên', '2026-04-22 19:07:55.655775', '2026-06-03 19:07:55.655775', 5, 'Understand high-level goals to ensure alignment in execution, guiding product initiatives toward strategic business objectives.Conduct competitor research and market analysis to identify trends and opportunities in Affiliate Marketing, and incorporate insights into product decisions.Gather user feedback and analyze user behavior to identify pain points, feature needs, and opportunities for improvement.Translate high-level initiatives into detailed epics and features that are actionable and ready for backlog preparation and refinement.Break down business requirements into user stories, technical specifications, and acceptance criteria to guide development teams.Collaborate with design and development teams to ensure requirements are feasible and understood, and provide clarification throughout the development process.Own and prioritize the product backlog, refining it based on user needs, business goals, and technical feasibility.Support sprint planning, clarify scope with the development team, and manage the delivery process to ensure features are completed on time.Track event implementation and ensure data quality, collaborating with the Growth team to ensure performance metrics are accurately captured.Validate delivered features against business objectives and user expectations, analyzing post-launch data to inform future product iterations.', '2+ years of experience as a Business Analyst, Product Owner, or similar role in a SaaS or technology product environment.Strong communication skills in English (written and verbal).Strong experience with backlog management, creating user stories, and working closely with cross-functional teams in an Agile environment.Proven ability to gather and analyze business and user requirements, then translate them into clear product specifications.Familiarity with event tracking, product performance analytics, and measuring product success.Excellent communication skills, able to collaborate effectively with stakeholders across Product, Engineering, Design, and Growth teams.Strong problem-solving skills, with the ability to deliver results that meet both user needs and business goals.Solid understanding of software development lifecycle and Agile/Scrum processes.Good understanding of user experience principles and user behavior.Ability to think strategically while remaining hands-on with execution.Experience in Affiliate Marketing, E-commerce, or Marketplace products is a strong plus.Familiarity with tools such as Jira, Confluence, Notion, Product analytics tools (GA, Mixpanel, Amplitude) is a plus.Good English', 'Competitive Salary (up to 30M)Salary review after 06 months
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (14, 5, '2008069', 'Business Analyst (Domain Bank/Fintech)', NULL, NULL, '5 năm', 'Nhân viên', '2026-05-14 19:07:55.655775', '2026-06-10 19:07:55.655775', 5, '1.Phân tích nghiệp vụTiếp nhận, phân tích và làm rõ yêu cầu sản phẩm, dịch vụ CNTT từ các đơn vị.Làm việc với các bên liên quan để thống nhất phạm vi và yêu cầu nghiệp vụ.Xác định các yếu tố nghiệp vụ ảnh hưởng, đánh giá tính khả thi và mức độ ưu tiên2.  Xây dựng tài liệu phân tích nghiệp vụXây dựng tài liệu phân tích nghiệp vụ chi tiết: BRD, FSD, SRS.Mô hình hóa quy trình nghiệp vụ sử dụng BPMN/UML, Use case, User story.Trình bày tài liệu phân tích và hỗ trợ kỹ thuật hiểu rõ yêu cầu.3. Tham gia triển khai dự án công nghệPhối hợp cùng các bộ phận kỹ thuật và quản lý dự án để lựa chọn, đề xuất giải pháp.Hỗ trợ quá trình kiểm thử (UAT), nghiệm thu, Golive và hỗ trợ sau triển khai.Xác định rủi ro trong dự án và phối hợp đề xuất phương án xử lý.4. Thực hiện các nhiệm vụ khác theo phân công của cấp trên', '1. Kinh nghiệm: Tối thiểu 05 năm kinh nghiệm trong lĩnh vực phân tích nghiệp vụ, ưu tiên trong lĩnh vực ngân hàng hoặc tài chính.Ưu tiên ứng viên: Am hiểu hệ thống ngân hàng lõi, các sản phẩm tài chính số, ứng dụng quản trị.2. Kiến thức: Am hiểu tổ chức: Nắm rõ mô hình hoạt động ngân hàng và ứng dụng CNTT trong hoạt động ngân hàngAm hiểu về lĩnh vực/ ngành nghề: Nắm vững hoạt động tài chính - ngân hàng, đặc biệt là cách các nghiệp vụ ngân hàng được số hóa và triển khai trên hệ thống CNTT3. Kiến thức chuyên môn: Am hiểu chuyên môn nghiệp vụ của vị trí (chính sách/ quy định/ quy trình…): Nắm vững kỹ thuật phân tích nghiệp vụ, mô hình hóa quy trình, viết tài liệu BRD/FSD; Am hiểu về pháp luật liên quan: Nắm được các quy định pháp lý về công nghệ thông tin, bảo mật thông tin, dữ liệu khách hàng trong lĩnh vực ngân hàng.4. Kỹ năng/ khả năng:Năng lực chung:Tư duy logic; giao tiếp và truyền thôngGiải quyết vấn đề và ra quyết địnhNăng lực chuyên môn: Kỹ năng phân tích nghiệp vụ và thiết kế giải pháp.Kỹ năng mô hình hóa quy trình nghiệp vụ.Kỹ năng trình bày, truyền đạt và làm việc nhóm.', 'Làm việc từ thứ 2 đến thứ 6Thưởng các ngày lễ Tết trong năm, thưởng tháng lương 13, thưởng Tết căn cứ vào kết quả kinh doanhHỗ trợ ăn trưa 50k/ngày làm việcHỗ trợ gửi xe 300k/thángReview tăng lương tối thiểu 1 lần/nămDu lịch nghỉ mát, team building hàng nămBHXH, BHYT, BHTN theo quy định của pháp luật hiện hànhĐược thử thách trong các dự án lớn, có cơ hội khẳng định năng lực bản thân và phát triển sự nghiệp', 'Trụ sở chính công ty', 675, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (108, 164, '2034050', 'Manual Tester (English)', NULL, NULL, 'Dưới 1 năm', 'Nhân viên', '2026-04-28 19:07:55.655775', '2026-06-05 19:07:55.655775', 5, 'Review, understand, and analyze project requirement documents.Create test plans, write test cases, execute testing, and prepare test reports for websites, POS systems, online payments, e-wallets, loyalty systems, mobile banking applications, and financial/banking platforms.Perform other tasks as assigned by the Team Leader.', 'Minimum 6 months of experience as a Software Tester/QAGood English skills, especially in writing and understanding technical documentationHands-on experience in testing websites and mobile applicationsFamiliar with database testing and API testing tools such as Postman, JMeter, or similarSolid understanding of the software testing lifecycle and processesExperience using bug tracking/management tools (e.g., Jira or equivalent)Strong ability to read, analyze, and understand project requirementsDetail-oriented, responsible, and careful in workAble to work independently as well as collaboratively in a team; quick learner with a proactive attitude', '1. Compensation & AllowancesCompetitive salary, negotiable based on experience and capability13th-month salary, year-end bonus, project bonus, and other performance incentivesOvertime compensation in accordance with company policySalary review twice per year or based on outstanding performance2. Insurance & HealthcareFull statutory insurance: Social Insurance, Health Insurance, and Unemployment InsuranceInsurance coverage applied from probation periodBao Viet premium healthcare insurance for employees and family members12 annual leave days + public holidays in accordance with Vietnamese labor lawAdditional support for sickness, maternity, and special occasions3. Work Environment & Other BenefitsCompany-provided laptop and necessary working equipmentAnnual company trips, team building, and retreats (domestic or international) at least once per yearWeekly Happy Hour, monthly birthday celebrations, company parties, football club, and more internal activitiesWorking hours: 8:30 AM – 6:00 PM, Monday to Friday (weekends off)Opportunities to contribute ideas, work on product development, and take ownership of projectsYoung, dynamic, and creative environment with supportive teammates', '-Hà Nội:Tầng 2, tòa CT1 Epic Home, 43 Phạm Văn Đồng, Phường Đông Ngạc', 698, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (57, 49, '2034157', 'Middle Android Developer (App)', 18.00, 26.00, '2 năm', 'Nhân viên', '2026-05-09 19:07:55.655775', '2026-06-18 19:07:55.655775', 5, 'Phát triển & bảo trì ứng dụng Android, phối hợp BA/PO/Design/Backend để triển khai tính năng đúng yêu cầu.Tối ưu performance/UX, refactor, fix bug; đảm bảo app ổn định trên nhiều thiết bị.Chủ động theo dõi và xử lý ANR/Crash (Crashlytics/Play Console), phân tích cải thiện chất lượng sản phẩm.Tham gia code review, chuẩn hoá kiến trúc (MVVM/Clean), tích hợp API/SDK Nghiên cứu, tìm hiểu các công nghệ mới phục vụ các nhu cầu của công ty.', 'Tối thiểu 2 năm kinh nghiệm phát triển Android bằng Kotlin; ưu tiên đã có app release thực tế trên Google Play.Nền tảng lập trình tốt, hiểu và áp dụng SOLID, làm việc với Clean Architecture; thành thạo MVVM (ưu tiên biết/đã dùng MVI).Nắm vững Android core: Service, BroadcastReceiver, vòng đời, permission, background/foreground, tối ưu tương thích nhiều phiên bản.Thành thạo Jetpack: ViewModel, LiveData/StateFlow, Room, WorkManager, ViewBinding.Xử lý bất đồng bộ tốt với Kotlin Coroutines + Flow, chú trọng hiệu năng, tránh leak/ANR, tối ưu memory.Thành thạo các thư viện core: Retrofit (network), Room (database), Hilt/Dagger2 (DI).Sử dụng tốt Firebase (Analytics, Crashlytics, ANR, Remote Config…) để theo dõi lỗi, đo lường và tối ưu sản phẩm.Thành thạo Git, làm việc theo quy trình branch/PR.Ưu tiên (Nice-to-have):Có kinh nghiệm UI nâng cao: Custom View (Canvas), Animation, xử lý giao diện đa kích thước màn hình, multi-themes (Dark/Light, dynamic colors…).Có kinh nghiệm xử lý Video/Image, ưu tiên biết FFmpeg.Hiểu và từng làm các tính năng realtime: Socket / streaming dữ liệu liên tục.Tích hợp Google Play Billing; có kinh nghiệm tối ưu hiệu suấtd quảng cáo (AdMob, Pangle, mediation…).Tư duy logic, tư duy sản phẩm tốt, chủ động đề xuất giải pháp.Tự học nhanh, cập nhật công nghệ mới, phối hợp tốt với team (Dev/UI/Tester/Backend).', 'Thu nhập 18-26M/thángCơ hội làm việc với sản phẩm app Global, người dùng trả phí thực tế.Lộ trình phát triển lên Senior Android Developer.Môi trường làm việc linh hoạt, đề cao hiệu quả và trách nhiệm.Tham gia trực tiếp vào quá trình xây dựng sản phẩm từ đầu.Hưởng đầy đủ các chế độ theo quy định của pháp luật lao động.', '-Hà Nội:49 Thái Hà, Phường Đống Đa', 110, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (59, 49, '2034123', 'IOS Developer (App)', 18.00, 26.00, '1 năm', 'Nhân viên', '2026-04-14 19:07:55.655775', '2026-05-16 19:07:55.655775', 5, 'Phân tích yêu cầu nghiệp vụ/kỹ thuật, phát triển và bảo trì các ứng dụng iOS; tiếp nhận và phản hồi các yêu cầu thay đổi từ các thành viên trong team.Tối ưu hiệu năng (performance), độ ổn định và trải nghiệm người dùng (UX/UI) của ứng dụng.Nghiên cứu, đánh giá và áp dụng công nghệ mới để nâng cao chất lượng sản phẩm.Đề xuất giải pháp/ý tưởng cải tiến tính năng, tối ưu luồng người dùng, tăng tính thân thiện và hiệu quả sử dụng của sản phẩm.Tham gia code review, chuẩn hoá coding convention, đảm bảo chất lượng source code, khả năng mở rộng và dễ bảo trì.', 'Có khoảng 1–3 năm kinh nghiệm phát triển iOS bằng Swift, ưu tiên đã có app release thực tế (App Store/TestFlight) hoặc sản phẩm chạy production.Thiên hướng SwiftUI: nắm vững layout, navigation, state management (State/Binding/StateObject/ObservedObject), list/grid, reusable components, hỗ trợ Dark/Light mode.Hiểu nền tảng iOS: lifecycle, permission, background/foreground, xử lý tương thích nhiều iOS version; biết kết hợp SwiftUI với UIKit bridging (UIView Representable/UIViewController Representable) là lợi thế.Có kinh nghiệm kiến trúc theo hướng MVVM với SwiftUI; biết thêm Clean Architecture / MVI (Redux-style) là điểm cộng.Làm việc với networking & data: URLSession/Alamofire, Codable, cache/storage (UserDefaults/CoreData/Keychain là điểm cộng).Xử lý bất đồng bộ tốt với async/await (Swift Concurrency); biết Combine ở mức cơ bản là lợi thế; có ý thức tối ưu hiệu năng và tránh memory leak/crash.Biết/đã từng dùng Firebase (Crashlytics/Analytics/Remote Config) hoặc tool tương đương để theo dõi lỗi và đo lường sản phẩm là điểm cộng.Dùng Git ổn, làm theo quy trình branch/PR; chủ động nhận feedback và cải thiện.Điểm cộng:UI nâng cao: animation/transition, responsive layout nhiều kích thước màn hình, localizations.Xử lý media: AVFoundation (image/video), export/compose cơ bản.Realtime: WebSocket/streaming dữ liệu.Từng tích hợp StoreKit (IAP) và/hoặc ads (AdMob) là điểm cộng.Tư duy logic, chủ động, phối hợp tốt với team (Dev/UI/Tester/Backend), tự học nhanh và cập nhật công nghệ mới.', 'Thu nhập 18M-26M/thángCơ hội làm việc với sản phẩm app Global, người dùng trả phí thực tế.Lộ trình phát triển lên Senior IOS Developer.Môi trường làm việc linh hoạt, đề cao hiệu quả và trách nhiệm.Tham gia trực tiếp vào quá trình xây dựng sản phẩm từ đầu.Hưởng đầy đủ các chế độ theo quy định của pháp luật lao động.', '-Hà Nội:49 Thái Hà, Phường Đống Đa', 610, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (49, 43, '2029805', 'Quản Lý Khối Dự Án Chính Phủ / Project Manager - Offer Upto 60M - Hà Nội', 30.00, 60.00, '3 năm', 'Nhân viên', '2026-05-10 19:07:55.655775', '2026-06-21 19:07:55.655775', 5, 'Làm việc với cơ quan Nhà nước để khảo sát, làm rõ yêu cầu và mục tiêu dự án.Phối hợp Presales/Tech xây dựng giải pháp, kiến trúc tổng thể, phạm vi và lộ trình triển khai.Ước tính nguồn lực, chi phí, timeline và lập kế hoạch triển khai cấp cao.Soạn/đóng góp hồ sơ dự án: đề xuất kỹ thuật, thuyết minh giải pháp, SOW, kế hoạch dự án.Tham gia thuyết trình, demo, Q&A; hỗ trợ Sales trong đàm phán phạm vi và điều khoản.Thiết lập governance dự án, kế hoạch chi tiết, phân công nguồn lực và quản lý baseline.Điều phối đội dự án (Dev/BA/QA/Partner); theo dõi tiến độ, chất lượng, rủi ro, issue.Quản trị phạm vi, kiểm soát thay đổi (CR), quản lý deliverables và tài liệu dự án.Tổ chức phân tích – phát triển – tích hợp – SIT/UAT – đào tạo – chuyển đổi dữ liệu – go-live.Là đầu mối làm việc với chủ đầu tư, đơn vị sử dụng, ban QLDA; quản lý kỳ vọng và xử lý xung đột.Lập kế hoạch nghiệm thu, tổ chức UAT/đào tạo, bàn giao vận hành và theo dõi bảo hành/bảo trì theo SLA.Theo dõi ngân sách, kiểm soát chi phí; phối hợp Finance về nghiệm thu, xuất hóa đơn và công nợ.Tổng kết bài học kinh nghiệm; đề xuất chuẩn hóa quy trình, template, checklist cho khối chính phủ.', 'Kinh nghiệmTối thiểu 3 năm quản lý/điều phối dự án CNTT (PM/PMO/Delivery Lead).Ưu tiên có kinh nghiệm triển khai khối Nhà nước/chính phủ hoặc dự án có quy trình nghiệm thu – hồ sơ chặt chẽ.Có kinh nghiệm làm presale: khảo sát, estimate, lập proposal/SOW, demo/thuyết trình.Kiến thức/Chuyên mônHiểu quy trình triển khai phần mềm: phân tích – phát triển – kiểm thử – triển khai – vận hành.Nắm phương pháp quản lý dự án: Waterfall/Agile/Hybrid; quản lý change, risk, issue.Ưu tiên có chứng chỉ: PMP/PRINCE2/PMI-ACP/Scrum (không bắt buộc nhưng là lợi thế).Kỹ năngGiao tiếp & điều phối đa bên tốt; làm việc với stakeholder “nhiều tầng nấc”.Kỹ năng viết tài liệu (biên bản, báo cáo, kế hoạch, tài liệu nghiệm thu) rõ ràng, chuẩn mực.Đàm phán, xử lý xung đột, quản trị kỳ vọng.Tư duy hệ thống, chủ động, chịu áp lực deadline, sẵn sàng onsite/công tác.Phẩm chấtLiêm chính, kỷ luật, bảo mật thông tin.Tinh thần phục vụ (service mindset) nhưng kiên quyết về quản trị phạm vi & chất lượng.', 'Thu nhập thỏa thuận theo năng lực, trong khoảng từ 30M-60M trở lên, tùy theo năng lựcGói thu nhập 13 tháng + thưởng hiệu quả công việc năm + Thưởng hiệu quả dự ánPhụ cấp ăn trưa 35k/ngàyThưởng lễ tết theo quy định của công tyDu lịch 1 lần/năm trong nước hoặc ngoài nước', 'Trụ sở chính công ty', 988, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (50, 43, '2004934', 'Senior DevOps Engineer', NULL, 30.00, '3 năm', 'Nhân viên', '2026-04-14 19:07:55.655775', '2026-05-06 19:07:55.655775', 5, 'Infrastructure as Code (IaC): Quản lý toàn bộ hạ tầng (AWS/GCP) bằng code (Terraform/OpenTofu/Pulumi). Tuyệt đối không cấu hình thủ công (ClickOps).CI/CD & Automation: Thiết kế pipeline (GitHub Actions/GitLab CI) tích hợp tự động testing, security scanning và deployment. KPI: Thời gian từ Code Commit đến Production dưới 15 phút.Observability (SRE): Triển khai hệ thống giám sát sâu (Prometheus, Grafana, ELK, Datadog). Thiết lập cơ chế cảnh báo chủ động (Proactive Alerting) để xử lý sự cố trước khi ảnh hưởng đến người dùng cuối.FinOps & Cost Control: Trực tiếp quản lý ngân sách Cloud. Tối ưu tài nguyên (Spot Instances, Autoscaling) để cắt giảm lãng phí. Mục tiêu: Giảm 15-20% chi phí hạ tầng hàng năm.DevSecOps: "Shift-left" bảo mật vào quy trình CI/CD (SonarQube, Trivy). Quản lý secrets an toàn tuyệt đối qua Vault hoặc AWS Secrets Manager.', 'Bắt buộc (Must-have):Kinh nghiệm: 3+ năm vận hành hệ thống Production có lưu lượng truy cập lớn (High Traffic).Cloud: Am hiểu sâu kiến trúc AWS hoặc GCP (EC2/EKS/GKE, RDS, VPC, IAM).Kubernetes (K8s): Làm chủ K8s – có khả năng debug sâu (troubleshoot), tối ưu resource limits và scaling (không chỉ biết deploy cơ bản).Coding & Scripting: Tư duy lập trình tốt với Python hoặc Go để viết tool automation (vượt xa mức độ Bash shell scripting). Thành thạo Terraform.Điểm cộng (Nice-to-have):Tư duy Platform Engineering (sử dụng Backstage.io hoặc tự build internal tools).Ứng dụng AI Tools (GitHub Copilot, ChatGPT API) vào automation workflow.Tư duy "Security First" trong mọi thiết kế.', 'Upto 30M, tương xứng theo năng lực. (Có thể deal vượt mức 30M)Tham gia xây dựng sản phẩm công nghệ từ giai đoạn phát triển.WFH linh động, đánh giá theo hiệu quả công việc.Môi trường công nghệ, trao quyền, ít thủ tục.Cơ hội phát triển lên Senior Full-stack / Tech Lead.', 'Trụ sở chính công ty', 501, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (88, 75, '2028357', 'Graphic Designer', 9.00, 13.00, '1 năm', 'Nhân viên', '2026-04-28 19:07:55.655775', '2026-05-15 19:07:55.655775', 5, 'Xây dựng ý tưởng và thiết kế các sản phẩm truyền thông thương hiệu.Thiết kế các ấn phẩm quảng cáo, ấn phẩm cho sự kiện, sản phẩm quảng cáo online… Phối hợp với các phòng ban khác lên ý tưởng cho từng loại sản phẩm phù hợp.Chủ động nắm bắt các xu hướng hiện tại và cập nhật các xu hướng thiết kế mới để tối ưu design quảng cáo, khuyến mại, event,....Đảm bảo tiêu chuẩn thiết kế, tuân thủ quy trình làm việc của team thiết kếThực hiện các công việc khác theo sự phân công của công ty.', 'Ít nhất 1 năm kinh nghiệm Thiết kế đồ họaĐộ tuổi từ 22 - 30Có sự sáng tạo và nền tảng vững chắc về thiết kế, thẩm mĩ,..Thành thạo phần mềm thiết kế Adobe Photoshop, Illustrator và các phần mềm hỗ trợ liên quanNhạy cảm với thị trường và thấu hiểu tâm lý, hành vi của khách hàng Âu MỹCó kinh nghiệm thiết kế các sản phẩm POD là lợi thếHòa đồng, có khả năng teamwork', 'Mức lương thỏa thuận theo năng lực.Performance review hàng năm.Môi trường có văn hóa "Mở", mọi người đều được thoải mái feedback, đưa ra ý kiến đóng góp.Được tư vấn và chia sẻ về phát triển năng lực và nghề nghiệp bản thân.Hưởng các chế độ, phúc lợi: Lương tháng 13; Thưởng lễ tết, thưởng thâm niên; 12 ngày phép năm; Phúc lợi và phụ cấp khác; BHXH, BHYT, BHTN.Phí đỗ xe miễn phí trong tòa nhà.Sử dụng miễn phí đồ uống tại khu sinh hoạt của Công ty.Được cung cấp máy tính để bàn, đồ dùng văn phòng cần thiết.Hoạt động nội bộ: du lịch hàng năm, teambuilding (hàng quý), liên hoan sinh nhật (hàng tháng).Tham gia các Câu lạc bộ của Công ty: CLB bóng đá, CLB cầu lông, CLB pickleball, CLB yoga…………..', '-Hà Nội:đường Nguyễn Cơ Thạch, Mỹ Đình 1, Phường Từ Liêm', 948, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (159, 139, '2009960', 'Graphic Design - Thiết Kế Đồ Họa Thời Trang', 9.00, 12.00, '1 năm', 'Nhân viên', '2026-05-04 19:07:55.655775', '2026-05-21 19:07:55.655775', 5, '1. Thiết kế banner, ấn phẩm truyền thông cho website, tiktokshop, shopee, social2. Thiết kế sản phẩm (mockup thời trang)3. Tham gia và tư vấn vào các buổi chụp ảnh của công ty', 'Kinh nghiệm tối thiểu 1 năm trong lĩnh vực thiết kếTư duy sáng tạo, hiện đại trong thiết kếHiểu biết về thời trang, thể thao là 1 lợi thế lớn', 'Được đóng BHXH sau thử việcThưởng nóng theo hiệu quả công việcMôi trường làm việc trẻ, năng động và được cập nhật kiến thức mới nhất trong ngành đang Hot là Thương Mại Điện TửNghỉ Lễ, Tết, lương tháng 13Review lương theo năng lực', 'Trụ sở chính công ty', 255, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (10, 2, '1711994', 'Data Analyst (Fresher)', 8.00, 10.00, 'Dưới 1 năm', 'Nhân viên', '2026-05-06 19:07:55.655775', '2026-05-25 19:07:55.655775', 5, 'Analyze user data, gameplay behavior, revenue metrics, and marketing performance.Design and build automated reports and dashboards using tools such as Google Sheets, Looker Studio, Power BI, etc.Write and optimize BigQuery queries for data extraction and analysis purposes.Process, normalize, and validate data using Python (pandas, numpy, etc.) when necessary.Collaborate closely with Product and Marketing teams to define analytical questions and generate valuable insights.Propose product improvement initiatives based on data-driven analysis.Participate in brainstorming sessions and internal discussions to share ideas and insights.', '6 months to 1 year of experience, or fresh graduates are welcome.Proficiency in Google Sheets (advanced functions, pivot tables, vlookup, filter, etc.).Experience querying databases using BigQuery or similar database management systems (basic to intermediate SQL: SELECT, JOIN, GROUP BY, CTE, etc.).Ability to use Python for basic data processing tasks (pandas, file I/O, simple APIs).Strong data visualization and presentation skills (using Google Sheets, Google Data Studio, Looker Studio, or similar tools).Basic understanding of Firebase Analytics and event-based data is a plus.Highly responsible, proactive, detail-oriented, and meticulous.Good communication skills and willingness to work within a large team.Strong critical thinking skills.', 'Attractive salary package + Project bonus + Performance bonus and other bonus on Public HolidaySalary review twice a yearTet bonus upto 03 month salary 7,5 working hour per day; 05 days per week12 Annual leave per yearPeriodic Health check; Health insurance package02 company trips per year, team building activities,…', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (8, 2, '2032555', 'Unity Developer (Junior)', NULL, NULL, '1 năm', 'Nhân viên', '2026-04-14 19:07:55.655775', '2026-05-21 19:07:55.655775', 5, 'Program and implement game features.Design and develop user interfaces and in-game logic.Take ownership of Hyper-casual game projects or provide support for larger-scale game projects.Collaborate with other teams and propose ideas to improve the productParticipate in brainstorming sessions and share ideas during internal discussions.', 'Minimum of 1 year of professional experience.Hands-on experience with Unity-based projects.Strong proficiency in Unity, C#, and related technologies.Passionate about and enthusiastic towards mobile gaming.Strong logical thinking, creativity, and a desire for continuous learning and self-improvement.Proactive, responsible, and highly committed to work.Ability to work independently as well as collaboratively within a team.Basic English skills for work-related communication.', 'Competitive salary package with monthly project revenue bonuses.Full participation in social insurance schemes in accordance with company policies.Salary reviews twice a year.Daily lunch allowance.Company trips twice a year.Regular team-building activities and internal company events.Special bonuses on holidays, Tet (Lunar New Year), and birthdays.12 days of annual leave per year.Tet bonus of up to 3 months’ salary.Annual health check-ups and more.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (89, 76, '1858496', 'Thực Tập Sinh Kinh Doanh Phần Mềm Website App', NULL, NULL, 'Không yêu cầu', 'Nhân viên', '2026-04-23 19:07:55.655775', '2026-05-12 19:07:55.655775', 7, '- Theo hướng dẫn của Team Leader, tìm kiếm thông tin khách hàng từ nhiều nguồn trên Internet.- Tìm kiếm và tạo mạng lưới khách hàng tiềm năng (online và offline)- Chăm sóc các khách hàng lớn và khách hàng cũ của công ty- Phát triển khách hàng đang có và mở rộng mô hình chiến lược kinh doanh cho khách hàng- Khảo sát nhu cầu của khách hàng và thúc đẩy họ tìm hiểu thêm về các công cụ kinh doanh online mà Công ty đang cung cấp- Được hướng dẫn và đào tạo trực tiếp khi làm việc', '- Ưu tiên sinh viên năm 4 đang kiếm đơn vị thực tập- Nhiệt tình, chịu khó, lịch sự trong giao tiếp công sở.- Giao tiếp tốt và có khả năng tư vấn khách hàng qua điện thoại và trực tiếp.- Có kinh nghiệm liên quan đến tư vấn, chăm sóc khách hàng là một lợi thế- Khả năng làm việc độc lập và đội nhóm tốt.- Giao tiếp Tiếng Anh khá là một lợi thế.', '- Thu nhập: từ 6.000.000 - 15.000.000đ + Thưởng- Thu nhập không giới hạn, tùy thuộc vào năng lực.- Cơ chế thưởng rõ ràng, chế độ BHXH đầy đủ cho nhân viên chính thức.- Được đào tạo, tham gia huấn luyện để trở thành những chuyên gia tư vấn trong lĩnh vực phần mềm và website.- Cơ hội tiếp xúc và làm việc, mở rộng các mối quan hệ trong lĩnh vực công nghệ, Cơ hội thăng tiến rộng mở.- Được làm việc trong môi trường 9x năng động, thân thiện, cởi mở.- Được tham gia teambuilding, du lịch hàng quý do công ty tổ chức.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (90, 76, '1856269', 'Thực Tập Sinh Kinh Doanh Phần Mềm Website', 6.00, 15.00, 'Không yêu cầu', 'Nhân viên', '2026-05-03 19:07:55.655775', '2026-05-24 19:07:55.655775', 7, '- Theo hướng dẫn của Team Leader, tìm kiếm thông tin khách hàng từ nhiều nguồn trên Internet.- Tìm kiếm và tạo mạng lưới khách hàng tiềm năng (online và offline)- Chăm sóc các khách hàng lớn và khách hàng cũ của công ty- Phát triển khách hàng đang có và mở rộng mô hình chiến lược kinh doanh cho khách hàng- Khảo sát nhu cầu của khách hàng và thúc đẩy họ tìm hiểu thêm về các công cụ kinh doanh online mà Công ty đang cung cấp- Được hướng dẫn và đào tạo trực tiếp khi làm việc', '- Ưu tiên sinh viên năm 4 đang kiếm đơn vị thực tập- Nhiệt tình, chịu khó, lịch sự trong giao tiếp công sở.- Giao tiếp tốt và có khả năng tư vấn khách hàng qua điện thoại và trực tiếp.- Có kinh nghiệm liên quan đến tư vấn, chăm sóc khách hàng là một lợi thế- Khả năng làm việc độc lập và đội nhóm tốt.- Giao tiếp Tiếng Anh khá là một lợi thế.', '- Thu nhập: từ 6.000.000 - 15.000.000đ + Thưởng- Thu nhập không giới hạn, tùy thuộc vào năng lực.- Cơ chế thưởng rõ ràng, chế độ BHXH đầy đủ cho nhân viên chính thức.- Được đào tạo, tham gia huấn luyện để trở thành những chuyên gia tư vấn trong lĩnh vực phần mềm và website.- Cơ hội tiếp xúc và làm việc, mở rộng các mối quan hệ trong lĩnh vực công nghệ, Cơ hội thăng tiến rộng mở.- Được làm việc trong môi trường 9x năng động, thân thiện, cởi mở.- Được tham gia teambuilding, du lịch hàng quý do công ty tổ chức.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (18, 9, '1975771', 'Presale Engineer (Intelligent Transport Systems)', NULL, NULL, '2 năm', 'Nhân viên', '2026-04-11 19:07:55.655775', '2026-05-04 19:07:55.655775', 5, 'Vị trí Kỹ sư giải pháp là cầu nối giữa khách hàng, Khối kinh doanh, Trung tâm R&D, Triển khai, Hãng công nghệ,... để xây dựng giải pháp, tối ưu sản phẩm. Vai trò này chịu trách nhiệm đảm bảo các giải pháp trong hệ sinh thái Giao thông thông minh được tư vấn, thiết kế và trình bày tối ưu, phù hợp nhất với nhu cầu thực tế của khách hàng.Nghiên cứu, xây dựng giải pháp cho các hệ thống ITS: ETC, WIM, Điều khiển đèn tín hiệu, ITS nội đô, ITS cao tốcThu thập và phân tích các yêu cầu kinh doanh và kỹ thuật từ khách hàng, bao gồm: Edge Devices, Servers, Storage, Network, Licenses, AI Analytics, etc.- Tư vấn các giải pháp phù hợp cho từng bài toán của khách hàng- Thiết kế các giải pháp kỹ thuật: sơ đồ kiến ​​trúc hệ thống (cấu trúc liên kết), tính toán tài nguyên (kích thước máy chủ, băng thông, lưu trữ) và lựa chọn danh sách thiết bị phù hợp.Phối hợp với Bộ phận Kinh doanh để chuẩn bị BoQ, Đề xuất, Báo cáo Đề xuất Đầu tư, Báo cáo Nghiên cứu Khả thi, Hồ sơ Mời thầu, v.v.Tham gia các buổi thuyết trình sản phẩm cho khách hàng và đối tác tại các buổi Demo, Hội thảo, POC, Pilot, v.v.Phối hợp và đồng hành với đội ngũ kinh doanh, marketing để xây dựng tài liệu sản phẩm phục vụ cho việc đưa sản phẩm ra thị trường và marketing.Phát triển và duy trì các chiến lược để phát triển hệ sinh thái đối tác đáng tin cậy, mở rộng hợp tác với các nhà cung cấp, nhà phân phối để đảm bảo nguồn lực ổn định, tối ưu hóa năng lực cung ứng và nâng cao khả năng cạnh tranh của giải pháp.', 'Tốt nghiệp đại học chuyên ngành CNTT, Điện tử Viễn thông, Tự động hóa hoặc các ngành liên quan.Có kiến thức hoặc kinh nghiệm trong một trong các mảng:- ETC: RFID, camera LPR, thiết bị làn thu phí, barrier, cảm biến.- WIM: cảm biến cân động- Đèn tín hiệu giao thông, ITS nội đô, cao tốc: là 1 lợi thế.Am hiểu kiến trúc hệ thống ITS: camera, radar, server, network, NVR/VMS, bảo mật và truyền dẫn dữ liệu.Thành thạo trong việc soạn thảo Proposal, tài liệu giải pháp, tài liệu kỹ thuật.Nhạy bén, có thiên hướng làm việc với đối tác/khách hàng tốt. Tư duy phân tích tốt, khả năng giải quyết vấn đề nhanh và logic.Kỹ năng giao tiếp và trình bày xuất sắc; tiếng Anh tốt là lợi thế.', 'LÝ DO ĐỂ ĐỒNG HÀNH VỚI ELCOMVới truyền thống 30 năm hình thành phát triển, Elcom chắc chắn sẽ là nơi làm việc khiến bạn an tâm gắn bó lâu dài, với:Sự tiên phong trong công nghệ và tin tưởng  trao quyền:Business phát triển bền vững, trải qua 30 năm tuổi, doanh thu và quy mô không ngừng tăng.Cơ hội làm việc trực tiếp với các hãng đối tác công nghệ lớn. Nghiên cứu nhiều sản phẩm đa dạng và đội ngũ nhân sự giỏi, nhiều chuyên gia trong lĩnh vực.Môi trường thân thiện, chia sẻ, đồng hành:Môi trường CNTT năng động, thân thiện, cởi mở, tôn trọng sự khác biệt và đề cao sáng tạo, Elcomers được làm chủ công việc và tận hưởng thành quả đạt được. Minh bạch, thẳng thắn trao đổi thống nhất với cấp trên trong suốt quá trình làm việc và các đợt review năng lực hàng nămNền tảng vững chắc cho phát triển sự nghiệp, thăng tiến, quyền lợi:Thu nhập cạnh tranh: Lương theo năng lực, thưởng sáng kiến, thưởng các dịp lễ và từ lợi nhuận công ty. Tổng thu nhập 1 năm lên tới 15 tháng lương.Phúc lợi cao cấp:- Bảo hiểm sức khỏe cho bạn & người thân (tới $6.000/người)- Khám sức khỏe định kỳ tại bệnh viện hàng đầu- Ăn trưa miễn phí tại văn phòng- Được hưởng toàn bộ các quyền lợi theo Luật lao động ban hành về chế độ tham gia bảo hiểm xã hội, nghỉ lễ, nghỉ phép năm.- Các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và Thân nhân…Văn hóa gắn kết – truyền cảm hứng:Du lịch, teambuilding, sự kiện công ty tại resort cao cấpCâu lạc bộ thể thao, âm nhạc, hoạt động cộng đồng ý nghĩa (“Trăng sáng yêu thương”, “Cơm có thịt”…)Thời gian làm việc: thứ 2 đến thứ 6.Tại ELCOM, chúng tôi không chỉ tìm một Kỹ sư giải pháp – chúng tôi tìm một người đồng đội, một nhà kiến tạo giải pháp và một đối tác tin cậy cho khách hàng. Nếu bạn muốn tạo dấu ấn trong ngành công nghệ và đóng góp cho những dự án mang tầm ảnh hưởng quốc gia, hãy gia nhập với chúng tôi.', 'Trụ sở chính công ty', 35, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (20, 11, '2037041', 'Senior AI_Natural Language Processing Engineer', NULL, 40.00, '2 năm', 'Nhân viên', '2026-04-30 19:07:55.655775', '2026-05-24 19:07:55.655775', 5, 'Architect and Develop Advanced NLP Models: Pioneer cutting-edge solutions for a range of educational applications, including:Automated Scoring & Feedback: Design systems for instant and accurate scoring of essays, pronunciation, grammar, and vocabulary.Intelligent Learning Assistants: Build sophisticated AI tutors and conversational agents that can understand student queries, provide contextual explanations, and guide them through their learning journey.Robust Speech Technologies: Implement and fine-tune state-of-the-art Speech-to-Text (S2T) and Text-to-Speech (T2S) models to create immersive practice environments.Pioneer our AI Conversation Partner: Build the core AI for a virtual speaking partner, designed specifically to help users build real-world communication skills through interactive, realistic dialogues with instant coaching.Research & Implementation: Stay at the forefront of AI research, experimenting with and applying the latest techniques (e.g., Transformers, Large Language Models) to solve unique challenges in language education.Collaborate and Ship: Work closely with product managers, software engineers, and language experts to integrate your AI models into our products, ensuring they are scalable, efficient, and deliver tangible value to our users.', 'Hard Skills Requirements:Bachelor''s or Master''s degree in Computer Science or related fields.At least 2 years of experience in the field of Natural Language Processing (NLP).Proficient in programming languages, especially Python (knowledge of C/C++ is an advantage), and capable of using frameworks such as Tensorflow, Keras, PyTorch.Expertise in building, analyzing data, training, and optimizing NLP models.Experience in model serving (using RayServe, Triton, TorchServe, etc.) and service integration and deployment is an advantage.Significant experience with Large Language Models (LLM) is a major advantage.Proficient use of Git, Docker.Experience with data organization systems: Database (Postgres, MySQL), Cache (Redis), Queue (RabbitMQ, Kafka) is an advantage.Ability to comprehend technical documents, scientific articles, and stay up-to-date with the State of The Art (SOTA).Strong analytical and problem-solving skills.Soft Skills Requirements:High enthusiasm and responsibility.Good communication skills, proactive, flexible at work, collaborative, and friendly within the team.Careful in work and considerate of customers.Fluency in English and Chinese is an advantage.', 'Salary: Up to 40 million VND.KPI bonus based on work results and company revenue (2-4 million/month), paid in monthly salary.Flexible working hours, a youthful and dynamic work environment.Health insurance, team building activities, annual vacations.Social insurance and health insurance provided in accordance with state regulations.Benefits include birthday celebrations, compassionate leave, year-end party, summer holiday,...Health insurance card (PVI) with inpatient and outpatient benefits issued upon becoming a full-time employee.Opportunity to work in a creative, young, and dynamic environment.Friendly colleagues, opportunities for learning and career advancement.FREE enrollment in one English or Chinese courseNote:By submitting a CV/Resume, along with the information provided by the applicant, and any exchanges during the interview process with Prep (if applicable), the applicant AGREES to Prep''s Privacy Policy and the handling of personal data, which is established and issued in accordance with Decree No. 13/2023/NĐ-CP on personal data protection. Additionally, the applicant agrees to allow Prep to collect and store the information provided for the following purposes:×         Collecting personal data and selecting candidates for interviews;×         Contacting and notifying the applicant;×    Assessing the applicant''s suitability to select the appropriate candidate for the company''s current position.', 'Trụ sở chính công ty', 132, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (93, 79, '1478077', 'Nhân Viên Thiết Kế', 15.00, 20.00, '1 năm', 'Nhân viên', '2026-04-19 19:07:55.655775', '2026-05-12 19:07:55.655775', 12, 'Tham gia vào quá trình thiết kế sản phẩm, bao bì, ấn phẩm quảng cáo, banner, poster, logo, ... cho các sản phẩm của công ty.Thực hiện các công việc thiết kế theo yêu cầu của trưởng nhóm, giám sát thiết kế.Nghiên cứu, tìm hiểu xu hướng thiết kế mới, cập nhật kiến thức, kỹ năng thiết kế.Hỗ trợ các bộ phận khác trong công ty về các vấn đề liên quan đến thiết kế.', 'Tốt nghiệp chuyên ngành Thiết kế đồ họa, Mỹ thuật công nghiệp hoặc các ngành nghề liên quan.Sử dụng thành thạo các phần mềm thiết kế đồ họa như Photoshop, AI, CorelDRAW.Có khả năng sáng tạo, nắm bắt nhanh xu hướng thiết kế mới.Có khả năng làm việc độc lập và làm việc nhóm.Có tinh thần trách nhiệm cao, cẩn thận, tỉ mỉ trong công việc.', 'Mức lương hấp dẫn, phù hợp với năng lực và kinh nghiệm.Ký túc xá 3 sao cho nhân viên ở xaĐóng 100% bảo hiểm từ tháng thử việc đầu tiênĐược tham gia các chương trình đào tạo nâng cao kỹ năng chuyên môn.Được hưởng đầy đủ các chế độ phúc lợi theo quy định của pháp luật.Môi trường làm việc năng động, chuyên nghiệp, thân thiện.', 'Trụ sở chính công ty', 4, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (15, 6, '1301020', 'Unity Developer Game - Thu Nhập Từ 18-25 Triệu (Deal Theo Năng Lực) - Tối Thiểu 3 Năm Làm Game Mobile Với Unity', 18.00, 25.00, '3 năm', 'Nhân viên', '2026-04-28 19:07:55.655775', '2026-06-09 19:07:55.655775', 5, 'Core-gameplay Development: Trực tiếp thiết kế và triển khai các hệ thống gameplay, core mechanics cho các dự án 3D Hybrid Casual trên nền tảng Mobile (Android & iOS).Game Juice & Aesthetics: Chăm chút từng chuyển động (Animation timing), hiệu ứng (Particle) và phản hồi vật lý. Trực tiếp setup ánh sáng (Lighting) và tinh chỉnh môi trường 3D để đảm bảo thị giác sản phẩm đạt chất lượng cao nhất.Optimization: Chịu trách nhiệm chính trong việc kiểm soát hiệu năng (CPU, GPU, Memory). Xử lý các bài toán Draw calls, Frame-rate và tối ưu dung lượng bộ cài.Collaboration: Phối hợp cùng Game Designer, Artist và Product Owner để chuyển hóa ý tưởng thành sản phẩm thực tế, đảm bảo sự cân bằng giữa tính thẩm mỹ và hiệu suất kỹ thuật.Data Analysis: Phân tích các chỉ số vận hành (Retention, Playtime, Drop-rate) để chủ động đề xuất các giải pháp cải thiện UX/UI và tính năng.', 'Kinh nghiệm: Tối thiểu 3 năm làm Game Mobile với Unity. Đã từng tham gia ít nhất 3 sản phẩm Global đã phát hành (Ưu tiên vị trí Key Member/Lead Logic).Chuyên môn 3D & Lighting:   - Am hiểu về Universal Render Pipeline (URP).   - Thành thạo kỹ thuật Lighting Bake (Lightmaps, Light Probes) và xử lý môi trường 3D sao cho tối ưu nhất cho Mobile.Hiểu biết về Shader, Post-processing và cách tạo ra "Game Juice" (độ mượt, feedback thị giác).Kỹ năng Tối ưu (Optimization Mastery):   - Sử dụng thành thạo Unity Profiler & Frame Debugger để tìm và giải quyết các vấn đề về hiệu suất.   - Kiểm soát tốt Draw calls, Batches (Static/Dynamic Batching, GPU Instancing).   - Tư duy code tối ưu: Quản lý bộ nhớ tốt, hạn chế GC, thành thạo Object Pooling.Tư duy lập trình & Vibe Coding:   - Nắm vững OOP, Design Patterns và xây dựng kiến trúc code linh hoạt (Clean Code).   - High-speed Productivity: Có tư duy "Vibe Coding" – ưu tiên ứng viên nhạy bén với các công cụ hỗ trợ AI (như Cursor, GitHub Copilot) và các workflow mới để tối ưu tốc độ triển khai dự án mà vẫn đảm bảo chất lượng logic.   - Tech-savvy: Chủ động cập nhật và thực hành các công nghệ/thư viện mới nhất (như Addressables, các bộ Tooling tối ưu hoặc xu hướng AntiGravity trong lập trình) để giải quyết vấn đề thay vì chỉ đi theo các lối mòn cũ.Ứng viên Junior (High-potential): Chỉ xem xét nếu có Portfolio 3D ấn tượng, tư duy Logic/Math tốt và chứng minh được khả năng "feel game" xuất sắc qua các sản phẩm cá nhân.ĐIỂM CỘNG- Đã từng làm các dự án Hybrid Casual có chỉ số tốt trên thị trường.- Có kinh nghiệm về LiveOps, hiểu về logic quảng cáo (Ads) và In-app Purchase (IAP).- Đọc hiểu tài liệu tiếng Anh chuyên ngành tốt.', 'Thu nhậpMức lương: Lên đến 18-25 triệu /tháng Review Lương 2 lần/nămPhụ cấp ăn trưa cho nhân viên chính thứcThu nhập gắn liền với hiệu suất và kết quả công việcCơ hội phát triểnMở rộng và nâng cao kiến thức, kỹ năng chuyên môn trong lĩnh vực Art và AITrực tiếp tham gia các dự án game toàn cầuLộ trình phát triển nghề nghiệp cá nhân hóa, rõ ràng theo từng giai đoạnMôi trường làm việcMôi trường startup, trẻ trung, năng động, sáng tạo và có khả năng phát triển vượt bậc;Con người là trên hết - bạn sẽ được trang bị đầy đủ trang thiết bị, bữa xế chiều, tủ pantry đầy đồ ăn vặt,...Chính sách phúc lợiĐóng đầy đủ BHXH, BHYT, BHTN theo quy định pháp luậtThưởng linh hoạt & hấp dẫn: Thưởng lễ, Thưởng Tết dương lịch, 8/3, 30/4–1/5, Trung thu, 2/9, 20/10, Giáng sinh, lương tháng thứ 13 theo doanh thu sản phẩm và theo mức độ đóng góp vào dự án;Thời gian làm việc: từ T2-T6, nghỉ T7 & CN (không OT).', 'Trụ sở chính công ty', 403, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (78, 68, '1914773', 'Business Analyst -Từ 03 Đến 05 Năm Kinh Nghiệm Trở Lên - Lương Upto 26 Triệu - Quận Hà Đông (Hà Nội)', NULL, 26.00, '3 năm', 'Nhân viên', '2026-04-26 19:07:55.655775', '2026-05-23 19:07:55.655775', 5, '- Xây dựng kế hoạch phát triển sản phẩm.- Nghiên cứu tính năng cho sản phẩm mới.- Hỗ trợ xây dựng Mockup (bản design đơn giản).- Vẽ user flow, viết specification với các tính năng. - Theo dõi tiến độ dự án hàng ngày, đảm bảo hoàn thành đúng deadline & yêu cầu.- Thống kê, hoàn thiện tài liệu trước khi phát hành sản phẩm.', '- Tuổi từ 22 - 30, làm việc full time. - Có từ 3 - 5 năm kinh nghiệm ở vị trí tương đương mảng e-commerce, phần mềm.- Đọc hiểu Tiếng Anh ở mức tốt.- Có tư duy tốt về việc làm sản phẩm, hiểu nhu cầu của khách hàng.- Có kỹ năng phân tích, xử lý tình huống và ra quyết định.- Kỹ năng tổ chức công việc và quản lý thời gian hiệu quả.- Học ngành thương mại điện tử, kỹ thuật phần mềm là một lợi thế.', '1. Lương, thưởng và phụ cấp: - Thu nhập theo thỏa thuận, tương xứng với năng lực và hiệu quả làm việc: Upto 26.000.000; Review lương 2 lần/năm.- Thưởng nóng, thưởng quý, thưởng lễ Tết, lương tháng 13.- Phụ cấp gửi xe, phụ cấp đi lại theo quy định công ty.- Cung cấp trang thiết bị làm việc đầy đủ, hiện đại (PC / Laptop,...). 2. Phúc lợi và đãi ngộ:- Được làm việc trong môi trường trẻ trung, thân thiện, nhiệt tình, chuyên nghiệp và có nhiều cơ hội thăng tiến.- Văn phòng làm việc tiện nghi với không gian mở; Pantry luôn đầy ắp trà, cafe, bánh kẹo được refill hàng ngày.- Tham gia các hoạt động thể thao / văn nghệ: CLB chạy bộ, đá bóng, cầu lông, board game, PS5, văn nghệ,... sau giờ làm việc.- Tham gia các hoạt động sự kiện được tổ chức hàng tuần / tháng: Happytime, sinh nhật, tổng kết, dã ngoại, trekking...- Hưởng đầy đủ các chế độ phúc lợi như BHXH, ngày nghỉ phép, du lịch hàng năm, thăm hỏi ốm đau, hiếu hỷ, thai sản, khám sức khỏe định kỳ, ... 3. Đào tạo và phát triển:- Được Leader training trực tiếp các kiến thức, kỹ năng cần thiết cho công việc.- Được tham gia các khóa học đào tạo về kỹ năng phát triển con người và kỹ năng chuyên môn.- Cơ hội được thể hiện và phát huy năng lực của bản thân, tham gia hoạt động Workshop trao đổi chuyên môn thường xuyên cùng đội nhóm để nâng cao kiến thức, năng lực.', 'Trụ sở chính công ty', 565, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (23, 13, '2031846', 'BUSINESS DEVELOPMENT (BFSI/Technology) [All Level]', NULL, NULL, '3 năm', 'Nhân viên', '2026-05-02 19:07:55.655775', '2026-06-09 19:07:55.655775', 5, 'A. Business Development (B2B Direct Sales)Develop and manage enterprise customers in Banking, Financial Services, FinTech, and Enterprise sectors.Proactively identify, approach, qualify, and convert leads into business opportunities.Present and sell technology solutions, including: Secure Payment, Open Banking/Open Finance, Cyber Security, IAM/CIAM, Fraud Prevention & Risk Management, PKI, Paperless, Digital Trust, MFA/FIDO2, etc.Work closely with Presales / Technical teams to:- Prepare proposals and respond to RFP/RFI- Conduct product demos and Proof of Concept (POC)Manage the full B2B sales cycle: Lead → Opportunity → Proposal → Negotiation → Contract signing.Build and maintain strong relationships with C-level executives and key decision makers.B. Channel Sales & PartnershipDevelop and manage channel partners, including:System Integrators (SI), Distributors, IT Services/Consulting firms, FinTech & Technology partners.Enable partners through training, pitching, positioning, and joint go-to-market activities.Track channel sales pipeline, forecast revenue, and support partners in deal execution and closure.C. Market & ReportingAnalyze the BFSI market, customer needs, and competitive landscape.Propose sales strategies, target accounts, and channel priorities.', 'Minimum 3 years of experience in Business Development, B2B Sales, or Channel Sales roles (Open for level Junior/Midle/Senior);Proven experience selling IT solutions, software, SaaS, security, FinTech, or enterprise solutions.Experience working with banks, financial institutions, or large enterprises is a strong advantage.Strong skills in:- B2B sales and pipeline management - Negotiation and deal closing- Partner and channel managementAbility to pitch and communicate in English with local and international clients.Capable of working independently and collaborating cross-functionally (Sales, Presales, Technical, Legal).Good communication skills in both Vietnamese and English.', 'Extremely attractive salary, commensurate with your ability and experience;Annual performance reviews and salary increases; year-end business bonuses, project bonuses, performance bonuses, and holiday bonuses throughout the year;Opportunities to demonstrate your capabilities, take ownership of your work, and advance your career;Chance to work with leading technology experts and major global tech corporations;A young, dynamic, and open-minded working environment that encourages self-expression and offers a variety of fun and engaging activities;Monthly birthday celebrations and gifts for employees, along with annual health check-ups;Full social insurance, health insurance, and unemployment insurance according to state regulations;Annual teambuilding trips, company anniversary Olympics, Year-End Party, Vietnamese Women’s Day (20/10) celebrations, and many other unique cultural activities;Spacious pantry area for relaxation, meals, and internal events;And many more exciting career opportunities await you!', 'Trụ sở chính công ty', 319, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (16, 8, '2029764', 'Web Developer Intern', 2.00, 2.40, 'Không yêu cầu', 'Nhân viên', '2026-05-16 19:07:55.655775', '2026-06-18 19:07:55.655775', 7, 'Assist in developing and maintaining web application components under supervision.Support the implementation of new features and basic enhancements for company products.Collaborate with Developers, Business Analysts, and QC teams to understand requirements and technical specifications.Follow established software development processes, coding standards, and best practices.Participate in coding, testing, debugging, and refactoring tasks.Perform basic unit testing and self-testing before submitting work.Support the optimization of application performance and usability.Write clear, concise, and well-documented code.Learn and apply modern development practices and tools.Research technologies or solutions as assigned.Manage assigned tasks within agreed timelines and report progress regularly.', 'University student majoring in Information Technology, Computer Science, or related fields.Basic knowledge of programming fundamentals.Familiarity with web technologies: HTML, CSS, and JavaScript.Basic understanding of web application concepts and REST APIs.Awareness of version control systems (Git).Basic English skills.Willingness to learn new technologies and frameworks.Good analytical thinking and problem-solving skills.Strong sense of responsibility and teamwork spirit.', 'Hỗ trợ phụ cấp thực tập Full-time: 2.000.000 VND/tháng và chi phí gửi xe: 400.000 VND/tháng.Tham gia các chương trình đào tạo (kỹ năng chuyên môn, kỹ năng giao tiếp) và các event nội bộ của công ty.Hỗ trợ dấu mộc thực tập (nếu có nhu cầu).Môi trường năng động, chuyên nghiệp, cơ hội làm việc và học tập liên quan đến kiến thức đầu tư, trực tiếp từ các chuyên gia trong ngành chứng khoán.', 'Trụ sở chính công ty', 801, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (95, 82, '2037235', 'Chuyên Viên Media Kiêm Thiết Kế, Quay Dựng', 17.00, 25.00, '3 năm', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-19 19:07:55.655775', 11, 'Lên ý tưởng, thiết kế ấn phẩm truyền thông (poster, banner, backdrop, POSM, social post...) phù hợp với định hướng thương hiệu.Quay video, chụp ảnh phục vụ cho chiến dịch truyền thông, quảng cáo, sự kiện.Dựng, chỉnh sửa video (TV, social, viral clip, reel, Tiktok…) đảm bảo sáng tạo và chất lượng. Phối hợp cùng team Marketing triển khai nội dung, đảm bảo hình ảnh nhất quán và hấp dẫn.Quản lý kho tư liệu hình ảnh, video; đề xuất cải tiến phong cách hình ảnh truyền thông.Phối hợp với các bộ phận khác để phát triển chương trình truyền thông có sự tham gia của các đối tác chiến lược.Chịu trách nhiệm hiệu quả sản phẩm thiết kế in ấn, quay dựng sản phẩm truyền thông trước và sau khi triển khai.Soạn thảo, biên tập quản lý các tư liệu media nội dung truyền thông, bao gồm hình ảnh, video, v.v. Đảm bảo tính nhất quán trong thông điệp truyền thông của công ty.Tạo ra các tài liệu truyền thông giúp nâng cao nhận diện thương hiệu của công ty', 'Tốt nghiệp Cao đẳng, Đại học chuyên ngành Thiết kế đồ họa hoặc các ngành liên quan.Có ít nhất 3 năm kinh nghiệm làm việc trong lĩnh vực thiết kế đồ họa.Sử dụng thành thạo các phần mềm thiết kế Adobe Creative Suite (Photoshop, Illustrator, InDesign), Figma hoặc các công cụ thiết kế khác.Có kiến thức về in ấn, chất liệu, kỹ thuật gia công.Có khả năng tư duy sáng tạo, thẩm mỹ tốt, có gu thiết kế hiện đại.Có khả năng làm việc độc lập và làm việc nhóm tốt.Chủ động, nhiệt tình, có trách nhiệm với công việc.Có khả năng quản lý thời gian và hoàn thành công việc đúng hạn.Có kinh nghiệm thiết kế UI/UX là một lợi thế.', 'Môi trường làm việc năng động, sáng tạo và chuyên nghiệp.Cơ hội được học hỏi, phát triển bản thân và nâng cao tay nghề.Tham gia các khóa đào tạo chuyên môn và kỹ năng.Được hưởng đầy đủ các chế độ bảo hiểm theo quy định của pháp luật.Chế độ nghỉ phép, nghỉ lễ theo quy định.Các hoạt động teambuilding, du lịch hàng năm.Cơ hội thăng tiến và phát triển sự nghiệp.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (87, 74, '1336336', 'Video Editor - Xây Dựng Kênh Youtube', 8.00, 15.00, 'Dưới 1 năm', 'Nhân viên', '2026-04-15 19:07:55.655775', '2026-05-26 19:07:55.655775', 1, '- Chỉnh sửa, biên tập video theo kế hoạch đã lên- Phối hợp với team Content để dựng video theo kịch bản có sẵn.- Thực hiện công việc theo sự phân công của quản lý.', '- Kinh nghiệm:  <1 năm (Được đào tạo nếu yêu thích Edit)- Sử dụng thành thạo bất kỳ phần mềm chỉnh sửa video nào: Adobe Premiere, Capcut...- Kinh nghiệm ghép âm thanh và tìm kiếm âm thanh- Đáp ứng các deadline một cách chính xác- Kỹ năng làm việc nhóm- Có trách nhiệm, đam mê, sáng tạo, chi tiết, cẩn thận.', '- Lương cứng: 8.000.000 - 10.000.000 + THƯỞNG  (Thưởng cao hơn lương CB)- Được đóng BHXH, BHYT, BHTN đầy đủ- Được cấp máy tính & trang thiết bị hiện đại- Môi trường trẻ trung, chuyên nghiệp- Được hưởng các chính sách phúc lợi theo quy định của công ty- Thời gian làm việc: 8:00 - 17:30 từ thứ 2 đến thứ 7 (Thứ 7 làm 50% KPIs)', 'Trụ sở chính công ty', 4, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (22, 12, '1847038', 'Nhân Viên Kinh Doanh Phần Mềm CRM (Sales B2B)', 20.00, 30.00, 'Dưới 1 năm', 'Nhân viên', '2026-04-28 19:07:55.655775', '2026-06-01 19:07:55.655775', 5, 'Tiếp nhận data khách hàng quan tâm từ Bộ phận Marketing và các nguồn khác, phân tích nhu cầu sử dụng phần mềm SandboxVN và ký hợp đồng tái tục.Tìm kiếm và khai thác khách hàng tiềm năng có nhu cầu sử dụng phần mềm quản trị doanh nghiệp.Thực hiện báo giá, tư vấn phần mềm, demo sản phẩm, đàm phán và ký kết hợp đồng.Đào tạo khách hàng sử dụng hệ thống; chăm sóc và duy trì mối quan hệ với khách hàng hiện có để gia tăng sự hài lòng, khai thác cơ hội từ nguồn khách hàng giới thiệuPhối hợp với các bộ phận liên quan (Marketing, CSKH, Kỹ thuật...) để hỗ trợ, đề xuất phát triển các tính năng phù hợp với yêu cầu khách hàngBáo cáo hiệu quả công việc định kỳ theo yêu cầu của quản lý.', 'Tốt nghiệp đại học các khối ngành Kinh Tế, Quản trị KD hoặc ngành có liên quanThành thạo kỹ năng văn phòng, giao tiếp tốt & tư duy phân tíchCó kinh nghiệm làm việc với khách hàng tại các vị trí: Sales, Consultant, Business Development, Account Manager, Partnership, Customer Relationship Manager,.... trong lĩnh vực công nghệ là một lợi thếĐã từng làm sales B2B về mảng CNTT, Phần mềm dịch vụ CRM, SaaS, phần mềm quản lý...Chào đón với các bạn fresher, sinh viên mới tốt nghiệp – đam mê kinh doanh, sẵn sàng học hỏi và bứt phá giới hạn của chính mình!', 'Lương cứng: 8.500.000 – 16.500.000 VNĐ/thángThu nhập hấp dẫn từ 15-30 triệu gồm: Lương căn bản theo năng lực cạnh tranh + hoa hồng + thưởng KPI quýThử việc trong vòng tối đa 02 tháng. Có bonus thêm với hợp đồng trong quá trình thử việc, KHÔNG ÁP KPI trong 02 tháng đầuĐào tạo bài bản từ A-Z: sản phẩm, kỹ năng sale, kỹ năng chốt deal, kỹ năng chăm sóc khách hàngĐược định hướng công việc theo năng lực và có lộ trình thăng tiến rõ ràngMôi trường làm việc trẻ, thân thiện, chuyên nghiệp, Được hưởng chế độ nghỉ mát, du lịch hàng năm, event,...Đầy đủ chế độ BHXH, BHYT, BHTN, phép năm, nghỉ lễ theo quy địnhĐược làm việc cùng đội ngũ am hiểu chuyên sâu về thị trường và nhiều kinh nghiệm phát triển các sản phẩm thành công.Thời gian làm việc: từ Thứ 2 đến Thứ 6 và sáng thứ 7 cách tuần, sáng từ 08h30 - 12h00, chiều từ 13h30 - 17h30;', 'Trụ sở chính công ty', 4, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (25, 15, '2034651', 'Nhân Viên Kinh Doanh Tiếng Hàn', NULL, NULL, '1 năm', 'Nhân viên', '2026-04-10 19:07:55.655775', '2026-04-30 19:07:55.655775', 5, 'Chủ động tiếp cận đối tác mới thông qua đa kênh (cold call, email marketing, networking events,…) để xây dựng phễu khách hàng Củng cố và phát triển quan hệ đối tác với danh mục khách hàng hiện hữu, đảm bảo tỷ lệ duy trì (retention) và tái ký hợp đồng Hợp tác chặt chẽ với đội ngũ kỹ thuật/sản phẩm để xây dựng giải pháp, soạn thảo hồ sơ đề xuất (Proposal), báo giá thương mại và lên kế hoạch triển khai Đóng vai trò cầu nối truyền tải yêu cầu từ khách hàng, theo dõi tiến độ thực hiện và trực tiếp tham gia giải quyết các vướng mắc để đảm bảo chất lượng đầu ra', 'Có kiến thức hoặc kinh nghiệm trong lĩnh vực CNTT, mô hình B2B hoặc tương đươngTối thiểu 1 năm kinh nghiệm ở vị trí SalesGiao tiếp thành thạo tiếng Hàn (Topik 5+)Kỹ năng giao tiếp, đàm phán tốt; hiểu tài liệu kỹ thuật là lợi thế', 'Lương thưởng cạnh tranh, thưởng tháng 13, review 2 lần/nămNghỉ 14 ngày phép/năm, nghỉ thứ 7 & CNTham gia đầy đủ BHXH – BHYT – BHTN, MIC CareMôi trường trẻ trung, năng động, văn hóa mở và chia sẻTeambuilding, Year-end Party, Happy Hour, CLB nội bộ (Bóng đá, Yoga, Bơi, Âm nhạc, v.v.)Cơ hội học tập & phát triển với khóa học nội bộ, workshop, LMS riêng', 'Trụ sở chính công ty', 519, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (35, 25, '2028349', 'Kỹ Sư AI / AI Engineer ( Thu Nhâp 1,000 - 2,000 USD )  - Phỏng Vấn Sau Tết - Hà Nội', 25.00, 50.00, '2 năm', 'Nhân viên', '2026-05-08 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, 'Phát triển và làm chủ mô hình AI (core chính của dự án):Lựa chọn mô hình/thuật toán phù hơp, xây dựng, huấn luyện, tối ưu mô hình AI (ML, LLM)Đánh giá và kiểm soát chất lượng mô hình: Xây dựng metric đánh giá, phân tích sai lệch và giải thích kết quả mô hìnhTriển khai mô hình: Đóng gói mô hình và phối hợp với IT để phát triển mô hình', 'a. Yêu cầu năng lực chuyên mônKỹ năng bắt buộc:Tốt nghiệp Đại học chuyên ngành về Dữ liệu, AI, công nghệ thông tin, toán hoặc các chuyên ngành liên quan.Đã từng phát triển ít nhất 1 production về  AI sử dụng công nghệ về NLP, predictive AISử dụng thành thạo Python và ít nhất một framework là Pytorch hoặc Tensorflow.Nắm vững thuật toán về machine learning.Kỹ năng lợi thế:Có kinh nghiệm về MLOps.Có kinh nghiệp fine tune mô hình LLM mã nguồn mở.Làm việc với dữ liệu lớn, dữ liệu nhiễuAm hiểu về định giá và BĐSb. Yêu cầu về kỹ năng mềmKhả năng làm việc độc lập tốt: xác định vấn đề, giải quyết vấn đề, khả năng chịu áp lựcKỹ năng làm việc nhóm tốt: kỹ năng giao tiếp, trình bày, thuyết phục, team building.Có khả năng  tiếng anh tốt là một lợi thế( nghe, nói, đọc hiểu).Sôi nổi, nhiệt tình, đam mê công việc là một lợi thế.', 'Thử việc: Thử việc 60 ngàyThời gian làm việc: Làm việc từ thứ 2 tới thứ 6, 08h00 đến 17h30 (nghỉ trưa 90 phút)Ngày nghỉ: Thời gian nghỉ chế độ và nghỉ lễ theo quy định Công ty và quy định Pháp luậtPhúc lợi:- Lương Chức danh;- Lương hiệu quả công việc;- Lương tháng 13;- Phụ cấp;- Chế độ xem xét tăng lương gắn liền với hiệu quả công việc.- Thưởng nhân các ngày lễ tết và các sự kiện MBAMC;- Thưởng thành tích định kỳ và đột xuất cho cá nhân hoặc tập thể.Phụ cấp khác :- Bảo hiểm Xã hội, Y tế, Thất nghiệp theo quy định của nhà nước;- Gói bảo hiểm sức khoẻ của MIC dành riêng cho CBNV Công ty;- Bảo hiểm tai nạn lao động.- Trợ cấp nhân các sự kiện đặc biệt của CBNV;- Chương trình du lịch trong và ngoài nước hàng năm;- Khám sức khỏe định kỳ.', 'Trụ sở chính công ty', 91, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (85, 73, '1890628', 'Nhân Viên Lập Trình', NULL, NULL, '1 năm', 'Nhân viên', '2026-04-29 19:07:55.655775', '2026-05-18 19:07:55.655775', 1, '- Lập quy trình chế tạo chi tiết, khuôn mẫu.- Lập trình gia công CNC (Phay 3 trục, Phay 5 trục, Tiện, Cắt dây,..)- Các công việc khác phù hợp với chuyên môn, theo sự phân công công việc của cấp trên.', '- Tốt nghiệp các trường Đại học và Cao đẳng chuyên ngành liên quan - Nhanh nhẹn, có trách nhiệm với công việc- Có thể làm thêm giờ.- Ưu tiên ứng viên có kinh nghiệm', '- Có lương tháng 13, thưởng lễ, tết, du lịch hàng năm.- Tăng lương hàng năm- Đóng BHXH, YT, TN ….theo luật- Thời gian làm việc: 8-17h, nghỉ 4 chủ nhật, nghỉ ngày lễ tết theo quy định.- Có xe đưa đón Hà Nội - Bắc Ninh-Có phụ cấp đảm bảo chất lượng, chuyên cần, hỗ trợ nhà ở (trang phục) + ăn', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (21, 11, '2037040', 'Senior AI Engineer / NLP Engineer', NULL, 50.00, '3 năm', 'Nhân viên', '2026-04-12 19:07:55.655775', '2026-05-14 19:07:55.655775', 3, 'We are seeking a highly skilled AI Engineer to join our dynamic team. The successful candidate will play a critical role in developing and implementing cutting-edge Natural Language Processing (NLP) techniques to power our AI-driven language learning products. You will work on a variety of applications, including but not limited to:Automated essay scoringPronunciation, grammar, and lexical scoringAI-based learning assistantsConversational AI systemsPersonalized adaptive learning systemsAnd more innovative AI-powered education toolsKey Responsibilities:Design, implement, and optimize NLP pipelines for real-world language learning applicationsFine-tune Large Language Models (LLMs) for specialized tasksDevelop agentic systems that support multi-step reasoning, task decomposition, and interactive learningUtilize Model Context Protocol (MCP) and other LLM orchestration frameworks to build structured, context-aware AI experiencesCollaborate with cross-functional teams including product managers, linguists, and engineers to align AI capabilities with learning goalsContribute to the evaluation and continuous improvement of model performance using both automated and human-in-the-loop methods', 'Hard Skills Requirements:Bachelor''s or Master''s degree in Computer Science or related fields.At least 3 years of experience in the field of Natural Language Processing (NLP).Proficient in programming languages, especially Python (knowledge of C/C++ is an advantage), and capable of using frameworks such as Tensorflow, Keras, PyTorch.Solid understanding of LLM fine-tuning, prompt engineering, and low-rank adaptation techniques (LoRA, QLoRA, etc.)Hands-on experience with building or integrating Agentic AI workflows using tool-augmented agents or function-callingExpertise in building, analyzing data, training, and optimizing NLP models.Experience in model serving (using RayServe, Triton, TorchServe, etc.) and service integration and deployment is an advantage.Significant experience with Large Language Models (LLM) is a major advantage.Proficient use of Git, Docker.Experience with data organization systems: Database (Postgres, MySQL), Cache (Redis), Queue (RabbitMQ, Kafka) is an advantage.Ability to comprehend technical documents, scientific articles, and stay up-to-date with the State of The Art (SOTA).Strong analytical and problem-solving skills.Soft Skills Requirements:High enthusiasm and responsibility.Good communication skills, proactive, flexible at work, collaborative, and friendly within the team.Careful in work and considerate of customers.Fluency in English and Chinese is an advantage.', 'Salary: Up to 50 million VND.KPI bonus based on work results and company revenue (2-4 million/month), paid in monthly salary.Salary increases based on performance and contribution.Flexible working hours, a youthful and dynamic work environment.Health insurance, team building activities, annual vacations.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (11, 2, '2032576', 'Data Engineer (Fresher+)', NULL, NULL, 'Dưới 1 năm', 'Nhân viên', '2026-05-07 19:07:55.655775', '2026-05-23 19:07:55.655775', 5, 'Build, maintain, and optimize BI dashboards and reporting systemsMonitor marketing performance and user behavior across mobile apps/gamesTrack key growth, user, and performance metrics on a regular basisDetect and report early signs of abnormal performance in campaigns or user dataAnalyze data trends over time to provide actionable insightsGenerate dashboards and summary reports for key performance indicators (KPIs)Support teams in data-driven decision makingWork with relevant teams to clarify data requirements and business needsPropose improvements to reporting systems and data workflows when necessary', 'At least 06 months – 1 year of experience as a Data Engineer, experience working with mobile apps or games is preferredStrong proficiency in SQLExperience working with BI tools / dashboards (e.g. Looker, Power BI, Tableau, Metabase, or similar)Good data analysis and logical thinking skillsUnderstanding of common metrics in mobile apps, games, or digital marketingCareful, proactive, and systematic working mindsetExperience handling multiple data sources is a plusKnowledge of marketing performance (UA, ROAS, CPI, LTV, retention, etc.) is an advantage', 'Attractive salary package + Project bonus + Performance bonus and other bonus on Public HolidaySalary review twice a yearTet bonus upto 03 month salary Lunch allowance7,5 working hour per day; 05 days per week12 Annual leave per yearPeriodic Health check; Health insurance package02 company trips per year, team building activities,…', 'Trụ sở chính công ty', 214, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (51, 156, '2029629', 'Senior Data Analyst Executive - Finance Dept.', 28.00, 35.00, '5 năm', 'Nhân viên', '2026-05-14 19:07:55.655775', '2026-06-14 19:07:55.655775', 7, 'Collaborate with the ERP and Operations teams to understand business rules, gather data from multiple sources, ensure data quality, and develop efficient data collection systems.Apply statistical analysis, data modeling, and other analytical techniques to interpret data and identify trends.Develop reports, dashboards, and other visualizations to clearly and effectively communicate insights.Collect, validate, clean, and organize data to produce standardized datasets for analysis.Support sales planning and forecasting through the analysis of historical data.', 'Education: Bachelor’s Degree in Data Science/ Economics/ Statistics/ Finance Experience: 5+ years of data analytics or other relevant experienceComputer skills: Strong proficiency in SQL, Power Query, Power BI, DAX Studio, and MS. Excel (Advanced Level). Practical experience with Azure Analysis Services, Python/R and BigQuery is a plus.Proficient in data analysis tools, programming languages, and data visualization software.Strong analytical and problem-solving skills, with the ability to interpret complex datasets.Excellent logical and technical capabilities in data modeling, data mining, and segmentation.Solid knowledge in developing and applying accurate algorithms to datasets to derive solutions.Strong understanding of business principles and the ability to leverage data analysis to address business challenges.Good communication and presentation skills, capable of conveying insights effectively to both technical and non-technical audiences.', 'Facilitate laptop support for work requirements.Participate in 100% Insurance compliance with current Labor Laws.Annual company travel opportunities.Free provision of work uniforms.Annual health examination.Attend the company''s skill training courses.Evaluate salary increases based on performance and achievements.Annual vacation leave entitlement.Probation time: 100% of official salary.', 'Trụ sở chính công ty', 232, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (32, 20, '2037175', 'Trưởng Phòng Công Nghệ', NULL, NULL, 'Trên 5 năm', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-11 19:07:55.655775', 5, '- Xây dựng và triển khai chiến lược phát triển công nghệ dài hạn, gắn liền với mục tiêu kinh doanh và tầm nhìn số hóa của VIMID- Thiết kế kiến trúc tổng thể hệ thống (Java stack, Microservices, Cloud-native…), đảm bảo tính ổn định, bảo mật và khả năng mở rộng.- Quản lý ngân sách công nghệ, tối ưu chi phí đầu tư và vận hành hạ tầng CNTT.- Định hướng, giám sát và phát triển các sản phẩm – nền tảng phần mềm nội bộ và khách hàng: ERP, Data Platform, BI, AI/ML.- Xây dựng chiến lược dữ liệu doanh nghiệp, phát triển Data Lake, chuẩn hóa luồng dữ liệu và khai thác hiệu quả phục vụ ra quyết định.- Dẫn dắt đội ngũ kỹ sư triển khai các giải pháp trên nền Java, Spring Boot, Kafka, Docker, Kubernetes, bảo đảm chất lượng, tiến độ và hiệu năng hệ thống.- Phối hợp với các khối nghiệp vụ để chuyển hóa yêu cầu kinh doanh thành giải pháp công nghệ khả thi.- Xây dựng, đào tạo và phát triển đội ngũ kỹ sư – chuyên gia dữ liệu – chuyên viên hạ tầng; tạo lập văn hóa công nghệ đổi mới và hợp tác.', '- Tốt nghiệp Đại học/Cao học chuyên ngành CNTT, Khoa học máy tính hoặc các ngành liên quan.- Có tối thiểu 10 năm kinh nghiệm trong lĩnh vực công nghệ thông tin, trong đó có từ 05 năm ở vị trí quản lý cấp cao (CTO, Head of Angineering, Technical Director).- Hiểu sâu về kiến trúc hệ thống, Cloud, Microservices, DevOps, bảo mật và quản trị dữ liệu doanh nghiệp.- Kinh nghiệm triển khai hệ thống ERP, CRM, BI hoặc các nền tảng số hóa trong doanh nghiệp sản xuất/ô tô/logistics là một lợi thế.- Năng lực lãnh đạo đội nhóm kỹ thuật, định hướng phát triển và quản trị hiệu suất theo KPI/OKR.- Tư duy chiến lược, khả năng phân tích và ra quyết định nhanh; tinh thần đổi mới và trách nhiệm cao.', '- Cơ hội tham gia xây dựng hệ sinh thái công nghệ của Tập đoàn VIMID, định hình nền tảng số cho toàn bộ chuỗi vận hành và sản xuất.- Môi trường làm việc chuyên nghiệp, năng động, khuyến khích đổi mới và thử nghiệm công nghệ mới.- Lộ trình phát triển lên Giám đốc Công nghệ (CTO) khi đạt thành tích và năng lực vượt trội.- Phúc lợi toàn diện: Nghỉ lễ, Tết hưởng nguyên lương; thưởng các dịp đặc biệt (lễ, Tết, sinh nhật…); khám sức khỏe định kỳ hằng năm.- Văn hóa gắn kết: Tham gia các hoạt động nội bộ đa dạng: team building, du lịch thường niên, sự kiện lễ hội, chương trình sinh nhật, hoạt động gắn kết hằng quý...- Môi trường làm việc hướng đến sự chuyên nghiệp: Giờ làm việc từ 8h00 – 17h00 (thứ 2 – sáng thứ 7).- Giá trị cốt lõi đồng hành cùng tập thể VIMERS: GIÁ TRỊ- TỰ CHỦ- TRÍ TUỆ-CÂN BẰNG- TIN CẬY- CHIA SẺ', 'Trụ sở chính công ty', 183, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (33, 21, '2030703', 'Chuyên Viên Thiết Kế / Graphic Designer', 12.00, 16.00, '1 năm', 'Nhân viên', '2026-05-16 19:07:55.655775', '2026-06-13 19:07:55.655775', 5, 'Thiết kế các ấn phẩm truyền thông: fanpage, TikTok, group, website, quảng cáo, banner, poster, landing page...
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (34, 22, '2030738', 'UI/UX Designer (Mobile App – Motion/Visual)', NULL, NULL, '2 năm', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-10 19:07:55.655775', 7, 'We are looking for a UI/UX Designer for a mobile application who is passionate about creating intuitive user experiences and bringing interfaces to life through motion and visual storytelling.Key Responsibilities:Design end-to-end UI/UX for mobile applications (iOS/Android), including user flows, wireframes, mockups, and interactive prototypes.Collaborate closely with Product Managers and Mobile Developers to translate ideas into high-quality product experiences.Contribute to building and maintaining a scalable design system for the mobile app.Design onboarding flows and continuously improve user journeys based on product feedback.Nice-to-have Responsibilities:Create motion graphics, animations, or light 3D visuals to enhance in-app experiences.Support visual content for product demos, onboarding, training, or marketing when needed.Apply visual storytelling principles to help users better understand product features.', '2+ years of experience in UI/UX or Product Design for mobile applications.Strong proficiency in Figma (required).Solid understanding of mobile-first design principles and UI/UX best practices.A portfolio showcasing mobile app or product design work.Strong communication skills and ability to work cross-functionally with developers and stakeholders.Nice to Have:Experience with motion or animation tools such as After Effects, Blender, Cinema 4D, or similar.Experience working on tech products, SaaS platforms, or clean-tech solutions.Familiarity with Unity, Unreal Engine, or WebGL is a plus (not required).You don’t need to be a 3D expert — curiosity, creativity, and a willingness to learn matter most.', 'Salary: Negotiable based on qualifications and experience.Performance bonus based on system interaction scores.13th-month salary bonus and other incentives depending on business performance.Seniority bonus based on length of service milestones.Full participation in social insurance, health insurance, and unemployment insurance as per Vietnamese labor laws.24/7 accident insurance coverage for all employees.Annual leave and public holidays in accordance with the law.Additional benefits for weddings, funerals, Lunar New Year, Mid-Autumn Festival, etc.Allowances: Lunch, transportation, phone, laptop, travel expenses... and taxi card for certain positions.Corporate culture: “Aspiration to be different – Different to lead – Lead to succeed.”Professional working environment with talented and friendly colleagues.Opportunities for regular training, personal development, and clear KPI updates.Annual teambuilding and company trips based on business performance.', 'Trụ sở chính công ty', 471, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (166, 147, '2023617', 'Kỹ Sư Giải Pháp Nghiệp Vụ (BA Business Analyst)- VTS-Tối Thiểu 2 Năm Kinh Nghiệm', 15.00, 50.00, '1 năm', 'Nhân viên', '2026-04-13 19:07:55.655775', '2026-05-13 19:07:55.655775', 5, 'Xây dựng giải pháp nghiệp vụ (đối với dự án nâng cấp có nghiệp vụ cụ thể, rõ ràng) - Khảo sát nhu cầu, phân tích và mô hình hóa nghiệp vụ khách hàng - Xây dựng tài liệu phân tích nghiệp vụ (PTYC), làm Prototype - Chốt thống nhất với khách hàng về yêu cầu bài toán - Xây dựng tài liệu giải pháp và thiết kế chi tiết tính năng về mặt người dùng theo yêu cầu của Trưởng sản phẩm hoặc khách hàng. (Chi tiết các trường dữ liệu, các trường hợp ràng buộc, ngoại lệ) - Giải đáp, trao đổi các thắc mắc về mặt nghiệp vụ của đội dự án. Quản lý dự án- Cập nhật tài liệu liên quan trong dự án theo quy trình. - Quản lý và lưu trữ các yêu cầu thay đổi theo đúng quy trình. - Hỗ trợ AM, PM nghiệm thu sản phẩm/hệ thống với khách hàng - Tính toán nỗ lực, chi phí thực hiện cho các yêu cầu nghiệp vụ.', 'Bằng cấp: Tốt nghiệp Đại học (loại Khá trở lên) chuyên ngành CNTT, Điện tử Viễn thông, Khoa học Máy tính, Toán Tin Ứng dụng, Kinh tế hoặc tương đương.Ngoại ngữ: Đọc hiểu tài liệu tiếng Anh tốt. Ưu tiên có chứng chỉ TOEIC 550+ (hoặc IELTS, TOEFL tương đương).Kiến thức, kinh nghiệm:Có tối thiểu 1,5 năm kinh nghiệm ở vị trí ứng tuyển.Có kiến thức về các kĩ thuật phân tích nghiệp vụ, mô hình hóa các luồng nghiệp vụ như: các mô hình chức năng nghiệp vụ, mô hình dữ liệu quan hệ, ngôn ngữ UML, tạo Use case, BPMN,...Biết cách xây dựng prototype của sản phẩm/ứng dụng.Có khả năng giao tiếp, diễn đạt tốtTư duy phản biện, kỹ năng đàm phánTổ chức các cuộc họp.Tinh thần: Năng động, sẵn sàng học hỏi, dám đương đầu thử thách và luôn hỗ trợ đồng đội.', 'Lương cạnh tranh: Thu nhập “ổn áp”, xứng đáng với năng lực và kinh nghiệm.Đầy đủ các khoản thưởng: Thưởng lễ Tết, quà tặng, du lịch nghỉ mát, hỗ trợ ăn trưa, cước điện thoại...Nghỉ phép linh hoạt: 12 ngày phép + 3 ngày nghỉ mát + 1 ngày sáng tạo mỗi năm.Bảo hiểm toàn diện: Hưởng đầy đủ BHXH, BHYT, BHTN theo quy định, cộng thêm gói bảo hiểm riêng từ Viettel.Môi trường phát triển: Làm việc với công nghệ hiện đại, cơ hội tham gia các dự án quy mô lớn, không gian sáng tạo “bung nóc”.', '-Hà Nội:Số 1 Trần Hữu Dực, Mỹ Đình 2, Từ Liêm, Phường Từ Liêm', 538, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (86, 73, '1890605', 'Nhân Viên CNC', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-30 19:07:55.655775', '2026-05-21 19:07:55.655775', 1, '- Trực tiếp vận hành các loại máy gia công cơ khí CNC (Máy phay CNC- 3 trục, Máy phay CNC- 5 trục)- Trực tiếp quản lý và vận hành máy đo 3D và các loại dụng cụ đo- Các công việc khác phù hợp với chuyên môn, theo sự phân công công việc của cấp trên- Trao đổi cụ thể khi tham gia phỏng vấn', '- Tốt nghiệp các trường Đại học và Cao đẳng chuyên ngành cơ khí hoặc chuyên ngành liên quan - Có kinh nghiệm 3 năm về lập trình và chạy máy CNC 5 trục-Nhanh nhẹn, ham học hỏi, kiên nhẫn và chịu được áp lực', '- Có lương tháng 13, thưởng lễ, tết, du lịch hàng năm.- Tăng lương hàng năm- Đóng BHXH, YT, TN ….theo luật- Thời gian làm việc: 8-17h, nghỉ 4 chủ nhật, nghỉ ngày lễ tết theo quy định.- Có xe đưa đón Hà Nội - Bắc Ninh-Có phụ cấp 5S,, đảm bảo chất lượng, chuyên cần, hỗ trợ nhà ở(trang phục)..', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (28, 19, '1331229', 'Lập Trình Viên AI', NULL, NULL, '1 năm', 'Nhân viên', '2026-05-16 19:07:55.655775', '2026-06-03 19:07:55.655775', 5, 'Xây dựng kế hoạch để phát triển ứng dụng AI theo yêu cầu của Công ty;Thử nghiệm công nghệ, phát triển các thuật toán để xây dựng ứng dụng thông minh phát triển dự án của Công ty;Phối hợp với các bộ phận chuyên môn xây dựng CSDL;Nghiên cứu, lập trình AI vào các dự án của Công ty Theo dõi, đánh giá kết quả phát triển ứng dụng AI và báo cáo hoạt động của chương trình AI;Thực hiện các công việc khác theo chỉ đạo, phân công của cấp trên.', 'Tốt nghiệp đại học chuyên ngành Công nghệ thông tin hoặc các chuyên ngành khác am hiểu về Lập trình AI;Kỹ năng về phần mềm máy tính, khoa học dữ liệu, Machine learning, Deep learning, Computer VisionƯu tiên ứng viên có kinh nghiệm nghiên cứu, phát triển hoặc triển khai các bài toán Computer Vision như: nhận dạng hình ảnh, phân loại hình ảnh/video, phát hiện và theo dõi đối tượng, …Sử dụng được các ngôn ngữ lập trình như Python, R, C++, Java, ...Biết về các nguyên tắc về framework học máy như TensorFlow, Theano, PyTorch, Caffe, ...Kỹ năng giao tiếp khi làm việc trong đội nhóm để hoàn thành công việc tốt hơn.Tư duy và tính sáng tạo để hiểu phát triển mô hình AI theo nhu cầu của Công ty.Có tính tỉ mỉ, chịu được áp lực công việc; có tinh thần học hỏi, hợp tác trong công việc.Làm việc ổn định tại Hà Nội.', 'Mức lương thỏa thuận theo năng lực và kinh nghiệm. Xét tăng lương định kỳ hàng năm hoặc trước hạn theo tình hình đánh giá;Được hưởng các chế độ BHYT, BHXH theo quy định của nhà nước; các chính sách phúc lợi của Công ty;Làm việc trong môi trường chuyên nghiệp, năng động, bình đẳng, phát huy tối đa khả năng chủ động sáng tạo của nhân viên;Được trang bị đầy đủ trang thiết bị phục vụ công việc;Được trau dồi kỹ năng về nghiệp vụ và kỹ năng mềm;Được tham gia, đóng góp vào các dự án phát triển có quy mô lớn, lâu dài;Thưởng theo thành tích làm việc.', '-Hà Nội:101 Phố Láng Hạ, Phường Đống Đa', 5, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (19, 10, '2036914', 'Nhân Viên Thiết Kế Đồ Họa', NULL, NULL, '1 năm', 'Nhân viên', '2026-04-19 19:07:55.655775', '2026-06-02 19:07:55.655775', 3, 'Thiết kế tài liệu tiếp thị & truyền thông:
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (125, 110, '2035278', 'Web/Was Engineer', NULL, NULL, '4 năm', 'Nhân viên', '2026-05-08 19:07:55.655775', '2026-06-06 19:07:55.655775', 5, 'Chúng tôi đang tìm kiếm kĩ sư vận hành về mảng Web/Was; DatabaseWEB/WASTham gia dự án vận hành/ phát triển (Web: Nginx, Apache, IIS, WebToB)Thực hiện cấu hình Web/Was (Was: Jboss, Tomcat, Jeus)Điều tra các issue liên quan tới Web/Was, phối hợp các thành viên dự án xử lý issueINFRA/CLOUDTham gia dự án vận hành/ phát triển (AWS/SCP)Phối hợp với các thành viên dự án giải quyết các vấn đề Infra/Cloud (Windows/Linux server)Tư vấn giải pháp/kiến trúc (Loadbalancer)Tham gia đánh giá kiến trúc của dự án: điểm mạnh, điểm yếu, rủi ro về mặt hạ tầngDATABASETham gia dự án vận hành/ phát triểnTư vấn/ Tham gia triển khai các giải pháp tối ưu hóa database (DB:Oracle/PostgreSQL/SQL Server)Giải quyết các vấn đề về database: cài đặt, backup, migration,...Hỗ trợ: Đào tạo các kiến thức liên quan theo yêu cầu dự án', 'YÊU CẦU BẮT BUỘCWEB/WASWeb: Nginx, Apache, IIS, WebToBWas: Jboss, Tomcat, JeusINFRA/CLOUDKiến thức kinh nghiệm về Cloud (AWS/SCP)Kiến thức, kinh nghiệm vận hành Windows/Linux serverKinh nghiệm về LoadbalancerĐIỂM CỘNG NẾU CÓ KINH NGHIỆM VỀ DATABASEKinh nghiệm về DB:Oracle/PostgreSQL/SQL Server', 'Lương thỏa thuận100% lương trong thời gian 2 tháng thử việcBảo hiểm trên tổng lương bắt đầu ngay từ thời gian thử việc3 lần thưởng mỗi nămGói bảo hiểm y tế cao cấpNgân sách đào tạo hấp dẫn cho mỗi nhân viên mỗi năm cho đào tạo cá nhân & Tài khoản học tập trực tuyến cao cấpCơ hội đào tạo ở nước ngoàiNhiều hoạt động nội bộ: liên kết nhóm, đào tạo nhóm,...Tặng quà cho mỗi nhân viên lễ tết, sinh nhật…', '-Hà Nội:PVI, Phường Cầu Giấy', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (9, 2, '1960747', 'Playable Ads Developer (Senior) - Unity & Cocos', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-11 19:07:55.655775', 5, 'Develop and implement playable ads using Unity and Cocos Creator engines.Write clean, efficient, and maintainable code in C#, JavaScript, and TypeScript.Collaborate with Game Designer, Artists, and UA to translate game concepts into interactive playable ads.Optimize playable ads for performance and user experience across multiple platformsTroubleshoot, debug, and continuously improve existing playable ads.', '3+ years of experience in game development.Proven experience with Unity and Cocos Creator engine development.Strong programming skills in C#, JavaScript, and TypeScript.Solid understanding of game mechanics, user engagement, and ad monetization.Experience working on casual and puzzle games is a strong advantage.Ability to work independently and as part of a collaborative team.Passion for gaming and willingness to learn new technologies.', 'Competitive salary package with monthly project revenue bonuses.Full participation in social insurance schemes in accordance with company policies.Salary reviews twice a year.Daily lunch allowance.Company trips twice a year.Regular team-building activities and internal company events.Special bonuses on holidays, Tet (Lunar New Year), and birthdays.12 days of annual leave per year.Tet bonus of up to 3 months’ salary.Annual health check-ups and more.', '-Hà Nội:107 Nguyễn Phong Sắc, Phường Cầu Giấy', 869, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (12, 4, '1993638', 'Tester Up To 15M', NULL, 15.00, '1 năm', 'Nhân viên', '2026-04-15 19:07:55.655775', '2026-05-18 19:07:55.655775', 5, 'Review and analyze client-specific requirements and scope of projects/tasks to ensure an accurate understanding of deliverable requirements and acceptance criteria.Define test scenarios, create test plans, and participate in the definition and execution of manual and/or automated system test scripts.Executing the appropriate test cases, including writing test plans, scenarios, and test cases, mining and manipulating test data.Isolate, replicate, and report defects and retesting of defects through resolution.Collaborate with project team resources to understand and prioritize testing efforts.Execute project deliverables and tasks on time and on budget to support profitable and high-quality operations service delivery.Typically assigned to multiple projects, ranging from simple to moderate complexity, or to a single project of high complexity.Assist in the analysis of current processes and propose recommendations for process improvements.Perform other related duties as assigned.', '22-25 years old and have at least 1 year of experience in website or software testing.Basic knowledge in e-commerce, pre-intermediate English level (reading and writing skills), and computer literacy.Experience working in an Agile/Scrum or having knowledge of JavaScript, PHP, and Magento is a plus.Analytical, critical thinking, and problem-solving skills.Strong interpersonal skills to collaborate with customers and internal cross-functional teams.Ability to quickly learn new technologies, systems, and processes.Self-motivated, well-organized, and with strict attention to detail.Having an infectious can-do attitude inspires others and encourages great performance in a fast-moving environment.Own or potentially develop BSS core values: Passion, Responsibility, Integrity, Can-do attitude, Joy, Respect.', 'Salary: Up to 15M  (review every 6 months).Working in one of the leading Magento companies in Vietnam, which is the first to be both Select Extension Builder and Business Solution Partner of Magento, with nearly 100% foreign customers.Daily implement professional testing tools (Browserstack, Jmeter, Internal bug logging system…) Coverage of ISTQB certification fee and other advanced testing courses.Youthful and dynamic working environments with many clubs: running, football, board games…Convenient office at the 14th, 18th, 19th, and 20th floors with scenic views. Tea, coffee, and drinks are always available at the office.The State statutory holidays and collective activities (team building, picnics, travel…) are organized by the Company.Other benefits are according to the provisions of the Company and the Labor Code.', '-Hà Nội:Toà Viwaseen, 48 Tố Hữu, Phường Đại Mỗ', 670, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (37, 154, '2034946', 'Communicator (Comtor) - Tiếng Nhật (Mức Lương Từ 1000 - 1500$)', 25.00, 37.50, '1 năm', 'Nhân viên', '2026-04-26 19:07:55.655775', '2026-06-07 19:07:55.655775', 7, 'Thông dịch Nhật – Việt – Nhật trong các buổi họp dự án IT (vai trò chính)Dịch tài liệu dự án (requirement, spec, chat) Là cầu nối giúp khách hàng Nhật và team kỹ thuật hiểu nhau rõ ràng, đúng trọng tâmPhối hợp cùng PM/Developer để dự án chạy mượt mà', 'Tiếng Nhật thành thạo 4 kỹ năng (bằng cấp không quan trọng)
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (39, 155, '1990789', 'Senior Backend Developer (Node.Js) (Không Yêu Cầu Tiếng Anh, Nghỉ T7,CN) - Lương Upto 50 Triệu/Tháng', NULL, 50.00, '3 năm', 'Nhân viên', '2026-05-01 19:07:55.655775', '2026-05-25 19:07:55.655775', 5, 'Chúng tôi đang tìm kiếm Senior Backend Developer (Node.js) (Không yêu cầu tiếng Anh) gia nhập đội ngũ phát triển theo mô hình Agile, cùng xây dựng và phát triển các hệ thống phần mềm có khả năng mở rộng, hiệu năng cao.Bạn sẽ đóng vai trò chính trong việc:Phát triển toàn bộ logic phía server, đảm bảo tốc độ xử lý nhanh và ổn định.Thiết kế, xây dựng và bảo trì cơ sở dữ liệu, tích hợp nhiều nguồn dữ liệu trong cùng một hệ thống.Tham gia thiết kế kiến trúc hệ thống, tối ưu hiệu năng và khả năng mở rộng.Xây dựng các RESTful API bảo mật, xử lý xác thực và phân quyền người dùng.Bảo trì, vận hành và cải tiến hệ thống hiện tại nhằm đảm bảo tính ổn định, an toàn và khả dụng.Viết tài liệu kỹ thuật, thực hiện code review và mentoring cho các thành viên trong nhóm.', 'Yêu cầu bắt buộc:Có từ 3 năm kinh nghiệm trở lên trong phát triển Backend với Node.js.Thành thạo JavaScript, TypeScript.Kinh nghiệm làm việc với NoSQL (MongoDB) và SQL (MySQL, PostgreSQL).Có kinh nghiệm sử dụng Redis, BullMQ hoặc các hệ thống xử lý queue.Có kinh nghiệm xây dựng RESTful API đảm bảo bảo mật và hiệu năng.Có kinh nghiệm với các công nghệ real-time như WebSocket.Hiểu rõ lập trình bất đồng bộ, các đặc thù và cách tối ưu trong Node.js.Hiểu các nguyên lý thiết kế hệ thống scalable, hiệu năng cao.Có khả năng thiết kế database schema phù hợp với quy trình nghiệp vụ.Có kiến thức về accessibility và các tiêu chuẩn security compliance.Điểm cộng:Có kinh nghiệm làm việc với Front-end.Có kinh nghiệm với Java, Spring Boot, Maven.Từng tham gia các dự án có yêu cầu cao về hiệu năng hoặc real-time system.', 'Mức lương cứng: 30 - 45 TRIỆU VNĐ/tháng, deal theo năng lực.Lương tháng 13, thưởng lễ – Tết theo quy định.Thưởng nóng cho sáng kiến và thành tích nổi bật.KHÔNG YÊU CẦU TIẾNG ANH.Xét tăng lương & cấp bậc trung bình 02 lần/năm, minh bạch theo hiệu suất.Thời gian làm việc:08:30 – 17:30, Thứ 2 – Thứ 6 (nghỉ Thứ 7 & Chủ nhật).Tham gia đầy đủ BHXH – BHYT – BHTN theo Luật Lao động.Bảo hiểm sức khỏe Zenify Care – VBI.Được tham gia các khóa  đào tạo cải thiện kỹ năng mới nhất do công ty chi trả 100%Cung cấp thiết bị làm việc, máy tính và các công cụ AI hiện đại phục vụ công việc.Môi trường làm việc trẻ trung – chuyên nghiệp – đề cao hiệu suất & sáng tạo.Nhiều hoạt động nội bộ: Du lịch, team building 2–3 lần/năm, CLB thể thao (bóng đá, cầu lông,...), sinh nhật, workshop phát triển bản thân, các sự kiện gắn kết định kỳ.', '-Hà Nội:Tầng 3, Số 4 Phạm Tuấn Tài, Phường Nghĩa Đô', 519, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (45, 41, '2029241', 'Nhân Viên Tester/QC', NULL, 20.00, '1 năm', 'Nhân viên', '2026-04-21 19:07:55.655775', '2026-06-04 19:07:55.655775', 5, 'Tập đoàn MISA, thành lập năm 1994, là đơn vị CNTT hàng đầu Việt Nam với hơn 350.000 khách hàng tổ chức và gần 3,5 triệu cá nhân, hiện diện tại 22 quốc gia. MISA tiên phong phát triển Agentic AI và nền tảng AIaaS, cung cấp giải pháp số hóa cho doanh nghiệp, hộ kinh doanh và chính phủ. Định vị là tập đoàn dẫn đầu về Agentic AI, MISA cam kết đổi mới sáng tạo, giúp tối ưu vận hành, nâng cao hiệu quả và giảm tải thủ công cho tổ chức. Sứ mệnh của MISA là đồng hành cùng chính phủ, doanh nghiệp và cá nhân trong hành trình chuyển đổi số, khẳng định vị thế công nghệ Việt Nam trên quốc tế.Chi tiết công việc:Chịu trách nhiệm kiểm soát chất lượng phần mềm của Công ty trước khi phát hànhLập kế hoạch test, xây dựng testcase, thực hiện test, log bug và kiểm soát tiến độ xử lýTiếp nhận feedback, bug report của khách hàng và đốc thúc đội dự án cùng xử lýHỗ trợ tiếp nhận, làm rõ requirements hoặc tham gia xây dựng tài liệu mô tả nghiệp vụ khi cần', 'Nữ, độ tuổi 23 - 30Có ít nhất 01 năm kinh nghiệm thực tế tham gia test dự án phần mềm (web app và mobile app)Tư duy test hướng nghiệp vụ, hướng người dùngNắm rõ về các phương pháp và công cụ testHiểu rõ quy trình test sản phẩm phần mềmKỹ năng xây dựng test case nghiệp vụ, data test tốt, mô tả bug rõ ràng, dễ hiểuCó khả năng viết tài liệuGiao tiếp tốt, tư duy logic tốt, trách nhiệm cao với công việc', 'Tiên phong công nghệ, uy tínMISA là doanh nghiệp CNTT xuất sắc nhất khu vực Châu Á - Châu Đại Dương. Tiên phong xuất khẩu giải pháp SaaSTOP đầu doanh nghiệp CNTT tăng trưởng liên tục với quy mô nhân sự tăng 20%/năm, doanh thu tăng 15%/nămHội tụ 4000 nhân tài cùng khát vọng đưa sản phẩm công nghệ “Make In Vietnam” vươn tầm quốc tếXây dựng niềm tin với 350.000 khách hàng là đơn vị HCSN, doanh nghiệp, 3.5 triệu khách hàng cá nhân tại Việt Nam và 22 quốc giaHơn 100 giải thưởng trong ngành CNTT trong nước và quốc tếNền tảng vững chắc cho phát triển sự nghiệp, thăng tiến, quyền lợiLương cạnh tranh. Thưởng năng suất dựa trên kết quả công việc từ 2 tháng lương.Đánh giá review lương 2 lần/năm, nhiều cơ hội tăng lương 50-70%/năm, thưởng sáng kiến...Huấn luyện “Hổ tướng”: chương trình đào tạo quản lý tài năng, bệ phóng trở thành Chiến tướng tinh nhuệGiải thưởng “Gấu vàng": nơi tôn vinh những tài năng xuất sắc nhấtGói chăm sóc sức khỏe toàn diện tại Medlatec, cháy hết mình tại các CLB theo sở thích, chương trình teambuilding, du lịch định kỳMôi trường thân thiện, chia sẻ, đồng hànhKết nối tài năng: tập trung phát triển những con người có chung lý tưởng, mục tiêu, cùng trao giá trị và nhận thành côngTư duy đột phá: môi trường tôn trọng sự khác biệt và đề cao sáng tạo, MISA-er được tự do phát triển các ý tưởng tiến bộ, cải tiến công việcCông nghệ cao: trang bị máy tính làm việc, tối ưu hiệu suất công việc bằng ứng dụng công nghệ, phần mềm tự động (AMIS, Jira, Power BI, AI Marketing,...)Nơi làm việc hạnh phúc: MISA mong muốn tạo một môi trường làm việc để bạn luôn cảm thấy hạnh phúc', '-Hà Nội:Tầng 2, Toà N03T1, Khu đô thị Ngoại giao đoàn, Phường Xuân Đỉnh', 980, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (48, 41, '2029147', 'Business Analyst [JetPay BankHub]', NULL, NULL, '2 năm', 'Nhân viên', '2026-05-07 19:07:55.655775', '2026-05-22 19:07:55.655775', 5, 'As a member company of MISA, JetPay Joint Stock Company was established with the mission of providing secure, fast, and efficient digital payment solutions for businesses, organizations, and individuals. JetPay focuses on developing electronic payment services that help businesses optimize cash flow, enable transparent financial management, and enhance a convenient, seamless payment experience for users.Embracing the spirit of “Striving to innovate for a smarter world through Vietnamese intelligence and technology products,” we look forward to partnering with you to create breakthrough achievements together.Job DescriptionWork directly with customers to gather and clarify business requirements.Collaborate with domestic and international banks and financial institutions to understand and validate payment processes, and identify suitable solutions for customer implementation.Research and analyze competitor software, and propose enhancement initiatives for JETPAY BankHub.Conduct business analysis and produce Business Requirements Specifications (BRS) and related documentation.Train and brief developers to ensure they fully understand the business context and customer expectations.Participate in user acceptance testing (UAT) to ensure the software meets customer requirements accurately and completely.', 'Bachelor’s degree or above in Accounting, Finance, Banking, Business Administration, Economics, or a related field.Coursework in Accounting Principles, Management Accounting, and/or Financial Accounting.At least 2 years of experience in a similar role. Preference for candidates with experience in banking, online payments, or accounting/finance.Strong communication skills, quick to grasp issues, and a good self-learning ability.Able to collect, consolidate, and analyze information effectively.Capable of writing documentation, delivering training, and giving presentations.Careful, responsible, and reliable at work.Fluent in English.', 'With 31 years of growth and development, MISA is a workplace where you can feel confident building a long-term career, offering:Technology leadership and strong customer trustMISA is recognized as a leading IT company in the Asia Pacific region, and a pioneer in exporting SaaS solutions.Among the top fast-growing IT companies, with headcount increasing by 20% per year and revenue growing by 15% per year.Home to 4,000 talented professionals united by the ambition to bring “Make in Vietnam” technology products to the global market.Trusted by 350,000 public-sector organizations and businesses, and 3.5 million individual customers in Vietnam and 22 countries worldwide.Recipient of 100+ domestic and international awards in the IT industry.A strong foundation for career growth, advancement, and benefitsCompetitive base salary, aligned with your capabilities.Performance bonus based on results, equivalent to 2 to 3 months’ salary.Salary reviews twice a year.“Hổ tướng” (Tiger Generals) Program: a talent management training track and springboard to become an elite leader.“Gấu vàng” (Golden Bear) Awards: recognition for the company’s most outstanding talents.A comprehensive healthcare package with Medlatec, active interest-based clubs, and regular team building and company trips.A friendly, supportive, and collaborative environmentTalent connection: building a community of people who share the same values and goals, creating value together and achieving success together.Breakthrough mindset: a culture that respects differences and celebrates creativity, where MISA-ers are encouraged to develop progressive ideas and improve the way work gets done.High-tech workplace: provided work computers and productivity optimized through technology, applications, and automation software.Interview processRound 1: Role-specific InterviewRound 2: Culture-fit interview', '-Hà Nội:Tòa nhà Technosoft ngõ 15 Duy Tân, Phường Cầu Giấy', 309, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (54, 157, '2032509', 'Chuyên Viên Thiết Kế (Graphic Designer)', NULL, NULL, '5 năm', 'Nhân viên', '2026-05-22 19:07:55.655775', '2026-06-15 19:07:55.655775', 7, '- Thiết kế các ấn phẩm truyền thông quảng cáo trên các kênh online.- Thiết kế POSM (brochure, leaflet, standee, folder, poster, sticker….) và các sản phẩm in ấn khác….- Thiết kế các vật phẩm quảng cáo khác cho các event của công ty.- Thiết kế giao diện website/landing page cho các dự án bất động sản.- Phối hợp với team Marketing lên ý tưởng thiết kế cho các hình ảnh, video quảng cáo sản phẩm của công ty theo yêu cầu của từng dự án. - Sản xuất các teaser, Video ngắn phục vụ Marketing nội bộ và tuyển dụng.- Thực hiện công việc khác được giao từ người quản lý trực tiếp.', '- Tốt nghiệp đại học chuyên ngành đồ hoạ, hoặc chương trình tương đương.- Bắt buộc ứng viên từng làm việc ở công ty Bất Động Sản- Biết AI là một lợi thế.- Kinh nghiệm tối thiểu  05 năm trở lên.- Có kinh nghiệm về dựng Video là 1 lợi thế.- Đam mê đối với công việc thiết kế.- Chịu được cường độ và áp lực cao trong công việc.', '- Mức lương:  Thỏa thuận.- Được hỗ trợ chi phí các khóa học nâng cao trình độ chuyên môn.- Thưởng tháng 13, 14 + thưởng cuối năm, lễ tết, sinh nhật,...- Môi trường làm việc năng động, chuyên nghiệp, cơ hội thăng tiến- Được đi du lịch hằng năm- Được thưởng các ngày lễ tết trong năm.- Được hưởng các chế độ phúc lợi đặc biệt: sinh nhật, hiếu hỉ, ốm đau.Được hưởng các chính sách theo quy định của Nhà nước: BHXH, BHYT, BHTN, chế độ ốm đau, thai sản.', '-Hồ Chí Minh:307 Nguyễn Văn Luông, Phường Phú Lâm', 431, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (58, 49, '2032352', 'UI Design (APP)', 12.00, 15.00, '1 năm', 'Nhân viên', '2026-04-23 19:07:55.655775', '2026-06-06 19:07:55.655775', 5, 'Thiết kế UI cho ứng dụng mobile trên Android & iOS, bao gồm:- Onboarding- Core feature screens (utilities / AI features)- Paywall, subscription, pricing screens- Empty states, error states, loading statesPhối hợp với Product Owner để:- Hiểu rõ yêu cầu tính năng và mục tiêu sản phẩm- Chuyển yêu cầu thành layout và UI logic phù hợpLàm việc trực tiếp với Developer để:- Đảm bảo thiết kế khả thi khi implement- Kiểm tra UI sau khi dev hoàn thiện (UI QA cơ bản)Xây dựng và duy trì design system / UI guideline cho sản phẩm.Tối ưu giao diện dựa trên:_ Hành vi người dùng- Feedback thực tế- Yêu cầu từ thị trường Global (ngôn ngữ, độ dài text, văn hoá sử dụng)Hỗ trợ chỉnh sửa UI cho A/B test, cải thiện trải nghiệm và tỷ lệ chuyển đổi.', 'Tối thiểu 1–2 năm kinh nghiệm thiết kế UI cho app mobile (Android hoặc iOS).Thành thạo Figma (bắt buộc).Hiểu nguyên tắc thiết kế UI/UX cơ bản cho mobile app.Có tư duy sản phẩm, trải nghiệm và hành vi người dùng theo thị trường mục tiêu.Biết làm việc với design system, component, auto layout.Có khả năng đọc hiểu tiếng Anh (UI, tài liệu, feedback).Chủ động, có trách nhiệm, phối hợp team tốt.Điểm cộngĐã từng làm UI cho app utilities hoặc AI, theo mô hình Hybrid/IAPCó kinh nghiệm làm sản phẩm cho thị trường Global.Hiểu cơ bản về UX, conversion, A/B testing.Biết phối hợp thiết kế theo guideline Android & iOS (Material / Human Interface).', 'Thu nhập 12M-15M/thángCơ hội làm việc với sản phẩm app Global, người dùng trả phí thực tế.Lộ trình phát triển lên Senior UI Designer / Product Designer.Môi trường làm việc linh hoạt, đề cao hiệu quả và trách nhiệm.Tham gia trực tiếp vào quá trình xây dựng sản phẩm từ đầu.Hưởng đầy đủ các chế độ theo quy định của pháp luật lao động.', '-Hà Nội:49 Thái Hà, Phường Đống Đa', 118, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (72, 61, '2036144', 'Chuyên Viên Marketing (Full – Stack) – Hệ Thống ADCBook', NULL, NULL, '2 năm', 'Nhân viên', '2026-05-09 19:07:55.655775', '2026-05-26 19:07:55.655775', 5, 'Với vai trò Marketing Full-stack, bạn sẽ là "kiến trúc sư" tham gia vào mọi công đoạn của chiến dịch:· Lập chiến lược & Thực thi: Xây dựng, triển khai các kế hoạch Marketing tổng thể cho hệ thống cửa hàng ADCBook và các nhãn hàng đối tác.· Quản trị "Hub" truyền thông: Chăm sóc và phát triển hệ sinh thái đa kênh (Facebook, TikTok, Zalo, Website...). Không chỉ là đăng bài, mà là xây dựng cộng đồng yêu sách và văn hóa.· Sự kiện & Trải nghiệm khách hàng: Trực tiếp lên ý tưởng và tổ chức các sự kiện tại điểm bán (Workshop, Booksign, Ra mắt sản phẩm mới...) nhằm tối ưu lưu lượng khách và thúc đẩy doanh thu.· Kết nối đối tác: Phối hợp chặt chẽ với các nhà cung cấp, nhãn hàng để triển khai các chương trình khuyến mãi độc quyền (Co-branding).· Lắng nghe con số: Phân tích dữ liệu khách hàng (CRM), nghiên cứu hành vi mua sắm và đối thủ cạnh tranh để điều chỉnh chiến dịch "trúng và đúng" theo thời gian thực', '· Tốt nghiệp Đại học trở lên chuyên ngành Marketing, Truyền thông, QTKD hoặc liên quan.· Có tối thiểu 02 năm chinh chiến trong ngành Marketing. Đặc biệt ưu tiên những bạn đã từng làm tại các chuỗi bán lẻ (Retail).· Có khả năng viết content tốt, tư duy hình ảnh/video nhạy bén.· Kỹ năng phân tích số liệu để đưa ra quyết định dựa trên dữ liệu.· Khả năng quản lý dự án và làm việc nhóm linh hoạ.· Chủ động, không ngại thử thách với cái mới và có niềm đam mê với ngành sách/giáo dục.', '· Thu nhập: Lương cạnh tranh + Thưởng KPI.· Làm theo giờ hành chính. Được nghỉ Thứ 7 - Chủ Nhật· Địa điểm làm việc: Tầng 12A, tòa nhà Diamond Flower, 48 Lê Văn Lương, P.Yên Hòa, thành phố Hà Nội.· Đóng bảo hiểm theo quy định của Nhà nước.· Môi trường làm việc của Công ty năng động, văn hóa, tri thức, năng động, trẻ trung.· Hưởng các chế độ phúc lợi khác: Nghỉ lễ, Tết, du lịch và các đặc quyền mua sắm ưu đãi tại hệ thống ADCBook.', '-Hà Nội:Tầng 12A tòa Diamond Flower Handico 6, 48 Lê Văn Lương, Phường Yên Hòa', 408, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (74, 161, '2034793', 'UI/UX Designer', 15.00, 30.00, '2 năm', 'Nhân viên', '2026-05-15 19:07:55.655775', '2026-06-15 19:07:55.655775', 7, 'Thiết kế giao diện người dùng (UI) cho các ứng dụng web và di động, đảm bảo tính nhất quán và dễ sử dụng.Phát triển và tinh chỉnh các nguyên mẫu (prototypes) và wireframes.Đảm bảo tất cả các thiết kế tuân thủ bộ nhận diện thương hiệu và nâng cao trải nghiệm tổng thể của người dùng.Phối hợp chặt chẽ với các nhóm phát triển và sản phẩm để đảm bảo thiết kế được triển khai đúng ý tưởng.Cập nhật và áp dụng các xu hướng thiết kế mới để nâng cao chất lượng sản phẩm.', '2+ năm kinh nghiệm trong thiết kế UI/UX.Thành thạo các công cụ thiết kế như Figma và Adobe (Photoshop, Illustrator, XD,...).Sở hữu portfolio mạnh, thể hiện sự hiểu biết sâu sắc về nguyên tắc thiết kế và các thực tiễn tốt nhất.Kỹ năng nghiên cứu và phân tích hành vi người dùng.Kỹ năng giao tiếp tốt để làm việc hiệu quả với các nhóm phát triển và sản phẩm.Có khả năng học hỏi nhanh, làm việc nhóm, và tiếp thu công nghệ mới.Kinh nghiệm thiết kế trong môi trường Web3 hoặc blockchain là một lợi thế lớn.', 'Mức lương cạnh tranh 15-30 triệu tùy năng lực.Môi trường làm việc chuyên nghiệp và năng động.Nghỉ thứ 7, chủ nhật và các ngày lễ theo quy định Việt Nam.Đồng nghiệp thân thiện, cơ hội học hỏi và áp dụng các công nghệ hiện đại và cập nhật.Cung cấp đồ ăn nhẹ tại nơi làm việc', '-Hồ Chí Minh:Tầng 4, tòa nhà Vimedimex, 246 Cống Quỳnh, Phường Bến Thành', 322, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (77, 67, '2033464', 'Nhân Viên Gán Nhãn Dữ Liệu Tiếng Pháp/Tây Ban Nha/Bồ Đào Nha/Thái (Không Yêu Cầu Kinh Nghiệm)', NULL, NULL, 'Không yêu cầu', 'Nhân viên', '2026-05-20 19:07:55.655775', '2026-06-16 19:07:55.655775', 5, 'Review, label, and evaluate user-generated content related to learning and TV/Film domains in French/Spanish/Portuguese/Thai language .Perform content quality monitoring, classification, and policy-based assessment.Handle special workflows including CRP-related tasks, outreach, exemptions, experiments, and model training support.Ensure accuracy, consistency, and productivity in line with project KPIs.Escalate edge cases or ambiguous content to QA or Project Management.Collaborate with QA and Operations teams to maintain overall quality.', 'Prior annotation or content-related experience is a plus but not mandatory.Regularly using social networking platforms such as TikTok and YouTube is a plus.Comfortable working with visual media and related technologies.Proficiency in French/Spanish/Portuguese/Thai with level B2 and above in all four skills (reading, listening, writing, and speaking).Strong language comprehension and attention to detail.Ability to follow guidelines and feedback accurately.Comfortable working onsite in a fast-paced, KPI-driven environment.Rigorous work attitude, consumer-oriented, responsible.', 'Competitive salary range can be negotiable based on language level, including 90% base salary + 10% performance bonus.100% base salary + performance bonus during 2-month probation.Social insurance premium is based on 100% gross salary.12 annual leaves per year.Annual health check-up.A chance to improve your language skills.Dynamic working environment, free style wearing', '-Hà Nội:Việt Á Tower, 9 Duy Tân, Phường Cầu Giấy', 823, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (79, 69, '2024294', 'Senior DevOps / Site Reliability Engineer (SRE) - Upto $4000', NULL, NULL, 'Trên 5 năm', 'Nhân viên', '2026-04-26 19:07:55.655775', '2026-05-21 19:07:55.655775', 5, '1. Operational Excellence & Incident Management 
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (98, 86, '2033527', 'Senior PHP Laravel Developer - 5 Năm Kinh Nghiệm - Thu Nhập Hấp Dẫn - Tại Hà Nội', NULL, NULL, '5 năm', 'Nhân viên', '2026-05-05 19:07:55.655775', '2026-05-27 19:07:55.655775', 5, 'We are actively seeking an experienced Senior PHP Laravel Developer  with strong expertise in PHP/Laravel to play a crucial role in advancing our projects. As a Senior PHP Laravel Developer, your responsibilities will encompass:● Designing and implementing web applications primarily utilizing the Laravel framework.● Diagnosing and resolving bugs within the code.● Engaging with SQL databases at an advanced level.● Collaborating closely with software developers and architects to analyze requirements, construct software components, and deliver innovative solutions.● Implementing advanced best practices, coding standards, and security measures, employing industry-standard tools for building enterprise-level web applications.● Playing a pivotal role in ensuring the successful delivery of projects by proactively analyzing, researching, and resolving complex application issues.● Can build UI (HTML/CSS/JS) based on design (Figma, XD...)● Have worked with UI Framework/Library (Bootstrap, Tailwind, Vuetify...)● Conducting rigorous testing of functions and projects to ensure high-quality deliverables to customers.● Utilizing Slack as the primary communication tool for team collaboration and project updates.', 'Skills:● Minimum 5+ years of backend development expereince.● Strong experience with PHP and Laravel framework●  Experience with at least one additional backend language (Python, Java, Go, Node.js, etc.)● Solid expertise in advanced OOP concepts.● Proficiency in using Git, Docker at an advanced level.● Deep expertise in SQL, MySQL databases.Nice to have:● Have experience working with Wordpress● Experience building and integrating LLM-powered chatbots/AI assistants into production applications.● Experience in building realtime Chat, Notification● Proven experience working with Japanese companies and projects in Japan.● Familiarity with VueJS, Test Driven Development, WordPress.● Knowledge of Cloud concepts.● Experience with Agile Software Methodology.', 'Benefits:- Professional and open working environment- Support personal development● Special working time: only 7.5 hours from 7:30 - 16:00 Monday to Friday with a flexible check-in/out of ±15 minutes(Lunch break 1 hour)● Free lunch every Wednesday● Free snack and drinksSalary● Competitive monthly salary, up to $1700● Various allowances: language allowance, attendance allowance, seniority allowance...● 13th month bonus per year', '-Hà Nội:The Sun Building, No 3 Me Tri Street, Tu Liem Ward, Phường Từ Liêm', 381, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (99, 86, '2033483', 'Support / Helpdesk (Japanese Speaking) - Tại Hà Nội', 10.00, 24.00, '1 năm', 'Nhân viên', '2026-05-05 19:07:55.655775', '2026-06-15 19:07:55.655775', 5, '● Receive and respond to emails, chats, and phone calls from Customers  
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (131, 115, '1987778', 'Intern AI - ERP - Software Developer', NULL, NULL, 'Không yêu cầu', 'Nhân viên', '2026-05-07 19:07:55.655775', '2026-06-14 19:07:55.655775', 7, 'Tham gia thiết kế, lập trình sản phẩm phần mềm quản lý doanh nghiệp (ERP)Hệ thống phần mềm nên nền tảng Odoo, ngôn ngữ lập trình Python, Java, PHP, HTML, CSS, mobile app, Embedded, IoT ... theo ứng dụng, chuyên môn thực tập.Thực hiện công việc chuyên môn theo kế hoạch được giaoĐược đào tạo, nghiên cứu tài liệu chuyên ngànhTham gia các khoá đào tạo, hội thảo theo hướng dẫnViết tài liệu, slide, present công việc đã thực hiện, nghiên cứuBáo cáo công việc chủ động theo kế hoạchNghiệp vụ thực hiện:Bao gồm tất cả các chuyên môn, nghiệp vụ trong quy trình lập trình phần mềm.', 'Sinh viên đang học tại các trường Đại học, Cao đẳng; đam mê với ngành (có thể khác ngành nhưng có mong muốn làm việc trong ngành Công nghệ thông tin – phần mềm), mong muốn được tham gia công cuộc chuyển đổi số quốc gia của chính phủSắp xếp công việc, tập trung hoàn toàn cho thực tập để đạt được kết quả tốt nhấtNăng động, chủ động nghiên cứu, sẵn sàng nhận việc khó, những việc chưa biếtSẵn sàng lắng nghe, học hỏi để đạt được hiệu quả tốt nhất', 'Cơ hội đào tạo với Doanh nghiệpĐược hỗ trợ DẤU DOANH NGHIỆP theo yêu cầu chương trình thực tập của nhà trườngThư giới thiệu của công ty, khi mong muốn ứng tuyển cho các công ty / học bổng nghiên cứu du học, đặt biệt là công ty nước ngoài, hay học Cao học.Văn phòng: Coffee luôn sẵng sàngĐược đào tạo sử dụng email chuyên nghiệp trong công việc, được cấp email doanh nghiệpĐược đào tạo sử dụng, triển khai hệ thống phần mềm chuyển đổi số như ERP, MRP, CRM, Marketing theo chương trình đề cương thực tậpĐược đào tạo kỹ năng nghiên cứu, trình bày, kỹ năng thuyết trìnhĐược giới thiệu tham gia các hội thảo, triển lãm chuyên ngành phù hợp với lĩnh vực học tập nghiên cứuCơ hội làm luận văn tốt nghiệp với Doanh nhiệpCơ hội làm Đề tài/luận văn Tốt nghiệp với doanh nghiệp, đề tài/sản phẩm thực tế khả năng áp dụng cao.Đề tài liên quan: IoT, tích hợp AI trong quản trị doanh nghiệpChương trình thực tập: 3 phases:   Phase 1:Nhiệm vụ: Học hệ thống – Framework công ty đang sử dụng: triển khai hệ thống e-Commerce hay tương tựMục tiêu: hiểu sơ bộ năng lực / khả năng của hệ thống – frameworks; quy trình vận hành thực tế khi triển khai hệ thống CNTT cho doanh nghiệpKế hoạch: 1 – 2 tuần Phase 2:Nhiệm vụ: Học lập trình với framework công ty đang sử dụng: Theo nguyện vọng của sinh viên và năng lực được công ty đánh giá sau Phase 1: FrontEnd, BackEnd, MobileApp, Embedded IoTMục tiêu: Hiểu sơ bộ về lập trình, tích hợp với frameworkKế hoạch: 1 - 2 tuần Phase 3:Nhiệm vụ: Thực tập – trải nghiệm với dự án mẫu: qua Phase 1 và Phase 2, công ty đánh giá đề xuất dự án mẫu phù hợp với sinh viênMục tiêu: Trải nghiệm làm việc nhóm, với dự án mẫuKế hoạch: Toàn bộ thời gian thực tập còn lạiHỗ trợ Đồ án – Luận văn tốt nghiệp với doanh nghiêp:Đối tượng: Sinh viên đã thực tập với công ty. Hiểu quy trình, cách làm việcMục tiêu: Đề tài – Nhiệm vụ – Lĩnh vực theo năng lực nguyện vọng và thực tế trải nghiệm của sinh viên sau giai đoạn thực tậpKế hoạch: 3 – 4 tháng (theo kế hoạch của nhà trường)', '-Hồ Chí Minh:125/45C Âu Dương Lân, Phường Chánh Hưng', 658, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (107, 96, '2035231', 'Quality Control (Japanese N4) / Kiểm Thử Phần Mềm', 10.00, 25.00, '2 năm', 'Nhân viên', '2026-05-13 19:07:55.655775', '2026-05-31 19:07:55.655775', 7, 'Read and interpret Japanese Detail Design documents (詳細設計書) to create comprehensive Japanese test plans and test cases.Perform thorough manual testing on legacy Java Applet applications.Create high-quality Japanese evidence (エビデンス) and test reports.Conduct "double-checks" on all documents and test results to ensure zero-defect delivery to the client.Read and analyze Java source code and PL/SQL (Oracle) to understand system logic.Write basic PL/SQL code and complex queries to verify data integrity, understanding table relationships and keys.Work comfortably with low-level code and specialized proprietary tools provided by the client.Communicate directly with the Japanese client to clarify requirements or report issues.Strictly follow the client’s established workflow without deviation.Establish and follow a formal process for explaining technical issues or bugs to the client in a clear, professional Japanese manner.', 'JLPT N4 or higher. You must be able to read/understand technical designs and write professional test cases in Japanese.Experience working on Japanese software projects and familiarity with Japanese business etiquette (Ho-Ren-So).Ability to read Java and PL/SQL.Strong knowledge of Oracle Database (tables, keys, relationships, and SQL querying).Basic ability to write PL/SQL scripts for testing purposes.Comfortable working with Java Applet technology and low-level tools.High level of attention to detail; you are someone who checks your work three times before hitting "send."A disciplined approach to following strict project methodologies.The ability to explain "why" an issue occurred and present it logically to the client.', 'Competitive salary and benefits including Premium Healthcare package insurance13th-month salary, Performance bonus 16 days annual leaveComprehensive Training Courses (Languages, Technical and Soft-skill)Language Certificate allowance (TOIEC, IELTS )Lunch and bus/ parking allowance Fun team activities and outings Sponsored happy hour and sports clubs Comfortable workspace and friendly colleagues', '-Hồ Chí Minh:E Town 2, 364 Cộng Hòa, Phường Tân Bình', 861, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (103, 90, '2035669', 'Junior IT Technician', NULL, NULL, '2 năm', 'Nhân viên', '2026-05-14 19:07:55.655775', '2026-06-24 19:07:55.655775', 5, 'Position Title: Junior IT Technician.Department: Information Technology.Reporting To: Information Technology Supervisor.Location: Ha Noi, Viet Nam.Employment Type: Full-Time.To provide direct technical support to employees, ensuring IT systems operate stably and resolving hardware, software, and network connectivity issues in a timely manner. This role requires strong problem-solving skills, effective communication, and a customer-centric mindset to support the needs of a BPO environment.ResponsibilitiesEnd-User Support: Handle requests via the ticketing system; diagnose and troubleshoot hardware, software, and network issues for laptops, printers, and peripherals.System & Network Administration: Manage user accounts and access permissions; perform routine maintenance on network devices and servers; coordinate with vendors for repairs when necessary.Asset Management: Monitor the full lifecycle of IT assets (procurement, issuance, maintenance, recovery); conduct monthly inventories and comply with the company''s Asset Management SOP.Documentation & Reporting: Update technical documentation and FAQs; provide periodic reports on ticket resolution status and recurring incidents to improve service quality.Compliance & Security: Ensure adherence to IT security policies and information security standards; report any potential security risks immediately.User Training: Guide employees on IT policies and self-service tools; notify staff regarding scheduled system maintenance.', 'Education: Bachelor’s or Associate’s degree in Information Technology or a related field.Working Hours: Willingness to work in shifts, including weekends or holidays as required (rotating shift, 40 hours/week).Technical Skills: Proficient in Windows 10, 11, and Windows Server; knowledgeable in computer hardware and on-premise network infrastructure.Experience: Preference given to candidates with experience providing technical support via multiple channels (email, chat, phone).Soft Skills: Excellent communication and problem-solving skills; ability to work both independently and as part of a team.Attitude: Responsible, proactive, and possessing strong professional ethics.', '1. Salary and BenefitsAttractive salary and benefits;100% salary during probation period;Social Insurance, Health Insurance, Unemployment Insurance contribution base on full salary, effective after probation period;Premium Healthcare and Mental Health Care service for you, 100% covered by the company;Extra bonus per personal events (Wedding, Funeral, Hospitalization, Newborn baby) and a very cute baby box for staff who are going to welcome a new baby angel to the world;Annual health check;Paid leave (12 days/year).2. Working EnvironmentInternational, fun and professional working environment;Modern hardware provided by the company (laptop, monitor, airpod, etc.);Free drinks (coffee, tea, etc.);English working environment;Training and career development opportunities', '-Hà Nội:Tower 1 Times City, Phường Vĩnh Tuy', 428, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (105, 93, '2034899', 'Data Engineer / Software Developer', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-09 19:07:55.655775', '2026-05-12 19:07:55.655775', 8, 'Phát triển, xây dựng và bảo trì các phần mềm/công cụ hỗ trợ quản lý cho các phòng ban trong nhà máy.Đảm bảo tính mở rộng (scalability) và tối ưu hiệu suất của hệ thống.Duy trì, nâng cấp các công cụ phân tích dữ liệu và báo cáo; đảm bảo tính chính xác và sẵn sàng của dữ liệu (daily/weekly).Đề xuất giải pháp về thu thập, xử lý và phân tích dữ liệu nhằm hỗ trợ các dự án Digitalization & Automation.Tham gia xây dựng và tối ưu quy trình vận hành/sản xuất thông qua ứng dụng công nghệ.Xác định vấn đề trong quy trình và đề xuất giải pháp cải tiến hiệu quả hoạt động.Soạn tài liệu hướng dẫn sử dụng, xây dựng kế hoạch đào tạo và trực tiếp training người dùng.', 'Trình độTốt nghiệp Đại học chuyên ngành:Công nghệ Thông tinKỹ thuật Phần mềmPhân tích dữ liệu hoặc các ngành liên quanKinh nghiệmTối thiểu 3 năm kinh nghiệm phát triển phần mềm/ứng dụng quản lý.Kiến thức & kỹ năng chuyên mônThành thạo:SQL (MySQL, SQL Server)Power BI, Power QueryMicrosoft OfficeCó kiến thức/làm việc với:Python, JavaScript, C#, HTML, CSSAI & Machine Learning (ứng dụng thực tế là lợi thế)Tiếng Anh: Tương đương B2 trở lênKỹ năng mềmTư duy phân tích và giải quyết vấn đề tốtChủ động trong công việc, quản lý tiến độ dự ánKhả năng làm nhiều nhiệm vụ và điều chỉnh ưu tiên linh hoạtKỹ năng giao tiếp & trình bày tốtTinh thần “can-do”, không ngại thử thách', 'Môi trường làm việc tại tập đoàn quốc tếTham gia các dự án Digitalization & Automation quy mô lớnCơ hội phát triển chuyên sâu về Data & AIChế độ BHXH, BHYT, BHTN theo quy địnhCác phúc lợi khác theo chính sách công ty', '-Huế:Hanesbrands Vietnam – Nhà máy, Phường Phú Bài', 833, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (109, 97, '1097307', 'Kỹ Sư Cầu Nối (Brse - Tiếng Nhật)', NULL, 40.00, '2 năm', 'Nhân viên', '2026-04-17 19:07:55.655775', '2026-05-09 19:07:55.655775', 5, 'Tham gia dự án với các đối tác/khách hàng Nhật Bản của công ty    Chịu trách nhiệm trao đổi với khách hàng Nhật Bản, phân tích làm rõ và chuyển các yêu cầu của khách hàng tới team dự án    Hỗ trợ các hoạt động tư vấn, đề xuất giải pháp.    Phối hợp thiết kế hệ thống/giải pháp cung cấp cho khách hàng trong dự án    Nghiên cứu và xây dựng giải pháp tiềm năng cho công ty có thể dễ dàng cung cấp cho khách hàng    Hỗ trợ và kết hợp với PM để quản lý tiến độ và chất lượng', 'Tốt nghiệp chuyên ngành CNTT, Mạng máy tính và truyền thông, Quản trị mạng.Có từ 2-3 năm kinh nghiệm về các vị trí liên quan: PM, BrSECó từ 2-3 năm kinh nghiệm lập trình trở lên với các ngôn ngữ bất kỳ: Java, C/C++, .Net, Python…Quản lý được thay đổi requirement, đánh giá được scope và đàm phán được với KH về scope, tạo schedule tương ứng.Có thể coding/unit test. IT execution, làm việc độc lập được tại site khách hàngKhả năng giao tiếp tốt với khách hàng và member dự án.Khả năng quản lý team size 5-10 ngườiTiếng Nhật từ N2, tự tin giao tiếp tốt với khách hàng', 'Thu nhập: Thỏa thuận theo năng lực (up to 40tr)Xét tăng lương 1 lần/năm, mức tăng theo năng suất và hiệu quả công việc, đóng góp thực tế vào dự án của công tyThưởng cuối năm và thưởng các ngày lễ, sinh nhật.Cơ hội tham gia nhiều dự án đa dạng, làm việc trực tiếp với khách hàng hàng đầu Nhật Bản trong lĩnh vực IT.Được tham gia vào các buổi đào tạo, seminar hàng tháng để nâng cao kỹ năng công việc và cùng nhau chia sẻ: knowledge base, working experience, lessons learn, best practices...Các chế độ theo quy định của pháp luật và phúc lợi đãi ngộ của công ty: BHXH, hiếu hỉ, ốm đau...Chế độ lương làm thêm giờ (OT) theo đúng quy định của pháp luậtTham gia vào các hoạt động teambuilding, du lịch thường niên, tiệc công ty, liên hoan kick-off, ngày lễ.Tham gia vào câu lạc bộ thể thao công ty: cầu lông, bóng đá, bi-aĐược trau dồi và phát triển kỹ năng ngoại ngữ: học tiếng NhậtMôi trường làm việc trẻ và năng động, tôn trọng phát triển cá nhân, công bằng và luôn khuyến khích sáng tạo để phát huy tối đa năng lực.Thời gian làm việc: từ thứ 2 đến thứ 6 (Nghỉ thứ 7, CN)', '-Hà Nội:Toà Viwaseen, 48 Tố Hữu, Phường Đại Mỗ', 166, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (110, 98, '1997046', 'Application Architect', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-18 19:07:55.655775', '2026-05-19 19:07:55.655775', 5, 'Leading the way in financial IT service market in Korea, we now seek to expand our expertise to the APAC.Participation in R&D AI Agent development Project Solution DevelopmentDesign scalable, secure, maintainable application architectureBuild and maintain automated CI/CD pipelines using modern devOps tools and practicesEstablish and promote software architecture standards, security guidelines, and design principlesDocumentation for architecturesCollaborate closely with development, QA, product, and operations teams', 'Application Architect experience (3 years or more)Architect ModelingExperience designing cloud-based applicationsCICD pipeline designExcellent communication skills and ability to work well with developersResource estimation based on draft architectureDesigning Modern Applications Using the Public CloudCommunicate in English at an average level', 'Attractive salary and bonus will be discussed after going through CV & InterviewTopik allowanceReview capacity annually and adjust salary increases according to work performance.Health care: Premium health insurance, Annual health check-upYoung working environmentGood career development opportunities with interesting and challenging projects.English, Korean, technical, soft skills training courses.Opportunity to learn special courses from LG CNS, new technology and security.Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)Outdoor activities with company support: sports clubs, team building, happy hour parties,birthdays, travel, employee and family events, etc.Working hours: 8 hours from Monday - Friday (8 hours/day)LocationKeangnam Landmark 72, Pham Hung, Yen Hoa, Hanoi', '-Hà Nội:keangnam, Phường Yên Hòa', 850, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (139, 123, '2011381', 'Backend Lead Engineer', 50.00, 70.00, '3 năm', 'Nhân viên', '2026-05-15 19:07:55.655775', '2026-06-13 19:07:55.655775', 5, 'NHỮNG KẾT QUẢ CỤ THỂ CẦN ĐẠT TRONG 6 - 18 THÁNGLàm chủ và tối ưu hóa thành công các ETL/ELT jobs và event pipelines để dữ liệu từ TikTok Shop, Shopify, Facebook đổ về hệ thống luôn chính xác và thời gian thực (Real-time).Thiết kế và chuẩn hóa lại Schema Data tối ưu cho việc truy vấn báo cáo hiệu suất (Product performance, Ads metrics).Dẫn dắt việc nâng cấp kiến trúc (Refactor/Microservices) giúp hệ thống chịu tải tốt hơn khi quy mô SKU và đơn hàng tăng trưởng đột biến.Xây dựng đội ngũ backend kế thừa thông qua việc thiết lập coding guidelines và mentoring.CHỈ SỐ ĐO LƯỜNG THÀNH CÔNGData Accuracy & Integrity: Tỷ lệ sai lệch dữ liệu giữa các nền tảng tích hợp (TikTok/Shopify) và hệ thống nội bộ < 1%.System Performance: Giảm thời gian phản hồi API và tối ưu hóa query plan cho các tập dữ liệu lớn (Heavy Data).Time-to-Market: Tốc độ chuyển hóa từ yêu cầu kinh doanh sang giải pháp kỹ thuật thực tế mà không cần qua trung gian PM.Engineering Quality: Tỷ lệ bug nghiêm trọng phát sinh sau release và hiệu quả của các buổi Code Review.', 'Thành thạo PHP/Laravel (bắt buộc) và có tư duy tốt về MySQL/Postgres (JSONB, Indexing, Transaction design).Khả năng nhìn bức tranh tổng thể để tìm "điểm gãy" của hệ thống trên nhiều phương diện: vận hành, logistics, marketing.Tự bóc tách logic kinh doanh thành phương án kỹ thuật khả thi, biết cân bằng giữa tốc độ triển khai và rủi ro kỹ thuật (Trade-off).Kinh nghiệm xây dựng Pipeline xử lý dữ liệu lớn và các hệ thống bất đồng bộ (Asynchronous pipeline, Queue/Worker).Phải xử lý vấn đề ngay cả khi yêu cầu từ phía Business chưa rõ ràng hoặc liên tục thay đổi theo thị trường eCommerce.Giải quyết bài toán hiệu năng khi đối mặt với lượng dữ liệu "khủng" từ các nền tảng quảng cáo và vận hành.Duy trì sự ổn định của hệ thống khi tích hợp với nhiều API bên thứ ba có độ phức tạp cao.', 'Môi trường "Thực chiến": Không làm outsourcing lẻ tẻ, bạn xây dựng sản phẩm cho hệ thống eCommerce thực tế, đa thị trường, đa nền tảng.Lộ trình phát triển đột phá: Cơ hội thăng tiến lên Solution Architect, nơi bạn không chỉ giỏi code mà còn am hiểu sâu sắc về cách vận hành một doanh nghiệp công nghệ toàn diện.Thu nhập cạnh tranh nhất thị trường, tương xứng với năng lực và hiệu quả công việc. Chúng tôi không giới hạn thu nhập vị trí này – giới hạn duy nhất chính là năng lực của bạn. Thưởng tháng 13 và thưởng kinh doanh cuối năm rõ ràng, minh bạchChính sách làm việc linh hoạt (Hybrid / Work From Home), đảm bảo cân bằng giữa công việc và cuộc sốngMôi trường làm việc hạnh phúc & hiện đại. Ghế công thái học 100% nhân viên. Pantry luôn đầy đồ ăn. Tiệc sinh nhật hàng tháng, du lịch nước ngoài. Bàn bi-a, không gian giải trí và văn phòng view tàu điện trên cao cực chillLàm việc với hệ thống eCommerce thực chiến, dữ liệu lớn, đa thị trường. Tiếp cận nhiều API lớn: TikTok Shop, Shopify, Facebook…', 'Trụ sở chính công ty', 924, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (111, 98, '1997026', 'Backend Java Engineer', NULL, NULL, '4 năm', 'Nhân viên', '2026-04-16 19:07:55.655775', '2026-05-23 19:07:55.655775', 5, 'Leading the way in financial IT service market in Korea, we now seek to expand our expertise to the APACParticipation in R&D AI Agent development Project Solution DevelopmentBackend Java DevelopmentRequirements analysis and designEnsuring own program quality', 'Web application development experience (4 years or more)Java programming experience (Spring, Spring Boot, Spring MVC)RDBMS (MySQL, PostgreSQL, MariaDB) & SQLExperience with collaboration tools such as Git, Jira and ConfluenceOptionalHave Python programming experienceSolid understanding of RESTful API design and implementationGood knowledge of SQL database management and optimizationGood knowledge of backend security, cryptography, and authentication protocolsExcellent communication skills and ability to work well in cross-functional teamsCommunicate in English at an average level', 'Attractive salary and bonus will be discussed after going through CV & InterviewTopik allowanceReview capacity annually and adjust salary increases according to work performance.Health care: Premium health insurance, Annual health check-upYoung working environmentGood career development opportunities with interesting and challenging projects.English, Korean, technical, soft skills training courses.Opportunity to learn special courses from LG CNS, new technology and security.Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)Outdoor activities with company support: sports clubs, team building, happy hour parties,birthdays, travel, employee and family events, etc.Working hours: 8 hours from Monday - Friday (8 hours/day)LocationKeangnam Landmark 72, Pham Hung, Yen Hoa, Hanoi', '-Hà Nội:keangnam, Phường Yên Hòa', 211, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (113, 98, '1997032', 'Backend Python Developer For AI Agent Development Project', NULL, NULL, '4 năm', 'Nhân viên', '2026-04-24 19:07:55.655775', '2026-05-27 19:07:55.655775', 5, '[Hanoi] LG CNS is looking for a Python Backend Developer to join our R&D team. In this role, you''ll be responsible for designing and implementing backend solutions that support AI-driven applications. You''ll leverage your expertise in Python and modern backend technologies to build secure, scalable, and high-performance APIs and services, ensuring solution quality and maintainability.Job DescriptionParticipate in AI Agent solution development projects, collaborating with cross-functional teams.Implement backend features using Python/Java and related frameworks.Analyze requirements and contribute to design discussions for specific AI-driven solutions.Develop and maintain RESTful APIs for integration with AI components and services.Work with RDBMS (MySQL, PostgreSQL, MariaDB) and optimize SQL queries for performance.Ensure backend security, including cryptography and authentication protocols.Deliver maintainable, documented, and high-quality backend components.', '[Required]Bachelor degree in Computer Science, Software Engineering, or related field.4+ years of experience in web application development.Strong experience with Python/Java programming and backend development.Solid understanding of RESTful API design and implementation.Good knowledge of SQL database management and optimization.Experience with collaboration tools such as Git, Jira, and Confluence.Average English communication skills for team collaboration. [Preferred]Experience with Python programming.Knowledge of backend security, cryptography, and authentication protocols.Excellent communication skills and ability to work well in cross-functional teams.', 'Attractive salary and bonus will be discussed after going through CV & Interview.Topik allowance.Review capacity annually and adjust salary increases according to work performance.Health care: Premium health insurance, Annual health check-up.Young working environment.Good career development opportunities with interesting and challenging projects.English, Korean, technical, soft skills training courses.Opportunity to learn special courses from LG CNS, new technology and security.Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.).Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.', '-Hà Nội:Keangnam, Phường Yên Hòa', 591, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (114, 99, '2034851', 'Nhân Viên Chỉnh Sửa Video AI', NULL, NULL, 'Không yêu cầu', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-10 19:07:55.655775', 7, 'Sản xuất video bằng các công cụ chỉnh sửa video AISản xuất video cho nội bộ công ty và khách hàng bên ngoàiQuản lý, chỉnh sửa video SNS và video quảng báQuản lý chất lượng tổng thể của nội dung video', 'Ưu tiên tốt nghiệp ngành video, media, thiết kếƯu tiên có kinh nghiệm sản xuất video SNS, video quảng bá doanh nghiệp/dịch vụKhông ngại sử dụng các công cụ chỉnh sửa video bằng AIƯu tiên ứng viên có kinh nghiệmỨng viên chưa có kinh nghiệm vẫn có thể ứng tuyển (với điều kiện tốt nghiệp ngành liên quan đến chỉnh sửa video)', 'Mức lương thỏa thuận theo năng lực và kinh nghiệmTham gia đầy đủ BHXH, BHYT, BHTN theo quy định của pháp luậtThưởng lễ, Tết theo quy định công tyNghỉ phép năm, nghỉ lễ theo quy định của Nhà nướcMôi trường làm việc chuyên nghiệp, thân thiệnĐược đào tạo trong quá trình làm việcCơ hội phát triển và thăng tiến', '-Hồ Chí Minh:Số 15 Đường số 21, Khu dân cư Phước Kiển, Ấp 89 TP Hồ Chí Minh, Việt Nam, Xã Nhà Bè', 672, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (115, 100, '2036436', 'Chuyên Viên IT Software', NULL, NULL, '2 năm', 'Nhân viên', '2026-05-17 19:07:55.655775', '2026-06-09 19:07:55.655775', 5, 'Quản trị, vận hành hệ thống (database, server) đảm bảo tính ổn định, liên tục của hệ thống.Tiếp nhận, hỗ trợ, hướng dẫn người dùng các vấn đề liên quan đến nghiệp vụ và sử dụng ứng dụng mobile.Phối hợp với bộ phận phát triển phần mềm để tìm ra nguyên nhân và xử lý một cách triệt để.Thực hiện các nhiệm vụ khác được cấp trên phân công.', 'Tốt nghiệp Cao đẳng trở lên chuyên ngành Công nghệ thông tin, hoặc chuyên ngành về vận hành ứng dụng.Có ít nhất 02 năm trong lĩnh vực liên quan phần mềm, hệ thốngCó kiến thức về lập trình ứng dụng, quản trị hệ thống phần mềm.Ưu tiên ứng viên lập trình được ngôn ngữ Node JS, React để chỉnh sửa và hỗ trợ kịp thời các ứng dụng.Có kỹ năng phân tích, kỹ năng làm việc nhóm, và giao tiếp', 'Thu nhập: Cạnh tranh theo năng lực05 ngày làm việc/tuần với 8h/ngàyXét lương hàng năm12 ngày phép năm + 01 ngày nghỉ lễ công ty + 0.5 ngày nghỉ sinh nhậtĐược tham gia đóng BHXH, BHYT theo quy định của nhà nướcMôi trường làm việc trẻ trung, năng độngHoạt động team building, du lịch…', '-Hà Nội:Lotte Mall Tây Hồ, Phường Tây Hồ', 119, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (119, 105, '2032482', 'Senior Product Designer (AI-Powered Product Lab / Startup Studio)', 30.00, 45.00, '5 năm', 'Nhân viên', '2026-05-20 19:07:55.655775', '2026-06-07 19:07:55.655775', 7, 'About UsOS Research is a startup studio building AI-powered products across multiple industries. We move fast, ship weekly, and use AI tools to work at 2-3x the speed of traditional teams.We''re looking for a designer who can make complex products feel simple and beautiful.The RoleYou''ll be the lead designer for 1 (or more) of these 4 products:1. OSR Venture Creation EngineOur flagship product. A website + platform where founders validate startup ideas through structured experiments.Public website with CMS (brand, content, case studies)Research & Validation platform (dashboards, experiment tracking, analytics)2. InsurTech PlatformA digital insurance platform for enterprise clients. Claims management, SLA tracking, micro transactions.Admin dashboardsMobile-friendly interfacesComplex data visualization3. B2B AdTech PlatformA trip-based advertising platform for vehicle fleets. Programmatic ad distribution across moving screens.Campaign management UIReal-time analyticsAdvertiser self-serve tools4. Voice Interface PlatformAn AI-powered app that helps users improve their speech through practice and feedback.Conversation interfacesProgress trackingAudio/visual feedback systemsWhat You''ll DoOwn the end-to-end design process from scratch: research, wireframes, UI, prototypes, handoffCreate modern, visually pleasing interfaces that users actually enjoyBuild and maintain lean design systems across multiple productsCollaborate directly with founders and developers (no layers)Use AI tools to generate options fast, then refine with tasteRun quick user tests and iterate based on real feedbackYou Should BeStrong in both UX and UI. You can map complex user flows AND make them look beautiful. Not one or the other, both.AI-native. You already use Figma AI, Midjourney, ChatGPT, Galileo, or similar tools daily. You have opinions about what works.Fast without sacrificing quality. You compress 2-week cycles into days. You know when to polish and when to really ship.Experienced with AI-powered products. You''ve designed apps with AI features — chat interfaces, recommendations, voice, automation. You understand the UX patterns.Visually excellent. Your portfolio makes people stop scrolling. Modern, clean, with attention to detail.', 'RequirementsMust have:5+ years of product design experience across industriesPortfolio showing both UX thinking and strong visual designExperience designing AI-powered or data-heavy applicationsFigma expert (components, auto-layout, prototyping, design systems)Strong understanding of the whole product development processCurrently using AI tools in your workflowNice to have:Experience with B2B SaaS, InsurTech, or AdTech (or created any app that had more than 10K monthly users)Motion design / micro-interactionsCan implement in Framer or WebflowSome understanding of frontend development or no-code, low-code development.', 'What We OfferStarting Salary: 30,000,000 VND gross/month. Can go up to 45,000,000 VND if you pass probation with excellent resultsWork style: Hybrid in HCMCEquipment: iMac M4 in the officeTools: Paid subscription to the best AI tools and softwaresKey benefits: 100% gross-based social insurance coverage. 13th-month bonus. Regular cash bonus tied to KPIs. Salary raise every 6 months for exceptional performance.Autonomy & Impact: You own your work. Fast and straightforward approval process. Your work ships to real people and has a chance to spin off into real and meaningful ventures.', '-Hồ Chí Minh:28 Thao Dien, Phường An Khánh', 932, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (120, 106, '2036357', 'Software Engineer - Pair Programming With AI', NULL, NULL, 'Dưới 1 năm', 'Nhân viên', '2026-04-30 19:07:55.655775', '2026-06-10 19:07:55.655775', 7, 'Giai đoạn hiện tai, AI đang trỗ dậy mạnh mẽ, trong lĩnh vực phần mềm càng thấy rõ điều đó. Từ phân tích, lên kế hoạch, lập trình, kiểm thử, triển khai, bảo trì.Alliance đang tìm kiếm các lập trình viên có xu hướng sử dụng sức mạnh của AI trong việc phát triển phần mềm.  Học cách điều khiển AI, hiểu AI và biến AI thành sức mạnh của mình.', 'Khi AI đã lập trình quá tốt, bạn có thể không cần phải code. Khi AI đã viết Unit Test quá đầy đủ, bạn không cần phải tạo thêm. Nhưng bạn cần hiểu nó. Nên tối thiểu bạn sẽ cần có tư duy tốt để hiểu được mục tiêu đang là gì.Tốt nghiệp đại học các chuyên ngành liên quan tới công nghệ thông tin.Giao tiếp rất quan trọng để bạn có thể làm việc nhóm tốtĐã từng Vibe Coding là một lợi thếCó kiến thức nền tảng một bất cứ 1 lĩnh vực cụ thể: Web, Mobille ….', 'Thưởng tháng 13Du lịch hàng năm (thường vào tháng 4 hằng năm)Thưởng theo dự án (căn cứ vào hiệu quả của bạn trong project)Một môi trường trẻ trung để hòa mình.Nhiều lead không ngừng chia sẻ để cùng lớn.Và những projects giúp chúng ta cùng phát triển.', '-Hồ Chí Minh:Căn B7-D1.TMDV.02, Lô B7, Lumière Boulevard, Số 8, Đường D1, Phường Long Bình', 995, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (121, 106, '2036499', 'QC/Tester - Pair WITH AI', NULL, NULL, 'Dưới 1 năm', 'Nhân viên', '2026-05-06 19:07:55.655775', '2026-06-03 19:07:55.655775', 7, 'Sẽ sử dụng AI Agent rất nhiều để đẩy tốc độ và chất lượng lênHiểu yêu cầu dự án, xây dựng test plan, test casesXây dựng e2e test (playwright), api test (k6)', 'Khi AI đang và sẽ mạnh hơn mỗi ngày, Bạn cần vận động nhiều hơn để kiểm soát được AI. Biến AI thành trợ thủ đắc lựcTốt nghiệp đại học các chuyên ngành liên quan tới công nghệ thông tin.Giao tiếp rất quan trọng để bạn có thể làm việc nhóm tốt', 'Thưởng tháng 13Du lịch hàng năm (thường vào tháng 4 hằng năm)Thưởng theo dự án (căn cứ vào hiệu quả của bạn trong project)Một môi trường trẻ trung để hòa mình.Nhiều lead không ngừng chia sẻ để cùng lớn.Và những projects giúp chúng ta cùng phát triển.', '-Hồ Chí Minh:Căn B7-D1.TMDV.02, Lô B7, Lumière Boulevard, Số 8, Đường D1, Phường Long Bình', 586, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (124, 109, '2027035', 'Senior PHP Fullstack Developer (SaaS Product) - Phú Nhuận', 32.00, 45.00, '5 năm', 'Nhân viên', '2026-05-06 19:07:55.655775', '2026-06-15 19:07:55.655775', 7, '3 Lý do bạn không thể bỏ lỡ Rakus Vietnam1. Không rào cản ngôn ngữ (No English/Japanese Required)Tại Rakus, "Code" là ngôn ngữ duy nhất. Chúng tôi không yêu cầu kỹ năng tiếng Anh hay tiếng Nhật. Bạn chỉ cần tập trung vào chuyên môn kỹ thuật. Mọi rào cản ngôn ngữ đã có đội ngũ Comtor hỗ trợ.2. 3 kỳ nghỉ dài (9 ngày liên tục/kỳ) mỗi nămChúng tôi trân trọng thời gian bạn dành cho gia đình. Ngoài kỳ nghỉ Tết Âm lịch, công ty chủ động thiết lập các kỳ nghỉ đặc biệt vào dịp Golden Week (tháng 4-5) và Năm mới Dương lịch (tháng 12-1). Mỗi dịp này bạn sẽ được nghỉ liên tục 9 ngày.Bạn có thể thoải mái du lịch hay về quê mà không cần dùng đến phép năm!Tổng số ngày nghỉ lễ trong năm lên đến hơn 30 ngày.3. Nền tảng vững chắc (PHP/Java) x Công nghệ AI (Github Copilot, v.v.)Chúng tôi phát triển sản phẩm SaaS ổn định được hơn 10.000 doanh nghiệp Nhật Bản tin dùng, nhưng quy trình làm việc luôn được cập nhật mới nhất.Cấp tài khoản GitHub Copilot bản quyền cho toàn bộ kỹ sư.Cấp tài khoản Devin, Claude Code cho những ai có nhu cầu.Bạn sẽ phát triển thành một "Hybrid Engineer" – vừa có nền tảng Backend vững chắc, vừa thành thạo các công cụ AI hiện đại. Rakus Việt Nam là công ty 100% vốn đầu tư từ RAKUS Co., Ltd. - công ty nổi tiếng hàng đầu tại Nhật Bản cung cấp các dịch vụ đám mây (SaaS), giúp các doanh nghiệp điều hành hoạt động của mình một cách nhanh chóng, tiện dụng nhất. Chúng tôi đang tuyển dụng 3 vị trí PHP Software Engineer, level Senior trở lên: LÀM VIỆC OFFLINE FULLTIME TẠI VĂN PHÒNG CHI NHÁNH PHÚ NHUẬN- Domain: Hệ thống phần mềm phát hành và quản lý email Marketing - đang được sử dụng bởi hơn 1,7tr end-users tại thị trường Nhật Bản. Nếu:・Bạn muốn tham gia phát triển một dự án lớn có độ khó cao về nghiệp vụ, là một trong những thành viên đầu tiên của team. ・Bạn có định hướng thăng tiến lên Principal Software Engineer/Technical Leader.・Bạn mong muốn môi trường làm việc lâu dài (ít nhất 3 năm trở lên)・Bạn có năng lực tập trung và thích tìm hiểu sâu về 1 hệ thống. Hãy gia nhập đội ngũ phát triển series sản phẩm "Rakuraku" – SaaS chiếm thị phần số 1 tại Nhật Bản.- Cùng Project Leader và các kỹ sư Nhật Bản phân tích đặc điểm kỹ thuật của sản phẩm, các thay đổi đặc điểm kỹ thuật và các chức năng mới bổ sung .- Tham gia vào phát triển các dự án với vai trò Senior/Principal Software Engineer từ giai đoạn Outline Design, Detail Design, Development/Implementation, Code review, Unit test, Release. Hoặc được đào tạo để trở thành Principal Software Engineer.- Môi trường làm việc linh hoạt: Làm việc theo quy trình Scrum, nơi mỗi thành viên cần chủ động và có trách nhiệm.- Phát triển Front-end: Sử dụng Vue.js để đảm bảo giao diện tích hợp tốt với Back-end.- Hạ tầng Cloud: Đóng góp vào việc thiết kế và triển khai giải pháp trên AWS.- Cải tiến: Chủ động sử dụng AI, nghiên cứu cải tiến và đóng góp ý tưởng cho sản phẩm/quy trình.', 'Yêu cầu cơ bản:Có từ 5 năm kinh nghiệm trở lên làm việc với PHP trong các dự án phát triển web application (Development, Refactoring, Unit Test). Có kinh nghiệm với 1 (hoặc nhiều) trong các framework của PHP như: Laravel, WordPress, CodeIgniter, Yii 2, CakePHP, ZendCó kinh nghiệm làm việc với Framework Javascript như: Vuejs, Reactjs, AngularjsThành thạo HTML, SCSS, Javascript, Jquery, Json, Smarty, NodejsCó kinh nghiệm làm việc với server CentOSThành thạo PostgreSQL hoặc MySQLCó khả năng thiết kế DB và tối ưu performance hệ thốngThành thạo Git (UI/Command) Có kinh nghiệm research kỹ thuật mới Ưu tiên:Sẵn sàng học hỏi và làm việc với framework mới của PHP.Đã từng làm Team Leader/Senior dự án từ 2 developers trở lên là một lợi thếCó kiến thức về việc tích hợp với Front-end dùng Vue.js.Có kiến thức làm việc chuyên nghiệp với nền tảng Cloud: AWS, Azure, GCPCó kiến thức về CI/CD và Docker.Có kiến thức về các nguyên tắc kỹ thuật phần mềm (tiêu chuẩn code, review code, testing, monitoring...).Có khả năng đọc, hiểu và phân tích yêu cầu nghiệp vụ từ phía khách hàng Có khả năng phát hiện và giải quyết vấn đề tốt.Có khả năng tạo/trình bày tài liệu kĩ thuật dễ hiểu và chia sẻ kiến thức với đồng nghiệp Có khả năng giao tiếp tốt Sử dụng hiệu quả các công cụ AI như Github copilot, Gemini, Claude, Cursor, …Hiểu biết về quy trình phát triển Scrum là một lợi thế.Hiểu quy trình và phong cách làm việc tại công ty Nhật là một lợi thế. Lưu ý: Không tuyển ứng viên nước ngoài.', 'Tại sao Rakus được yêu thích?Không chỉ là lương thưởng, chúng tôi chăm sóc cuộc sống và gia đình bạn theo phong cách Nhật Bản: "Tận tâm và An tâm".  Tài chính vững mạnh (Solid Finance)Chắc chắn "14 tháng lương": Bao gồm lương tháng 13 + 1 tháng thưởng cố định (được nhận bất kể KPI). Tài chính gia đình bạn luôn được đảm bảo.Xét tăng lương: 2 lần/năm. Lộ trình thăng tiến rõ ràng, cấp trên sẽ hỗ trợ bạn thăng cấp để đạt mức lương cao hơn.Công ty đóng BHXH ở mức 100% lương gross.100 % lương trong thời gian thử việc. Sức khỏe & Gia đình (Health & Family Care)Bảo hiểm đặc biệt: Chi phí y tế của bạn được chi trả phần lớn bởi gói bảo hiểm cao cấp do công ty đài thọ.Hỗ trợ người thân: Hỗ trợ thủ tục để vợ/chồng và con cái tham gia gói bảo hiểm nhóm của công ty (tự nguyện).Nghỉ phép siêu linh hoạt: 12 ngày phép năm có thể chia nhỏ để nghỉ theo "đơn vị 30 phút"."Sáng đưa con đi học", "Chiều về sớm đón con", "Đưa người nhà đi khám bệnh"... Tất cả đều OK! Chúng tôi ủng hộ tuyệt đối việc bạn chăm sóc gia đình.Khám sức khỏe định kỳ. Niềm vui & Kết nối (Community)Du lịch 5 sao: Company Trip hàng năm (3 ngày 2 đêm) tại các resort cao cấp. Tài trợ 50% chi phí tour cho gia đình nhân viên.Sự kiện liên tục: Tiệc sinh nhật hàng tháng, Year End Party hoành tráng, Lì xì Tết, quà tặng Trung thu, ngày phụ nữ, ngày nam nhân,  Giáng sinh, ...Ngân sách team: Cấp 170.000 VND/người/tháng cho team building (ăn uống, cafe, picnic cùng đồng nghiệp).Tham gia các CLB thể thao (Futsal, cầu lông) Thời giờ làm việc, nghỉ ngơiThứ 2 - thứ 6, từ 8:30 - 17:3012 ngày phép năm + 11 ngày nghỉ lễ lịch VN + 7 ngày nghỉ lễ lịch Nhật = 30 ngàyHầu như Không làm thêm giờ (No Overtime)Đào tạoCơ hội được cử đi Nhật đào tạo. Các kỹ sư người Nhật hỗ trợ OJT (on the job training)Training kỹ năng mềm theo levelSeminar kỹ thuật hàng tháng Giải thưởngMVP of the Year – Nhân viên xuất sắc mỗi năm được trải nghiệm và làm việc tại Nhật 1 tuần.Quarterly MVP – Giải thưởng Nhân viên xuất sắc của QuýGiải thưởng nhân viên 5 năm, ...', '-Hồ Chí Minh:Tầng 6, Tòa Nhà 3 Bees Tower, 281 Nguyễn Văn Trỗi, Phường Phú Nhuận', 936, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (126, 110, '2033848', 'Python Techlead', NULL, NULL, 'Trên 5 năm', 'Nhân viên', '2026-04-18 19:07:55.655775', '2026-05-08 19:07:55.655775', 5, '''The project improves and optimizes data processing performance.- Understand analysis/design documents and develop Python programs, performing unit testing.- Develop and implement new features and functionalities within the existing system.- Produce and manage Unit‑Test Result Reports.- Collaborate effectively with cross-functional teams to ensure successful project delivery.- Troubleshoot and debug issues related to application performance and functionality.- Code Review & Quality Management for team members.- Developer Skill‑Based Scheduling & Task Management- Problem Solving & Performance Tuning', 'Requirements:- University degree in IT, Computer Science, or related experiences.- Good understanding of SQL, Oracle DB and Python.- At least 6 years of Python development experience.- Experience conducting code reviews and mentoring team members.- Ability to schedule and assign tasks based on developers’ skill levels.- Good communication skill - Having self-management mindset- Having ability to work independentlyNice to have- Experience with Cloud Hadoop (kudu/impala, Hbase)- Experience with API, DevOps- Hands‑on experience with containers/orchestration (Kubernetes)', 'SALARY, INSURANCESalary negotiable100% salary during 2-month probationFull-salary insurance starting right from probation period3 times to receive bonusHealth check once per yearAccident insurancePremium Health insurance packageTRAINING & DEVELOPMENT:Annual budget for personal training and Udemy AccountOversea training opportunitiesOTHER BENEFITS:Numerous internal activities: team bonding, team training,...Gifts for each employee on 30/4,1/5; 2/9....(in cash)5 working days per week to ensure work-life balance', '-Hà Nội:Phường Yên Hòa', 767, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (127, 110, '2036629', 'Fullstack Developer', NULL, NULL, '5 năm', 'Nhân viên', '2026-05-03 19:07:55.655775', '2026-05-30 19:07:55.655775', 5, '• Interpreting, analyzing and implementing client’s requests • Analysis requirement, design, develop and maintain web application using Java and React JS• Performing quality verification including code review, code inspection, performance test, etc. • Developing interface for the integration with relevant system (Rest)• Understanding development process and ensuring compliance (Risk management system for the internal accounting)', '''• Recommended to have at least 5 years of experience in the both of the front-end and back-end of Web development using Java• Strong proficiency in Java programming language and related technologies• Experience with Java framework like Spring Boot, Spring Batch• Experience with HTML, CSS, Javascript and front-end framework • Experience with  Restful APIs• Experience with relational database(PostgreSQL, Oracle) and NoSQL database(MongoDB, Redis, DynamoDB)• Hands-on experience with various AWS service• Strong ability to troubleshoot and debug issues across the entire Web application stack• Capable of developing and tuning standard SQL • Having basic knowledge in the improvement of program performance (Documentation and analysis of Execution Plan)• Tool : Bitbucket, Jenkins, Datadog, CI/CD• Software life cycle development: Agile, Waterfall• Good communication skill• Having Self-Management Mindset• Having ability to work independently.', 'SALARY, INSURANCESalary negotiable100% salary during 2-month probationFull-salary insurance starting right from probation period3 times to receive bonusHealth check once per yearAccident insurancePremium Health insurance packageTRAINING & DEVELOPMENT:Annual budget for personal training and Udemy AccountOversea training opportunitiesOTHER BENEFITS:Numerous internal activities: team bonding, team training,...Gifts for each employee on 30/4,1/5; 2/9....(in cash)5 working days per week to ensure work-life balance', '-Hà Nội:Phường Cầu Giấy', 475, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (129, 112, '2033385', 'Nhân Viên Thiết Kế  Chế Bản File Tem Nhãn Bao Bì In Ấn (Phỏng Vấn Đi Làm Sau Tết)', 10.00, 16.00, '1 năm', 'Nhân viên', '2026-04-27 19:07:55.655775', '2026-05-13 19:07:55.655775', 7, '- Thiết kế hoặc chỉnh sửa file: Tem nhãn, bao bì giấy, bao bì nhựa mềm, catalogue, brochure, hộp mềm,... - Làm việc trực tiếp với bộ phận kinh doanh để lên ý tưởng thiết kế theo yêu cầu của khách hàng.- Chỉnh sửa file in, bình bài, xuất file in theo đúng quy chuẩn kỹ thuật.- Hỗ trợ xử lý file, đảm bảo chất lượng hình ảnh, màu sắc trước khi in.- Phối hợp với xưởng in để theo dõi, kiểm tra thành phẩm.làm việc tại 97 tân hiệp 13, ấp 19, xã tân hiệp , huyện hóc mônvào google map gõ xưởng in mai thành phát là ra định vị', '- Tốt nghiệp Trung cấp trở lên các ngành về đồ họa , thiết kế công nghiệp.- Có 1 năm kinh nghiệm tại vị trí tương đương (Chấp nhận sinh viên mới ra trường và đào tạo đầu vào) - Sử dụng thành thạo các phần mềm thiết kế đồ họa thông dụng như Illustrator, Photoshop, biết Corel - Có các kỹ năng ghép file hoặc chấp nhận được đào tạo - Yêu cầu đạo đức tốt, cẩn thận, trách nhiệm - Độ tuổi từ 20 tuổi đến 35 tuổi', '- Thu nhập 10.000.000 - 16.000.000 triệu/tháng cạnh tranh- Được hưởng các chế độ đầy đủ theo quy định -Thăng tiến trong công việc, mức lương không hạn chế theo khả năng- Môi trường làm việc chuyên nghiệp, năng động và thân thiện, được đào tạo thêm nhiều kỹ năng', '-Hồ Chí Minh:97 tân hiệp 13, ấp 19, xã tân hiệp , huyện hóc môn, Xã Hóc Môn', 417, NULL, 1);
