INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (144, 129, '2016503', 'Senior Designer', 11.00, 16.00, '2 năm', 'Nhân viên', '2026-05-09 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, '-      Thiết kế ấn phẩm Online cho các kênh Social: Banner, cover fanpage, post social media (lĩnh vực chủ yếu BĐS, kênh TMĐT, Bank,...)-      Thiết kế tĩnh video, tĩnh GDN, Google, Landing page dự án.-      Thiết kế video chuyển động đơn giản cho GDN và video dự án.-      Tương tác với bộ phận Media và Content để đưa ra ý tưởng cho các dự án truyền thông/marketing khác nhau.-      Xử lý các công việc phát sinh khác theo yêu cầu của Quản lý trực tiếp.', '-      Trình độ: Đại học, cao đẳng hoặc các chứng chỉ về chuyên môn Thiết kế.-      Sử dụng tốt các phần mềm thiết kế Photoshop, illustration, Adobe Animate CC (biết thêm là một lợi thế).-      Sáng tạo, có kiến thức tốt về mỹ thuật và khả năng trình bày ý tưởng.-      Chịu được áp lực về chất lượng và bảo đảm tiến độ công việc, có tinh thần trách nhiệm cao.-      Ham học hỏi, kiên trì, quan điểm sống tích cực, cầu tiến.-      Kinh nghiệm 2-3 năm trở lên.', '-      Làm việc trong môi trường năng động, chuyên nghiệp.-      Cơ hội được đào tạo & huấn luyện nâng cao kỹ năng chuyên môn và khả năng sử dụng phần mềm mới.-      Tham gia Teambuilding theo quý 3-4 lần/năm.-      Được review lương hàng năm.-      Hưởng các chế độ lao động theo quy định của nhà nước.Thông Tin khác:-      Thời gian làm việc từ 9:00 sáng đến 12:00 trưa và từ 1:00 chiều đến 5:30.-      Làm việc từ thứ 2 đến thứ 6 hàng tuần và buổi sáng thứ 7 đầu tiên của tháng, nghỉ CN.-      Hồ sơ bao gồm CV + Portfolio (các artwork đã thực hiện)', '-Hà Nội:Tòa Việt Á, số 9 Phố Duy Tân, Phường Cầu Giấy', 760, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (146, 131, '1518593', 'Thiết Kế Và Sản Xuất Animator Tại Hồ Chí Minh (Lương 20tr - 35tr) CV Tiếng Anh Và Portfolio File Video', 20.00, 35.00, '5 năm', 'Nhân viên', '2026-05-09 19:07:55.655775', '2026-06-11 19:07:55.655775', 7, 'Sản xuất animation nhân vật virtual idol Chỉnh sửa mocap animation và tạo ra những biểu cảm tự nhiên cho nhân vậtTạo pose cho nhân vật và có hiểu biết về cấu trúc cơ thểThể hiện được biểu cảm, cảm xúc, động tác vv của nhân vật.', 'Yêu cầu bắt buộc: nộp CV (tiếng anh) và PortfolioCó ít nhất 3 năm kinh nghiệm trong lĩnh vực AnimationThành thạo các phần mềm liên quan như Maya vvCó kiến thức cơ bản về 3D modeling và thiết kế nhân vậtCó kinh nghiệm sản xuất game animationKỹ năng giao tiếp và hợp tác tốtỨng viên quan tâm và yêu thích Kpop và virtual idol.Ứng viên quan tâm tới kỹ thuật & xu hướng animation mới nhất.Lưu ý: Yêu cầu bắt buộc nộp Portfolio video (File mp4 hoặc link video. Các hồ sơ thiếu Portfolio sẽ tự động bị loại)
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (147, 131, '1518603', 'Unreal Engine Artist Tại Hồ Chí Minh (Lương 10tr - 30tr) CV Tiếng Anh Và Portfolio File Video', 10.00, 30.00, '1 năm', 'Nhân viên', '2026-05-13 19:07:55.655775', '2026-06-23 19:07:55.655775', 7, 'Ưu tiên cho những Artist có kinh nghiệm phát triển trên phần mềm Unreal Engine, làm phim hoạt hình nhân vật.
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (150, 135, '2028629', 'QA Leader (Kỹ Sư Đảm Bảo Chất Lượng / Trưởng Nhóm QA) - Tiếng Nhật N2 Trở Lên Hoặc Từng Làm Việc Tại Công Ty Nhật', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-16 19:07:55.655775', '2026-05-27 19:07:55.655775', 7, 'Với vai trò là Leader của team QA, bạn sẽ phụ trách quản lý và thúc đẩy toàn bộ quy trình kiểm thử:• Quản lý task của QA team, hướng dẫn – đào tạo các thành viên, thực hiện review 
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (152, 137, '2036335', '(JP 223) Kỹ Sư Lập Trình Vận Hành Máy Gia Công NC (CAD/CAM Programmer) Đi Nhật Miễn Phí', 65.20, 81.50, '2 năm', 'Nhân viên', '2026-05-03 19:07:55.655775', '2026-06-06 19:07:55.655775', 10, 'Nơi làm việc ：Kanagawa, Nhật BảnNgày phỏng vấn ：Thứ Ba, 24/03/2026Ngày bắt đầu ：thương lượngSố lượng tuyển ：1 ngườiMức lương tháng ：từ 400,000 đến 500,000 yên/gross (thay đổi tùy vào kinh nghiệm)Trợ cấp tham gia PV ：1,000,000 vnd（bất kể kết quả đậu hay rớt） Nội dung công việc• Lập trình gia công tiện, cắt, gọt sử dụng CAD/CAM• Chỉnh sửa dữ liệu biến số dựa trên macro program có sẵn để phù hợp với nội dung bản vẽ• Soạn thảo thủ công chương trình NC cho các gia công vận hành đơn giản• Thiết kế bản vẽ đồ gá (bản vẽ 2D)• Và các công việc liên quan khácĐặc biệt• Công ty rất thân thiết với người Việt Nam• Công ty có nhiều người Việt làm lâu dài, người Nhật cũng quen giao tiếp với người Việt, hướng dẫn công việc cụ thể, tận tâm.', 'Yêu cầu công việc (bắt buộc)Kinh nghiệm tạo chương trình gia công cho máy NCTiếng Nhật từ N3 trở lên Yêu cầu công việc (hoan nghênh)• Có trên 2 năm kinh nghiệm lập trình NC cho gia công cơ khí• Có kinh nghiệm làm việc tại công ty Nhật Bản• Có chứng chỉ cẩu móc và vận hành cần trục (crane)• Có kinh nghiệm lập trình hoặc trực tiếp gia công NC cho: Tiện chi tiết dài (long shaft turning), phay và doa (boring) các chi tiết kết cấu• Có kinh nghiệm lập trình hoặc sử dụng một trong các hệ NC sau: FANUC, TOSNUC, MELDAS, MAZATROL• Có hiểu biết và kinh nghiệm tạo/lập trình custom macro cho hệ NC• Có kinh nghiệm sử dụng 2D/3D CAD/CAM để lập trình NC• Có kinh nghiệm sử dụng các phần mềm như: AutoCAD, Inventor, Fusion• Có kinh nghiệm sử dụng MAZATROL DX (DX-CAM của Yamazaki Mazaki)', 'Tăng lương: 1 lần/nămTrợ cấp nhà ởCác loại bảo hiểm xã hội đầy đủ (hưu trí, y tế, thất nghiệp, chăm sóc sức khỏe)Khám sức khỏe định kỳ 1 lần/nămNghỉ thứ 7, chủ nhật, lễ tết, nghỉ hè, nghỉ cuối năm và phép năm (hơn 125 ngày/năm)', '-Nhật Bản', 474, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (167, 148, '2036043', 'Chuyên Viên Mua Sắm- Đấu Thầu Dự Án Công Nghệ Thông Tin', NULL, NULL, '2 năm', 'Chuyên viên đấu thầu', '2026-05-22 19:07:55.655775', '2026-06-24 19:07:55.655775', 5, 'Thực hiện công tác hỗ trợ phát triển kinh doanh thông qua việc tham gia chuẩn bị, hoàn thiện hồ sơ dự thầu, hồ sơ chào giá, hồ sơ đề xuất theo yêu cầu của từng gói thầu/dự án.
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (38, 32, '2018405', 'Trưởng Bộ Phận Triển Khai Vận Hành - Thu Nhập Hấp Dẫn  - Nhận Việc Ngay - Tại Thanh Xuân, Hà Nội', NULL, NULL, '5 năm', 'Nhân viên', '2026-04-09 19:07:55.655775', '2026-05-04 19:07:55.655775', 5, 'Lãnh đạo và quản lý toàn bộ hoạt động triển khai, vận hành hệ thống tại khu vực Miền Bắc, đảm bảo tiến độ, chất lượng và hiệu quả.Xây dựng, cải tiến và giám sát quy trình triển khai dự án, vận hành, bảo trì và giám sát hệ thống tại khu vực phụ trách.Quản lý đội ngũ kỹ sư triển khai và vận hành, phân công công việc, theo dõi hiệu quả và phát triển nhân sự.Phối hợp với các phòng ban khác và các chi nhánh để triển khai giải pháp công nghệ, tối ưu hóa hiệu suất hệ thống và nâng cao chất lượng dịch vụ.Xây dựng tài liệu hướng dẫn sử dụng, tài liệu hướng dẫn vận hành. Thuyết trình giới thiệu, mô phỏng các mô hình, hệ thống.Báo cáo hoạt động các hệ thống theo định kỳ.Thực hiện các công việc khác theo sự phân công của Quản lý trực tiếp.', 'Tác phong chuyên nghiệp, làm việc có hệ thống, tư duy mạch lạc, tinh thần trách nhiệm cao.Tốt nghiệp Đại học/Cao đẳng chuyên ngành CNTT, Tin học, Khoa học máy tính, Điện tử, Viễn thông hoặc sở hữu các chứng chỉ liên quan Tin học, Viễn thông, CNTT.Kinh nghiệm ít nhất 5 năm triển khai và vận hành hệ thống CNTT, ưu tiên có kinh nghiệm quản lý bộ phận.Am hiểu về hạ tầng mạng, server, lưu trữ, cloud, bảo mật hệ thống và các quy trình vận hành. Có kinh nghiệm triển khai dự án về hạ tầng, DC, network, firewall quy mô trung bình hoặc lớn.Kỹ năng lãnh đạo, lập kế hoạch, giải quyết vấn đề và làm việc dưới áp lực cao.Yêu cầu có chứng chỉ Cisco Certified Network Professional (CCNP) hoặc tương đương.Có kinh nghiệm trong việc tư vấn, đề xuất thiết kế mô hình hệ thống, vận hành triển khai hệ thống CNTT, hệ thống camera (là một lợi thế).Có hiểu biết về điện nhẹ và cách thức sắp xếp, bố trí thiết bị vật lý (là một lợi thế).Tiếng Anh: tối thiểu có thể nghiên cứu tài liệu và viết báo cáo, giới thiệu, email; đạt IELTS 6.5 hoặc tương đương (là một lợi thế).Linh hoạt cao, sẵn sàng đón nhận và thực hiện các nhiệm vụ yêu cầu công tác.', 'Tham gia vào các dự án quy mô Bộ ngành, quốc gia, được làm việc cùng nhiều chuyên gia có nhiều kinh nghiệm.Lương: theo thoả thuận theo năng lực. Thử việc 2 tháng 100% lương.Thưởng tháng lương thứ 13, thưởng KPI (6 tháng một lần), thưởng theo kết quả kinh doanh, thưởng nóng theo hiệu quả công việc, thưởng ngày lễ (tổng thu nhập một năm lên đến 14-15 tháng lương).Các chế độ phúc lợi khác dành cho nhân viên: sinh nhật, kết hôn, sinh con, ăn trưa, YEP, du lịch, happy hour, team building tháng, tea break, quà lễ/tết,...Hoạt động thể dục thể thao năng động: bóng đá, cầu lông, tennis,...Cung cấp thiết bị làm việc.Tham gia đầy đủ các chế độ bảo hiểm (BHXH, BHYT, BHTN...), khám sức khoẻ định kỳ theo quy định của Nhà nước;Chính sách hỗ trợ đào tạo nâng cao năng lực nhân viên.', 'Trụ sở chính công ty', 409, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (40, 34, '2003558', 'Business Analyst (Có Kinh Nghiệm Với SAP/ Oracle/ MES)', NULL, NULL, '3 năm', 'Nhân viên', '2026-05-06 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, '- Nghiên cứu và làm việc trên các dự án nhà máy thông minh;- Khảo sát và khám phá các giải pháp IIOT/MES/APS;- Làm việc với khách hàng để thu thập yêu cầu, xây dựng Quy trình nghiệp vụ  (BPD), Thiết kế chức năng (FD), kiểm thử chấp nhận của người dùng, triển khai và tài liệu hóa;- Thu thập thông tin, làm việc độc lập và hợp tác với các nhóm khác để làm rõ yêu cầu quy trình nghiệp vụ và đảm bảo tính khả thi của các giải pháp trước khi thông báo cho Khách hàng;- Thiết kế giao diện người dùng theo hướng đối tượng và viết tài liệu URS, BRD, FSD bằng cách sử dụng các công cụ và phần mềm thích hợp.- Phân tích Fit-Gap, yêu cầu thay đổi và các yêu cầu cải tiến khác từ khách hàng;- Hỗ trợ các thành viên khác trong nhóm;- Thực hiện các công việc khác được giao bởi quản lý', '- Kinh nghiệm từ 3 năm trở lên làm phân tích nghiệp vụ.- Bằng cử nhân ngành Khoa học Máy tính, Công nghệ thông tin, Hệ thống thông tin quản lý hoặc các chuyên ngành liên quan đến Kỹ Thuật, sản xuất.- Kỹ năng nghiên cứu tốt.- Thành thạo các phương pháp phân tích: Agile/Scrum, Waterfall, hoặc Hybrid.- Kỹ năng viết tài liệu giải pháp (Technical Proposal), BRD, FSD và tài liệu giải pháp chi tiết.- Hiểu biết về công cụ quản lý và phân tích: JIRA, MS Visio, hoặc các công cụ tương đương.- Khả năng sử dụng SQL hoặc các công cụ phân tích dữ liệu để xử lý và khai thác thông tin.- Sử dụng thành thạo các công cụ: Figma, Axure,... để xây dựng wireframe, mock-up và prototype.- Kỹ năng phân tích và khả năng thu thập thông tin từ yêu cầu khách hàng.- Khả năng làm việc đa nhiệm và làm việc độc lập dưới áp lực thời gian chặt chẽ.- Kỹ năng giao tiếp tốt, khả năng làm việc nhóm và làm việc độc lập.- Có kinh nghiệm làm việc với các hệ thống ERP (SAP/ Oracle/Odoo), MES cho nhà máy thông minh, nhà máy sản xuất là một lợi thế.- Có thể đi công tác trong nước hoặc nước ngoài khi công ty yêu cầu.- Ưu tiên ứng viên có kinh nghiệm quản lý.- Ưu tiên ứng viên có khả năng tiếng Anh (giao tiếp, đọc hiểu tài liệu) tốt.', '- Thu nhập: Thỏa thuận  + % hoa hồng dự án- Thưởng cuối năm 01 – 03 tháng lương căn cứ theo khả năng thực hiện công việc- Đầy đủ các chế độ theo luật lao động hiện hành: BHXH, BHYT, BHYT…- Nghỉ phép có lương 12 ngày + 3 ngày đi du lịch teambuilding- Chính sách phúc lợi theo quy định của Công ty đa dạng: thưởng Tết dương, ngày lễ; chăm sóc sức khỏe định kỳ hàng năm; các hoạt động tri ân, chăm lo đời sống tinh thần CBNV và thân nhân, du lịch nghỉ mát hàng năm...- Được trang bị máy tính, phụ cấp phí điện thoại, phụ cấp đi công tác, gặp gỡ khách hàng- Môi trường làm việc thân thiện, cởi mở, trẻ trung, hiện đại, văn hóa đặc sắc. Có cơ hội làm việc với các đối tác quốc tế, các dự án và khách hàng lớn.- Được đào tạo thêm chuyên môn. Cơ hội học và làm việc trong lĩnh vực công nghệ 4.0- Tài trợ chi phí thi, học đối với 1 số chứng chỉ chuyên môn- Tham gia vào các dự án đa dạng, phát triển và ứng dụng các công nghệ mới nhất.  - Cơ hội làm việc và đào tạo ngắn/ dài tại nước ngoài.  - Công ty đang mở rộng rất nhanh, rất nhiều cơ hội phát triển, thăng tiến.', 'Trụ sở chính công ty', 115, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (41, 36, '1778187', 'Kỹ Sư Giải Pháp Cloud (Cloud Solution Architect)', 35.00, 45.00, '2 năm', 'Nhân viên', '2026-04-12 19:07:55.655775', '2026-05-02 19:07:55.655775', 7, 'Tiếp nhận, phân tích yêu cầu tư vấn và khai thác nhu cầu của Khách hàng doanh nghiệp về dịch vụ CMC Cloud (Cloud tự nghiên cứu phát triển).Thuyết trình giới thiệu về sản phẩm và dịch vụ CMC Cloud cho Khách hàng doanh nghiệp (có đào tạo).Tư vấn về giải pháp hệ thống tích hợp CMC Cloud cho Khách hàng doanh nghiệp.Tư vấn về giải pháp chuyển dịch hệ thống của Khách hàng doanh nghiệp về CMC Cloud.Phối hợp cùng các bộ phận liên quan trong việc triển khai hệ thống của Khách hàng doanh nghiệp trên CMC Cloud.Đề xuất tối ưu hệ thống của Khách hàng doanh nghiệp hiện hữu.Tổng hợp các thông tin đánh giá, yêu cầu cải thiện sản phẩm dịch vụ CMC Cloud từ Khách hàng doanh nghiệp.Tổng hợp và cập nhật tài liệu tư vấn giải pháp, cùng với phân tích và đánh giá cho các case study liên quan.Tổng hợp và cập nhật báo cáo nghiên cứu thị trường, cùng với phân tích và đánh giá các tính năng của Cloud đối thủ.Trao đổi và làm việc với các đối tác công nghệ của công ty trong và ngoài nước.', 'Có tối thiểu 2 - 3 năm kinh nghiệm triển khai, vận hành các nền tảng Public Cloud (AWS, GCP, Azure…) hoặc Cloud trong nước (CMC Cloud, Viettel Cloud, FPT Smart Cloud,…).(Hoặc) có tối thiểu 2 - 3 năm kinh nghiệm làm việc với các Hệ điều hành Linux/Windows, Hệ thống ảo hóa (KVM, VMware).Ứng viên đã từng công tác với vai trò Cloud Solution Architect ở các công ty có dịch vụ tích hợp hệ thống là một điểm công lớn.Có kiến thức hoặc kinh nghiệm thực tế dựng mô hình High Availability (HA) cho ứng dụng, hệ thống.Có kiến thức nền tảng về các mảng công nghệ như: Database Administration, Docker, K8s, Security, Network Infra là một điểm cộng lớn.Có kỹ năng đọc hiểu tài liệu kỹ thuật tiếng anh, giao tiếp tiếng anh khá/tốt.Có kỹ năng thuyết trình, làm báo cáo và biên soạn tài liệu hướng dẫn tốt.', 'Range lương: 35,000,000 - 45,000,000 VND/tháng gross.Phụ cấp cơm trưa miễn phí tại văn phòng công ty.Lương cứng + phụ cấp + Lương OT + KPI tháng/quý/năm + phúc lợi Lễ tết.Ký HĐLĐ, đóng BHXH đầy đủ, nghỉ 13 ngày phép năm, các ngày Lễ, Tết theo quy định Nhà nước.Xét thưởng và xét tăng lương 2 lần/năm dựa trên hiệu suất và kết quả công việc với khả năng tăng lương đặc biệt dựa trên những thành tích nổi bật.Cơ chế lương 3 vòng thu nhập, có thưởng KPI tháng và KPI năm.Công thức lương gói thu nhập năm (Trung bình thu nhập 13 – 15 tháng lương/năm).Hỗ trợ tài chính để tham gia các khóa học và kỳ thi chứng chỉ CNTT quốc tế (lên đến 100%).Tham gia các khóa huấn luyện, đào tạo nâng cao kỹ năng, nghiệp vụ do CMC và các Đối tác Công nghệ cung cấp.Bảo hiểm chăm sóc sức khỏe tư nhân Fullerton (điều trị nội trú và ngoại trú) dành cho nhân viên và người thân nhân viên.Các chuyến đi nghỉ dưỡng hàng năm.Kiểm tra khám sức khỏe hàng năm.', 'Trụ sở chính công ty', 571, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (42, 38, '1853350', 'Chuyên Viên Tư Vấn Giải Pháp Công Nghệ', 10.00, 30.00, '1 năm', 'Nhân viên', '2026-05-16 19:07:55.655775', '2026-06-05 19:07:55.655775', 5, '★ Giới thiệu và tư vấn phần mềm hỗ trợ bán hàng, quản lý cho doanh nghiệp.★ Hướng dẫn khách hàng sử dụng và hỗ trợ kỹ thuật cơ bản.★ Làm việc trực tiếp với khách hàng để chốt hợp đồng, duy trì mối quan hệ lâu dài.★ Data khách hàng do công ty cung cấp.Được hướng dẫn từ đầu  về sản phẩm', 'Ưu tiên ứng viên có kinh nghiệm kinh doanh, tư vấn hoặc chăm sóc khách hàng.Kỹ năng giao tiếp và xử lý tình huống tốt.Yêu thích học hỏi, có tinh thần cầu tiến và đam mê công nghệ.', 'Lương cứng không phụ thuộc doanh sốThu nhập tổng có thể lên đến 30 triệu theo hiệu quả công việc.Thưởng theo nhóm, thưởng cá nhân, thưởng nóng doanh thu.Được đào tạo bài bản từ đầu, hỗ trợ phát triển chuyên môn.Chế độ bảo hiểm, nghỉ phép, thưởng lễ/tết, du lịch cùng công ty.Môi trường làm việc trẻ trung, năng động, cơ hội thăng tiến rõ ràng.', 'Trụ sở chính công ty', 211, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (55, 46, '2033122', 'Mobile Game Developer – Mobile Banking App', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-17 19:07:55.655775', '2026-05-05 19:07:55.655775', 5, 'MUST HAVE: Can communicate well in ENG, Strong in Vue.js1. General InformationPosition: Mobile Banking Game DeveloperLevel: MiddleNumber of Openings: 02Work Location: Onsite at Thanh Xuan, Hanoi2. ResponsibilitiesDevelop mini-games via WebView embedded inside Android and iOS native applicationsImplement UI designs and user flows based on UI/UX designs and functional specificationsEnsure high performance, responsiveness, and usability of mobile applicationsIntegrate mobile applications with backend services via RESTful APIsCollaborate closely with System Analysts, UI/UX Designers, Backend Developers, and QA teamsEnsure compliance with banking security standards, coding guidelines, and best practicesFix bugs, optimize performance, and improve application stabilityParticipate in code reviews, technical discussions, and sprint planningSupport UAT and production release activities when required', '3. Requirements3+ years of experience in web application or web game developmentExperience working with game publishersStrong experience with Vue.js framework and TypeScript (mandatory)Experience integrating mobile applications with RESTful APIsProficiency in version control systems (Git)Experience working in Agile / Scrum development environmentsAbility to read and understand technical documentation in English', '4. Preferred SkillsExperience in Mobile Banking, Digital Banking, or Fintech projectsKnowledge of mobile security best practices (secure storage, authentication, encryption)Experience with CI/CD pipelines for mobile applicationsFamiliarity with UI libraries and design systemsExperience with performance optimization and app store deployment is a plus', 'Trụ sở chính công ty', 635, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (60, 50, '1180702', 'Thực Tập Sinh Trợ Lý Giám Đốc', NULL, NULL, 'Không yêu cầu', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-23 19:07:55.655775', 5, 'Tiếp nhận và triển khai những thông tin chỉ đạo từ GĐ, trợ giúp GĐ trong công việcThực hiện việc soạn thảo các loại văn bản, công vănChuẩn bị tài liệu, thu thập và lưu giữ thông tin cần thiết cho GĐSắp xếp lịch làm việc, lịch họp, lịch công tác, tổ chức các cuộc họp, ghi chép và tổng hợp nội dung các cuộc họp của GĐThực hiện các công việc khác theo chỉ đạo của GĐ.Chi tiết công việc trao đổi cụ thể khi phỏng vấn', 'Không yêu cầu kinh nghiệmƯu tiên nữ, sinh viên năm 4 hoặc đang chờ bằng các ngành Ngoại thương, Kinh tế, Tài chính, Quản trị kinh doanh, Ngoại ngữ, Luật kinh tế,...Thành thạo tin học văn phòng, đặc biệt là ExcelKỹ năng: giao tiếp, thuyết trình và quản lý thời gian hiệu quảGiao tiếp tốt, nhanh nhẹnThái độ hợp tác, sẵn sàng học hỏi, đam mê tìm tòi, sáng tạo cái mớiƯu tiên ứng viên có thể giao tiếp bằng Tiếng Anh', 'Mức hỗ trợ thực tập thỏa thuận upto 5trReview lên nhân viên chính thức sau thực tậpĐược training đầy đủ kiến thức chuyên mônĐược rèn luyện các kỹ năng mềm như kỹ năng tự học, quản lý thời gian, làm việc nhóm...Làm việc trong môi trường chuyên nghiệp, năng động, trẻ trung và thân thiệnChế độ: phụ cấp, du lịch, team building,...', 'Trụ sở chính công ty', 508, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (61, 51, '1329404', 'Chuyên Viên Kinh Doanh - Sales B2B', 18.00, 40.00, '2 năm', 'Nhân viên', '2026-05-02 19:07:55.655775', '2026-05-25 19:07:55.655775', 5, 'Tìm kiếm khách hàng doanh nghiệp cho sản phẩm Cổng thanh toán và Thu-chi hộ của VNPT EPAY;Triển khai và thực hiện quá trình bán các dịch vụ & sản phẩm của công ty cho khách hàng doanh nghiệp; Khảo sát, nghiên cứu và phân tích thị trường đề xuất các cải tiến cho dịch vụ phù hợp yêu cầu khách hàng;Hỗ trợ và chăm sóc trực tiếp khách hàng;Là đầu mối của Công ty trong việc tiếp xúc với các nhóm khách hàng;        Phối hợp triển khai các chương trình Marketing, xúc tiến bán hàng;Thu thập thông tin thị trường và đối thủ cạnh tranh;Làm báo cáo kinh doanh hàng tuần, tháng, quý, năm;Đề xuất các chương trình hỗ trợ, thúc đẩy hoạt động kinh doanh.', 'Có ít nhất 2 năm kinh nghiệm làm việc ở vị trí kinh doanh Sales B2B;Có mong muốn phát triển trong lĩnh vực trung gian thanh toán;Có am hiểu về lĩnh vực trung gian thanh toán về sản phẩm Cổng thanh toán, Thu-Chi hộ là một lợi thế;Có kỹ năng giao tiếp tốt và chịu được áp lực cao trong công việc;Nhiệt huyết, ham học hỏi và mong muốn phát triển sâu trong lĩnh vực Trung gian thanh toán;Độ tuổi từ 23-30;Có khả năng làm việc độc lập và phối hợp làm việc theo nhóm, có trách nhiệm cao trong công việc;Khả năng giao tiếp và đọc hiểu Tiếng Anh tốt là một lợi thế;Thành thạo các công cụ Microsoft office (Excel, Word, Power Point).', 'Mức lương 18tr-40tr/tháng, tương xứng với năng lực và đóng góp ;Lương tháng 13 và các khoản thưởng Lễ Tết;Đánh giá tăng lương 1 lần/năm;Được hưởng các khoản phụ cấp ăn trưa, điện thoại, đi lại, công tác, làm việc online... theo yêu cầu công việc;Các khoản thưởng khác (thưởng quý, thưởng năm) sẽ căn cứ vào tình hình kinh doanh thực tế của công ty;Được hưởng chế độ bảo hiểm theo quy định nhà nước;Được mua bảo hiểm PTI và chế độ khám sức khỏe chuyên sâu định kỳ 1 lần/năm;Được tham gia các hoạt động của công ty: Happy Hour, Teambuilding, Company Trip, Year End Party, Sinh nhật Công ty với chất lượng 5 sao;Được tham gia các CLB thể thao của công ty: CLB Đá bóng, Bóng bàn, Bi lắc...;', 'Trụ sở chính công ty', 554, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (170, 151, '1781606', 'Android Developer', 12.00, 18.00, '1 năm', 'Nhân viên', '2026-04-19 19:07:55.655775', '2026-05-30 19:07:55.655775', 5, '- Phát triển các ứng dụng trên nền tảng Android, cải thiện tốc độ, hiệu quả và mở rộng ứng dụng.- Tham gia phát triển, đề xuất giải pháp kỹ thuật cho các dự án lập trình ứng dụng.- Nghiên cứu, tìm hiểu các công nghệ mới phục vụ các nhu cầu của công ty.- Bảo trì và phát triển các ứng dụng cũ của công ty.', '- Ưu tiên ứng viên có kinh nghiệm từ 1 năm trở lên.- Thành thạo Android Java hoặc Kotlin.- Nắm rõ các kiến thức về Android Components, Storage- Có kinh nghiệm xử lý đa luồng, làm việc với Coroutine- Biết sử dụng Git.- Có kinh nghiệm làm việc với Dependency Injection với các framework như Hilt- Kinh nghiệm sử dụng Jira và tuân theo quy trình Scrum/Agile.- Có kiến thức về OOP, giải thuật, Design Pattern.- Thành thạo các kiến trúc MVVM.- Có kinh nghiệm làm việc với Restful API, Retrofit.- Biết Flutter là một lợi thế- Có kinh nghiệm xử lý animation, Custom View là một lợi thế', '– Thu nhập hấp dẫn: Lương NET 12-18tr (Thỏa thuận theo năng lực) + Thưởng hiệu suất làm việc hàng tháng (Dựa theo performance). – Được hưởng đầy đủ các chế độ dành cho người lao động theo quy định pháp luật hiện hành(BHYT, BHXH, BHTN...)– Thưởng tết âm lịch, 12 ngày phép năm, thưởng Lễ/tết (theo quy định công ty), thưởng quý, thưởng cuối năm, thưởng Nhân viên xuất sắc,...).– Được hưởng các quyền lợi khác theo chính sách của công ty.– Trà, cà phê, đồ ăn vặt... miễn phí tại văn phòng– Tham gia các hoạt động, sự kiện của Wavez: team building, dã ngoại, du lịch, sinh nhật, khám sức khỏe định kỳ...– Môi trường làm việc chuyên nghiệp, thân thiện, tạo điều kiện cho ứng viên phát huy tốt nhất năng lực cá nhân.- Thời gian làm việc: 8h30 – 17h30, từ thứ 2 – thứ 6.- Địa chỉ làm việc: Tầng 2, Tòa Golden Palace, Mễ Trì, Nam Từ Liêm, Hà Nội.', 'Trụ sở chính công ty', 791, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (70, 59, '2021458', 'Chuyên Viên Thiết Kế / Designer - Tại Hà Nội', 12.00, 15.00, '3 năm', 'Nhân viên', '2026-05-02 19:07:55.655775', '2026-06-09 19:07:55.655775', 5, '1. Thiết kế Social, Website và Sự kiện
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (62, 53, '1925104', 'Trưởng Nhóm IT', 19.00, 24.00, '3 năm', 'Nhân viên', '2026-05-02 19:07:55.655775', '2026-05-17 19:07:55.655775', 7, 'Quản lý dự án tổng thểXây dựng kế hoạch triển khai chi tiết Phối hợp với nhà cung cấp giải phápThu thập và phân tích yêu cầu nghiệp vụ Tổ chức họp dự án định kỳ Giám sát cấu hình, kiểm thử, và nghiệm thu hệ thống Quản lý thay đổi và phạm vi dự ánĐào tạo và hỗ trợ người dùngTổng kết và đánh giá hiệu quả dự án', '- Đại học trở lên các ngành CNTT, hoặc tương đương.- Tối thiểu 3 năm kinh nghiệm quản lý dự án CNTT, ưu tiên các dự án DMS/TMS/WMS/ERP.- Đã từng trực tiếp triển khai hoặc tham gia các dự án trong lĩnh vực bán lẻ, hàng tiêu dùng nhanh (FMCG) hoặc phân phối.- Hiểu biết quy trình vận hành phân phối, kho vận, logistics, nắm vững phương pháp quản lý dự án.- Am hiểu đặc thù vận hành và luồng dữ liệu trong hệ thống DMS/TMS/WMS và mô hình phân phối nhiều tầng (Distributor – Retailer).- Có chứng chỉ PMP.- Kỹ năng giao tiếp, lập kế hoạch, thương lượng và giải quyết vấn đề.- Thành thạo MS Project, hoặc các công cụ quản lý dự án tương đương.- Có thể nói và viết được tiếng anh trình độ cấp trung.', 'Mức lương thỏa thuậnTham gia BHXH full lươngThưởng tháng 13, 14 (tùy theo tình hình kinh doanh của công ty);Teambuilding hằng năm;Lộ trình thăng tiến rõ ràng;Môi trường làm việc thân thiện;Phụ cấp thâm niên từ 5 năm trở lên;Review lương hàng năm', 'Trụ sở chính công ty', 557, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (63, 159, '1562432', 'Nhân Viên Thiết Kế', 12.00, 18.00, '1 năm', 'Nhân viên', '2026-05-05 19:07:55.655775', '2026-06-09 19:07:55.655775', 5, 'Tiếp nhận các nhu cầu thiết kế, in ấn từ Trưởng phòng và BGĐ. Đưa ra ý tưởng thiết kế phù hợp với mục đích công việc và đảm bảo tiêu chuẩn mỹ thuật. Thiết kế các ấn phẩm liên quan đến các ngành hàng, sản phẩm công ty kinh doanh: standee, backdrop, brochure, catalogue, poster... Hỗ trợ công tác PR và Event, góp phần quảng bá hình ảnh thương hiệu Công ty Các nhiệm vụ khác liên quan. Các công việc khác theo sự phân công của quản lý trực tiếp', 'Nam/ Nữ tốt nghiệp đại học, từ 22 - 30 tuổi. Sử dụng thành thạo các phần mềm đồ họa: Adobe Illustrator, Adobe Photoshop... Có kinh nghiệm trong thiết kế poster quảng cáo, banner tờ rơi, brochure. Có khả năng tư duy sáng tạo, phân tích nội dung thiết kế. Kinh nghiệm 1 năm trở lên. Có nền tảng thẩm mỹ tốt. Tốt nghiệp các trường đào tạo về thiết kế đồ họa hoặc tương đương. Có tính cầu toàn, tỉ mỉ, ham học hỏi cái mới.', 'Lương 12- 18tr + phụ cấp (tiền ăn, điện thoại, xăng xe,...)Thưởng tháng lương thứ 13Thưởng các ngày Lễ lớn trong nămĐánh giá tăng lương 1 lần/nămĐược đi du lịch hằng năm với địa điểm hấp dẫnĐược tham gia các buổi liên hoan, sinh nhật hàng tháng, tiệc noel, tất niên,...Được tham gia BHXH, BHYT, BHTN theo luật hiện hành.Môi trường làm việc: lành mạnh, trẻ trung, sáng tạoNhân viên được mua sản phẩm của Công ty có thương hiệu nổi tiếng trên thị trường với giá ưu đãi', 'Trụ sở chính công ty', 789, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (67, 56, '2013917', 'Embedded Engineer', NULL, 30.00, '2 năm', 'Nhân viên', '2026-04-30 19:07:55.655775', '2026-05-19 19:07:55.655775', 5, '1/ Job SummarySteam For Vietnam - We are seeking an Electronics Engineer passionate about robotics and education to design, prototype, and optimize mechanical–electronic systems for our line of educational robots. You will work at the intersection of mechanical, electrical, and control systems, developing reliable, safe, and cost-effective robotic solutions for students and schools.2/ Key ResponsibilitiesDevelop, optimize, and maintain embedded software and firmware for humanoid robots.Develop schematics and layouts, optimize PCBA for motion control, power management, sensors, and communication modulesIntegrate and interface with sensors, actuators, and communication protocols (SPI, I2C, UART, CAN, Ethernet, etc.).Optimize power management and energy efficiency of embedded systems.Collaborate with mechanical, and software engineers to ensure seamless integration.Debug and troubleshoot low-level hardware and software issues using tools such as oscilloscopes, logic analyzers, and debuggers.', 'Bachelor’s or Master’s degree in Embedded Systems, Computer Engineering, or related field.At least 2 years of experience in embedded systems development, preferably in robotics.Proficiency in C, C++ for embedded systems.Hands-on experience with low-level driver development.Understanding of communication buses and protocols such as Ethernet, EtherCAT, Serial, SPI, and I2C.Strong understanding of embedded software architecture and design patterns.Strong problem-solving, analytical mindset, detail-oriented, ability to debug complex hardware and system-level issues.Effective communication and collaboration: ability to work in cross-functional teams (mechanical, software, product, manufacturing).Passion for robotics, education, and building products that matter in the STEAM space.', 'Hybrid working model: Enjoy 2 remote working days per week while fostering a collaborative environment to achieve outstanding results.Build your network in both nonprofit and tech communitiesReceive mentorship and grow in a supportive, mission-aligned teamBest working environment: Coffee shop-like open office space, kitchen full of snacks and drinks, West Lake view bar, PlayStation, pool table, etc.Gadgets for work: MacBook, external displays. Everything you need for your job is fully provided.Training and personal development: Tuition and textbook reimbursement for approved work-related courses; free video training programs from Udacity, Udemy, and The Great Courses Plus; company library with the newest technology and business books.', 'Trụ sở chính công ty', 616, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (68, 57, '2026394', 'UI/UX Designer', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-18 19:07:55.655775', '2026-05-26 19:07:55.655775', 5, '1. Thiết kế UI/UX cho website & sản phẩm an toàn thông tinKhảo sát yêu cầu, phân tích user flow, use case và hành vi người dùng để thiết kế trải nghiệm hiệu quả.Thiết kế wireframe à prototype à UI high-fidelity cho:Website giới thiệu sản phẩm, landing page, portal.Sản phẩm an toàn thông tin (ví dụ: TIP, SOAR, SIEM, ASM/VM, SOC dashboard...).Đảm bảo giao diện thân thiện, rõ ràng, tối ưu thao tác, phù hợp với người dùng kỹ thuật (SOC engineer, analyst, IT admin...).2. Xây dựng template & design system dùng chungThiết kế và duy trì design system cho hệ sinh thái sản phẩm:UI components (button, table, modal, form, toast, tag, badge...)Layout grid, typography, spacing, color token, icon setTemplate màn hình dùng chung (list/detail/create/edit, dashboard, settings, audit log...)Chuẩn hóa style guide + quy chuẩn thiết kế, đảm bảo khả năng tái sử dụng và mở rộng đa sản phẩm.Thiết kế dark mode / light mode (ưu tiên dark mode cho hệ thống SOC).3. Tập trung vào UX cho sản phẩm an toàn thông tinThiết kế UX tối ưu cho dữ liệu lớn và thao tác nghiệp vụ nặng:Bảng dữ liệu, filter nâng cao, search, sortingTimeline sự kiện, log viewer, indicator severity, triage viewDashboard KPI và trạng thái cảnh báo/caseƯu tiên tính rõ ràng - giảm nhầm lẫn - giảm sai thao tác, đặc biệt khi xử lý cảnh báo và sự cố.=4. Phối hợp phát triển sản phẩmLàm việc chặt chẽ với PM/BA/Tech Lead/Developer để:Chuyển đổi yêu cầu thành thiết kế khả thiHandoff spec rõ ràng (font, spacing, component states, responsive...)Review UI implementation, đảm bảo đúng chuẩn thiết kế.Chủ động đề xuất cải tiến UX dựa trên phản hồi người dùng và dữ liệu sử dụng.', 'Tối thiểu 3 năm kinh nghiệm UI/UX cho web app / SaaS / dashboard.Thành thạo Figma (Auto layout, Component, Variants, Design tokens).Hiểu rõ quy trình UX: user journey, wireframe, prototype, usability.Có khả năng thiết kế hệ thống phức tạp: table, filter, dashboard.Có tư duy hệ thống và khả năng xây dựng template + design system dùng chung.Biết cách viết spec/handoff rõ ràng cho developer.Ưu tiên: Có kinh nghiệm UI/UX cho cybersecurity / enterprise software (SOC tools, log monitoring, network/security products).Biết về RBAC, permission UI, audit log, compliance UI.Có hiểu biết cơ bản về HTML/CSS hoặc làm việc gần dev frontend.Có kinh nghiệm thiết kế responsive và tối ưu accessibility.Biết sử dụng các công cụ bổ trợ: Figma, Miro, Notion, Jira.', 'Thử việc hưởng 100% lương. Thu nhập hấp dẫn thỏa thuận theo năng lực. Review lương 2 lần/năm. Lộ trình đánh giá nhân viên rõ ràng, minh bạch, dựa trên số liệu, báo cáo chi tiết. Thưởng KPI Quý. Thưởng tất cả các ngày Lễ, Tết; thưởng giới thiệu ứng viên nội bộ. Thưởng thâm niên làm việc tính từ năm đầu tiên, Thưởng ESOP (Employee Stock Ownership Plan) đối với nhân viên và quản lý xuất sắc vào cuối năm. Được tham gia rất nhiều các khoá học đào tạo định kỳ về kỹ năng chuyên môn và kỹ năng mềm.  Được Công ty đầu tư chi phí cho việc học và thi các chứng chỉ quốc tế cần thiết cho công việc.  12 ngày phép năm + 1 ngày nghỉ vào ngày sinh nhật. Mỗi năm thâm niên được tăng thêm 1 ngày nghỉ phép. Được hưởng đầy đủ các chế độ bảo hiểm và ngày nghỉ, ngày lễ theo quy định của công ty và pháp luật hiện hành. Được hưởng các chế độ phúc lợi và các hoạt động văn hóa tập thể: Team Building, Gala cuối năm, sinh nhật, các ngày lễ ...; Văn hóa công ty đề cao sự công bằng, lắng nghe & chia sẻ, khách hàng là trọng tâm. Môi trường làm việc trẻ trung, chuyên nghiệp, văn minh.  Cơ hội làm việc với những Tập đoàn lớn/doanh nghiệp lớn/Bank', 'Trụ sở chính công ty', 810, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (69, 58, '2023505', 'Nhân Viên Kinh Doanh Giải Pháp/Phần Mềm Mảng Giáo Dục - Từ 27 Tuổi - Thu Nhập Đến 35 Triệu - Kinh Nghiệm Từ 2 Năm - Hà Nội', 15.00, 35.00, '2 năm', 'Nhân viên', '2026-05-11 19:07:55.655775', '2026-06-21 19:07:55.655775', 5, 'Xây dựng quan hệ và mở rộng các mối quan hệ với khách hàng, thực hiện đàm phán, thương lượng, ký kết hợp đồng với khách hàng.Chịu trách nhiệm KPIs doanh số theo tháng/quý/năm.Phân tích tình hình thị trường, đối thủ cạnh tranh, đánh giá các nhu cầu, tâm lý các khách hàng mục tiêu, tiềm năng. Xây dựng, đề xuất các chương trình marketing, giải pháp kinh doanh nhằm đạt được mục tiêu.Hỗ trợ bộ phận CSKH trong quá trình triển khai, hỗ trợ và tiếp nhận phản hồi của KH.Phối hợp với Lãnh đạo công ty phát triển các kế hoạch hay dự án kinh doanh mới.Thực hiện công việc liên quan khác theo yêu cầu của cấp trên', 'Từ 27 tuổi trở lênƯu tiên ứng viên Nam Tốt nghiệp Đại học các chuyên ngànhCó tối thiểu 2 năm kinh nghiệm. Ưu tiên ứng viên có kinh nghiệm trong lĩnh vực Giáo dục, Công nghệ thông tin.Kỹ năng chủ động quan sát, học hỏi, nghiên cứu, quản lý thời gian, có trách nhiệm cao với công việc được giao, chịu được áp lực công việc tốt.Kỹ năng giao tiếp, đàm phán và xử lý tình huống tốt.Ham học hỏi, mong muốn phát triển bản thân', 'Thu nhập trung bình: 15.000.000 VND - 35.000.000 VND  (tùy theo năng lực ứng viên)Thu nhập = Lương cơ bản + Thưởng hiệu quả công việc Phụ cấp ăn trưa và liên lạc.Chế độ phúc lợi sinh nhật cá nhân, các ngày nghỉ lễ.... Liên hoan hàng tháng, sẵn đồ ăn vặt trên văn phòng.Tham gia đầy đủ BHXH, BHYT, BHTN theo quy định của pháp luật ngay khi đủ điều kiệnĐịnh kỳ được đánh giá tăng lương theo năng lựcĐược đào tạo chuyên môn, nghiệp vụ và các kỹ năng bổ trợ cho công việc .v.v.Có cơ hội tham gia quản lý trực tiếp các dự án khác của công ty.Có cơ hội làm việc, học hỏi với nhiều chuyên gia trong lĩnh vực giáo dụcMôi trường làm việc thân thiện, nhiều thử thách, cơ hội phát triểnChế độ nghỉ phép, nghỉ lễ, tết theo quy địnhHưởng đầy đủ các chế độ phúc lợi nội bộ: sinh nhật, ốm đau, hiếu hỉ và các chính sách chăm sóc đời sống nhân sự khácĐược tham gia các hoạt động team building, du lịch hàng năm và các hoạt động hấp dẫn khác do công ty tổ chức', 'Trụ sở chính công ty', 483, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (71, 60, '773445', 'Giáo Viên Môn Công Nghệ Thông Tin (ICT/IT)', 15.00, 30.00, '2 năm', 'Nhân viên', '2026-04-28 19:07:55.655775', '2026-05-13 19:07:55.655775', 9, '- Xây dựng phân phối chương trình môn Information Technology  của các lớp đầu năm học (bao gồm long term, medium term/syllabus và short term plan của môn học) với đối tượng học sinh bậc THPT (Lớp 10-12);- Trực tiếp giảng dạy (dạy bằng tiếng Anh) theo phân phối chương trình và thời khóa biểu được phân công;- Xây dựng và lưu trữ theo quy định giáo án môn Information Technology (bao gồm giáo án, slide học tập, work sheet...), bảo đảm bộ giáo án đảm đúng phân phối chương trình, đúng năng lực học sinh, có điều chỉnh phù hợp yêu cầu học tập thực tế từng lớp học;- Soạn Unit Test môn Information Technology;- Soạn đề kiểm tra môn Information Technology trong năm học bao gồm 04 đề (bao gồm đề dự phòng): giữa kỳ và cuối kỳ học kỳ 1 và học kỳ 2;- Bồi dưỡng, hỗ trợ và luyện tập phù hợp cho học sinh trong quá trình học tập và trước các kì thi;- Tutor cho học sinh 1-2 buổi/tuần (mỗi buổi khoảng 30’ – 1h00);- Theo dõi học sinh học và điều chỉnh chương trình học/giáo án phù hợp với năng lực học sinh từng lớp;- Họp chuyên môn, bồi dưỡng giáo viên theo định hướng chương trình; - Tham gia xây dựng hoàn thiện chương trình quốc tế đặc thù ;', '- Bẳng Thạc sĩ, Tiến sĩ (tốt nghiệp nước ngoài) phù hợp với chuyên ngành giảng dạy; - Có kinh nghiệm học tập, làm việc ở nước ngoài là một lợi thế;- Năng lực ngôn ngữ tiếng Anh phù hợp giảng dạy, tương đương IELTS 6.5 trở lên;- Kinh nghiệm giảng dạy là lợi thế;- Tận tâm với học sinh và nghề dạy học.- Có kinh nghiệm đứng lớp là một lợi thế.', '-Lương cạnh tranh, theo năng lực thực tế và tiết dạy.- Hỗ trợ cung cấp chương trình và xây dựng giáo án giảng dạy.- Hỗ trợ chi phí đi lại đến trường học;- Thuế thu nhập cá nhân và các chế độ (nếu có) theo quy định.- Cung cấp sách tài liệu và sách (student books, teacher books, Hub account...) theochương trình học;- Học miễn phí đào tạo và được cấp chứng chỉ về môn học.- Bảo hiểm y tế, bảo hiểm thất nghiệp, bảo hiểm xã hội... (không khấu trừ vào lương) và bảo hiểm y tế tư nhân (quyền lợi lên tới 250 triệu/năm), khám sức khoẻ định kỳ, thưởng học kì, thưởng Tết và hỗ trợ sự kiện, lương hè 80%, vé xe bus tháng.- Làm việc môi trường chuyên nghiệp, hiện đại- Cơ hội giao tiếp với giáo viên nước ngoài- Xác nhận kinh nghiệm làm việc hoặc lí lịch thực tập.- Ăn trưa.', 'Trụ sở chính công ty', 214, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (73, 64, '1705030', 'UA Marketing - Mobile App', 12.00, 30.00, 'Dưới 1 năm', 'Nhân viên', '2026-04-27 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, 'Lập kế hoạch và triển khai các chiến dịch UA trên các nền tảng như Google Ads (UAC), Facebook Ads, TikTok Ads, v.v. Phân tích dữ liệu chiến dịch, theo dõi các chỉ số như CPI, ROAS, LTV, Retention, v.v. để tối ưu hiệu suất. Làm việc chặt chẽ với team Creative để lên brief và đánh giá hiệu quả các mẫu quảng cáo (video, banner, native...). Nghiên cứu thị trường, hành vi người dùng và đối thủ để liên tục cải thiện chiến lược UA. Báo cáo định kỳ kiểm soát công việc và chiến lược marketing hiệu quả Xây dựng và duy trì mối quan hệ với các đối tác chiến lược, khách hàng quan trọng và các bên liên quan khác. Đảm bảo ngân sách được sử dụng hiệu quả và đúng mục tiêu kinh doanh của từng dự án. Cơ hội làm việc với các đối tác lớn Google, Facebook, Apple, Tiktok.', 'Tối thiểu 6 tháng đến 1 năm kinh nghiệm làm UA Marketing Mobile App/Game hoặc các lĩnh vực liên quan. Hiểu biết về các kênh quảng cáo phổ biến và nền tảng phân tích dữ liệu như Firebase, Appsflyer, Adjust,... Có khả năng phân tích dữ liệu tốt, sử dụng thành thạo Excel/Google Sheets, BI tools là một lợi thế. Khả năng quản lý chiến dịch quảng cáo hiệu quả, tối ưu hóa ROI/ROAS. Có tinh thần học hỏi và cập nhật xu hướng UA liên tục. Có kinh nghiệm với chiến dịch soft-launch và scale-up UA cho các app global. Làm việc độc lập và phối hợp nhóm hiệu quả, kỹ năng giao tiếp tốt, chịu áp lực doanh số công việc tốt.', 'Lương up to 12 – 30 triệuMôi trường làm việc năng động, cơ hội phát triển nghề nghiệp.Nghỉ phép năm theo Quy định của Pháp luật hiện hành.Nghỉ lễ, tết theo Luật lao động quy định.Đóng bảo hiểm theo quy định của Nhà nước.', 'Trụ sở chính công ty', 569, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (75, 66, '2030334', 'QA/ TESTER Biết Tiếng Nhật (Tương Đương N3 Trở Lên)', NULL, NULL, '3 năm', 'Nhân viên', '2026-05-18 19:07:55.655775', '2026-06-10 19:07:55.655775', 5, 'airCloset là công ty cung cấp dịch vụ cho thuê thời trang hàng tháng, ra mắt vào tháng 2 năm 2015.Tính đến tháng 07/2023, airCloset đã phát triển lên hơn 1 triệu thành viên.Bên cạnh dịch vụ cốt lõi airCloset chúng tôi còn vận hành:+ airCloset Mall- một trung tâm cho thuê hàng tháng được nhà sản xuất phê duyệt, nơi khách hàng có thể dùng thử sản phẩm tại nhà.+ airCloset Spot Rental- dịch vụ cho thuê trang phục cho các dịp như đám cưới và tiệc tùng.Trong giai đoạn sắp tới, airCloset hướng tới mở rộng sang thị trường châu Á, với mục tiêu tăng trưởng nhanh và bền vững.Nhiệm vụ công việc:● Phối hợp với Dev và BrSE để phân tích các yêu cầu và thiết kế của dự án.● Viết các test cases và test scenarios.● Thực hiện test case (Web, App Native, API,Batch).● Review các test case● Báo cáo và xác minh các bug đã được tìm thấy.● Báo cáo kết quả test cho Test Leader.Môi trường phát triển:● Server-side sử dụng dụng NodeJS, Frontend sử dụng React, React Native, Flutter● Quản lý source-code: Github● Quản lý dự án: Backlog● CI: CircleCi● Infrastructure (cơ sở hạ tầng): AWS・GCP● Trao đổi nội bộ: Slack', '● Có kinh nghiệm từ 3 - 7 năm trở lên ở vị trí Tester/QA.● Trình độ tiếng Nhật tương đương N3+, có thể đọc và hiểu các tài liệu bằng tiếng Nhật.● Có kinh nghiệm kiểm thử Web, Native apps, API, Batch.● Ưu tiên có kinh nghiệm trong các dự án Thương mại điện tử.● Có kiến thức về các giai đoạn kiểm thử phần mềm (Integration test, System test, v.v.) và các kỹ thuật kiểm thử.● Thành thạo các truy vấn SQL và có kinh nghiệm làm việc với cơ sở dữ liệu.● Có kinh nghiệm sử dụng SQL (MySQL, SQL Server, ...).● Có khả năng ước tính và tự quản lý khối lượng công việc.● Tư duy logic, khả năng thích ứng và tư duy phản biện.● Nhiệt tình, ham học hỏi và có tinh thần trách nhiệm cao.Ưu tiên ứng viên:● Có khả năng viết các script kiểm thử tự động (Selenium, Playwright, ...).● Có kinh nghiệm sử dụng 1 trong các tool/framework: Karate, Selenium, Appium, Serenity BDD,...● Ưu tiên có kinh nghiệm lập trình: Java hoặc JavaScript/TypeScript.', '-Thu nhập:Mức lương cạnh tranh, tương xứng với năng lực và kinh nghiệmThưởng tháng lương thứ 13Review và tăng lương 2 lần/nămThử việc hưởng 100% lương.- Chế độ nghỉ phép:12 ngày phép năm và thêm 2 ngày sinh nhật công ty và sinh nhật bản thânNghỉ lễ, Tết theo quy định của nhà nướcLao động nữ được nghỉ sinh lý 2.5h/tháng-Bảo hiểm & Sức khỏe:Bảo hiểm sức khỏe cao cấp cho toàn bộ nhân viênKhám sức khỏe định kỳ 1 năm/lầnBHXH, BHYT, BHTN mức cao theo quy định, đảm bảo quyền lợi người lao động-Môi trường làm việc:Làm việc từ Thứ 2 – Thứ 6, full-timeKhông gian làm việc mở, hiện đại, tiện nghiĐược cấp Macbook phục vụ công việc-Hoạt động & Phúc lợi khác:Trợ cấp hoạt động teambuilding hàng thángCamping 6 tháng/lầnDu lịch công ty 1 năm/lầnTham gia CLB thể thaoCơ hội được đào tạo và mentoring từ senior membersLộ trình phát triển nghề nghiệp rõ ràng', 'Trụ sở chính công ty', 437, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (81, 71, '1977406', 'Nhân Viên Vẽ Minh Họa ( Artist 2D)', 10.00, 15.00, '2 năm', 'Nhân viên', '2026-05-18 19:07:55.655775', '2026-06-20 19:07:55.655775', 5, 'Minh họa tranh theo yêu cầu của khách hàng và các sản phẩm của công ty ( sản phẩm bao bì quà tặng cao cấp)Tham gia xây dựng, đề xuất các ý tưởng thiết kếHỗ trợ team thiết kế các ấn phẩm cho khách hàng như bao bì, logo, tờ rơi, nhận diện thương hiệu, các sản phẩm in ấn.....Brainstorm với đội để phát triển các ý tưởng sáng tạoThực hiện các công việc khác theo sự phân công của quản lý', 'Kinh nghiệm: 2 năm ở vị trí tương đươngCó khả năng vẽ tay, vẽ minh họaHiểu biết về thiết kế, biết sử dụng các phần mềm đồ họa cơ bản (Photoshop, Adobe Illustrator,...)Sử dụng thành thạo wacomCó tư duy thẩm mĩ, khả năng sáng tạo, luôn cập nhật các xu hướng thiết kế mớiCẩn thận, tỉ mỉ, có khả năng cân chỉnh màu sắcCó ý chí cầu tiến, ham học hỏi, tinh thần trách nhiệm và trung thực.', 'Mức lương: 10-15M + thưởngLương tháng 13, thưởng lễ tết, sinh nhật, mùa vụ...Đóng BHXH, 12 ngày phép nămĐược đào tạo kiến thức và kỹ năng chuyên ngành Design.Làm việc trong môi trường năng động và sáng tạo.Cung cấp các thiết bị phục vụ công việc: imac, wacom...Tham gia các khóa họa chuyên môn để nâng cao tay nghềDu lịch hằng năm cùng công tyThời gian làm việc: 8h00-17h00 từ thứ Hai đến thứ Sáu, thứ Bảy từ 8h00 - 12h00. Nghỉ chiều thứ Bảy& Chủ NhậtĐịa điểm làm việc: số 7, ngõ 37 Tây Kết, Phường Hồng Hà, TP Hà Nội', 'Trụ sở chính công ty', 996, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (82, 71, '1977336', 'Graphic Designer', 10.00, 15.00, '2 năm', 'Nhân viên', '2026-05-15 19:07:55.655775', '2026-06-08 19:07:55.655775', 5, 'Chịu trách nhiệm thiết kế, và phát triển về mặt mỹ thuật các sản phẩm thiết kếĐảm nhận việc thiết kế đồ họa các ấn phẩm theo yêu cầu của khách hàng như: bao bì, tem nhãn, logo, hệ thống nhận diện thương hiệu...Support team account làm việc với client & supplier..Chỉnh sửa, hoàn thiện sản phẩm theo yêu cầu của khách hàng.Thực hiện các công việc khác theo sự phân công của quản lý.', 'Tốt nghiệp Cao đẳng/Đại học chuyên ngành Thiết kế đồ họa, Mỹ thuật ứng dụng, Mỹ thuật công nghiệp hoặc các chuyên ngành liên quan;Kinh nghiệm: 2 năm ở vị trí tương đương tại agency hoặc clientƯu tiên ứng viên có khả năng vẽ tay, vẽ minh họaSử dụng thành thạo  trong các công cụ thiết kế cơ bản: Photoshop, Illustrator, indesign…Vận dụng tốt kỹ năng sắp xếp bố cục, sử dụng màu sắc.Phong cách thiết kế hiện đại, tư duy thẩm mỹ tốt.Tư duy sáng tạo và logic trong mỗi thiết kế/xử lý, tiếp thu và học hỏi tốt.Có trách nhiệm cao, cầu tiến, ham học hỏi, hòa đồng.Trung thực, tự giác, nghiêm túc trong công việc.', 'Thu nhập: 10.000.000 - 15.000.000 VNĐ/tháng + thưởngHỗ trợ ăn trưa 650.000/tháng12 ngày phép nămLương thưởng tháng 13Được tham gia BHXH, BHYT, BHTNCó cơ hội được giao lưu học hỏi, phát triển khả năng bản thân và kỹ năng làm việc theo nhóm.Cung cấp trang thiết bị đầy đủ để phục vụ công việc.Được tham gia các khóa học đào tạo để nâng cao nghiệp vụTham gia các hoạt động của công ty : sinh nhật, team building…Làm việc từ T2 đến T6 (8h-17h), thứ Bảy (8h-12h). Nghỉ chiều thứ Bảy và Chủ NhậtĐịa điểm làm việc: số 7, ngõ 37 Tây Kết, phường Hồng Hà, thành phố Hà Nội.', 'Trụ sở chính công ty', 246, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (83, 72, '2025723', 'Nhân Viên Thiết Kế Đồ Họa', NULL, NULL, '1 năm', 'Nhân viên', '2026-04-30 19:07:55.655775', '2026-06-01 19:07:55.655775', 7, 'Thiết kế đồ họa như Poster, Banner,…. phục vụ hoạt động của công tyQuay phim, chụp hình, edit video cơ bản cho các sự kiện nội bộ/tuyển dụng.Quản lý kênh Tiktok của công tyHỗ trợ đồng nghiệp tổ chức các hoạt động cho CNV công tyCác công việc liên quan khác do cấp trên yêu cầu.', 'Tốt nghiệp Cao đẳng ngành Thiết kế đồ họaThành thạo các phần mềm chuyên môn phục vụ công việc (photoshop, illustrator,..)Kinh nghiệm 1 năm vị trí liên quanNăng động, nhiệt huyết, có kiến thức về nhiếp ảnh và quay phim cơ bản là lợi thế', '- Được hưởng tất cả những quyền lợi theo luật lao động Việt Nam hiện hành- Được tham gia và hưởng chế độ bảo hiểm theo quy định Nhà nước (BHXH, BHYT, BHTN)- Phụ cấp cơm trưa, phụ cấp sinh hoạt hàng tháng (nhà trọ, xăng xe...)- Phụ cấp ngoại ngữ lên đến 3 triệu.- Tổ chức văn nghệ vui chơi giải trí. Liên hoan cuối năm, rút thăm trúng thưởng- Khám sức khỏe định kì- Thưởng lễ tết, lương tháng 13- Môi trường làm việc năng động, chuyên nghiệp, có cơ hội phát triển năng lực ngoại ngữ (Tiếng Anh- Tiếng Trung)- Cơ hội đào tạo, thăng tiến thông qua các khóa đào tạo nội bộ và các khóa đào tạo liên kết- Lương thỏa thuận khi phỏng vấn', 'Trụ sở chính công ty', 743, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (92, 77, '2029546', 'Tester (Senior)', NULL, NULL, 'Trên 5 năm', 'Nhân viên', '2026-05-07 19:07:55.655775', '2026-05-26 19:07:55.655775', 7, 'Create test scenarios, test case for testing the new system and new feature of existing system.Perform testing and document the actual result as needed.Report defects to appropriate team members, monitor defect resolution efforts and track successes.Work with relevant team to coordinate the development, updating, maintenance of test cases.Analyze defects to determine root cause.Ensure final documents are usable and of high quality.Collaborate with systems and development staff to collect and interpret technical information.Execute functional test, and integration test.Support end user in UAT testing.Coordinate with Project Manager, test leader, BA during planning and reporting test activities.Other testing and documentation tasks assigned.', 'English proficiency.Bachelor’s degree in computer science.Strong attention to detail and multi-tasking skillsAt least 7 years as Senior Test or above in a large foreign financial institution.Experience with accessibility standards.Experience with load testing, backend testing and performance testing.Excellent knowledge of software testing methodology, solid knowledge and experience applying Context Driven Testing is a big plus.Excellent sense of quality assessment and quality improvementStrong organizational, analytical, and problem-solving skills.Self-managed and self-motivated skills.', 'Annual salary review (once per year).Dynamic, technology-driven working environment with opportunities for self-development and career advancement.Full insurance coverage, annual leave, and 13th-month salary in accordance with state regulations.Participation in Social, Health, and Unemployment Insurance (BHYT, BHXH, BHTN).Annual health check-up.Participation in sports activities, workshops, birthday celebrations, team building, and company trips on a quarterly and yearly basis.', 'Trụ sở chính công ty', 947, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (94, 81, '1607034', 'Thực Tập Sinh Thiết Kế Đồ Hoạ (Designer)', 2.00, 5.00, 'Không yêu cầu', 'Nhân viên', '2026-05-18 19:07:55.655775', '2026-06-08 19:07:55.655775', 5, 'JOB DESCRIPTIONS:Tham gia brainstorm đề xuất ý tưởng visual phù hợp với các kênh truyền thông (Facebook, TikTok, Google, sàn TMĐT...) và các marketing campaignsTham gia thiết kế hình ảnh trên các kênh truyền thông và các marketing campaignsHỗ trợ quay video, chụp ảnh sản phẩm và các khâu sản xuất nội dung khácHỗ trợ quản lý hệ thống BI, thư viện design và tài nguyên, ấn phẩm mediaHỗ trợ các công việc khác theo yêu cầu, phát sinh', 'REQUIREMENTS:Start-up ADN và Máu lửa Chỉnh chu, cầu toàn và tập trung chi tiếtCó khả năng chịu áp lực và làm việc tốc độ caoCó thực tế design Web, UX-UI, Ecom là một lợi thếAm hiểu về các xu hướng Social content là một lợi thếƯu tiên thành thạo các tools chỉnh sửa, thiết kế ảnh, video như Capcut, Photoshop, AI...Ưu tiên sinh viên ngành Thiết kế đồ họa, mỹ thuật hoặc có định hướng về lĩnh vực thiết kếƯu tiên có laptop để chủ động công việc. Tiếng Anh tốt là một lợi thếỨng viên gửi kèm Portfolio hoặc Behance, các ấn phẩm thiết kế đã thực hiện!', 'BENEFITS & FUN:Phụ cấp thực tậpChi phí văn phòng; Phụ cấp điện thoạiCác tiện ích văn phòng khác, trà và cafe free...Cơ hội offer job chính thức sau thời gian thực tập rõ ràngTham gia Team Building, Party, Nghỉ mát và Events của Công tyWHY KOLABUY?Được đào tạo và phát triển thần tốc trong môi trường StartupMôi trường trẻ, năng động và hiện đại, open phong cách Quốc tếĐược “Chiến” và “Cháy” trong một startup khát khao và giàu tham vọng', 'Trụ sở chính công ty', 206, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (97, 85, '2028194', 'IT UI/UX Designer Biết Tiếng Trung ( Remote )', 20.00, NULL, '2 năm', 'Nhân viên', '2026-04-22 19:07:55.655775', '2026-05-30 19:07:55.655775', 5, 'Tiếp nhận yêu cầu và trao đổi thông tin từ khách hàng (Trung Quốc), dịch và truyền đạt, mô tả lại cho DeveloperTham gia design giao diện sản phẩm, bao gồm cả Web và Mobile app (Figma)Theo dõi tiến độ dự án và chất lượng sản phẩm trong suốt quá trình phát triển', 'Có tối thiểu 2 năm kinh nghiệmTrình độ tiếng Trung: Thành thạo giao tiếpThành thạo tin học văn phòngNăng động, tích cực trong công việc, kỹ năng giao tiếp, làm việc nhóm tốtBiết tiếng Anh là một lợi thế, biết sử dụng các phần mềm thiết kế là một lợi thếCó tư duy thẩm mỹ tốt, sáng tạoKỹ năng giao tiếp và làm việc nhóm tốt, năng động trong công việcSử dụng tốt các công cụ thiết kế như Figma, Adobe XD, Photoshop, Illustrator hoặc tương đươngCó kinh nghiệm làm việc liên quan đến IT là một lợi thế', 'Thu nhập: Thỏa thuận theo năng lực, lương cứng từ 20M NET + thưởng theo hiệu quả và sự đóng gópThời gian làm việc: Remote từ thứ 2 đến thứ 6, tham gia dự án với khách hàng nước ngoàiChế độ xét duyệt tăng lương định kỳ hàng nămĐược hưởng quyền lợi BHXH, BHYT, BHTN đầy đủ theo quy định của nhà nước.Được đánh giá xét kết quả công việc, đề bạt lên các vị trí phù hợp với năng lực bản thânCơ hội tham gia các dự án quốc tế với các khách hàng Nhật, US/EULàm việc tại môi trường chuyên nghiệp, năng động, trẻ trung, thân thiện và trải nghiệm các hoạt động văn hóa doanh nghiệp đặc sắcCơ hội tiếp cận với những doanh nghiệp, dự án lớn, những xu hướng công nghệ/nền tảng mới nhất, thỏa sức sáng tạo phát triển bản thânCác chế độ phúc lợi theo chính sách của Công ty: Nghỉ phép năm, thưởng các ngày lễ, tết, thăm hỏi, tặng quà, hỗ trợ ...', 'Trụ sở chính công ty', 318, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (91, 163, '1650565', 'Mobile App Developer (React Native)', 15.00, 25.00, '1 năm', 'Nhân viên', '2026-04-12 19:07:55.655775', '2026-05-02 19:07:55.655775', 7, 'Tham gia xây dựng và tối ưu hóa các ứng dụng mobile hiện đại, tập trung vào trải nghiệm người dùng mượt mà và tích hợp hệ thống. Chúng tôi đang tìm kiếm ứng viên đam mê công nghệ, sáng tạo và sẵn sàng đóng góp vào các dự án lớn. Được tiếp cận nhiều quy trình nghiệp vụ phần mềm: đa dạng, linh hoạt.Lập trình Mobile app iOS/Android cho phần mềm của công tyPhần mềm quản lý bán hàng FnB, bán lẻ (Retail)Phần mềm CRM, quản lý dự án, công việcCác phần mềm khác theo nghiệp vụ/ quy trình của doanh nghiệp', 'Yêu cầu kỹ năng chínhFramework & Thư viện: React Native; Redux; RxJS.Ngôn ngữ lập trình: TypeScript; HTML; CSS/SASS/SCSS; JavaScript.Khác: RESTful API; Giao thức giao tiếp web; Công cụ phát triển JavaScript.Kỹ năng thực hànhThành thạo git, công cụ quản lý versionKhả năng debug và xử lý lỗi, tư duy logicPhân tích & tối ưu hóa hiệu suất.Thiết kế responsive (phù hợp đa thiết bị).Ứng viên có ít nhất 1 năm kinh nghiệm (Middle), có khả năng làm việc độc lập, tính chủ động caoCó kinh nghiệp tích hợp cổng thanh toán trực tuyến, hóa đơn điện tử, giao hàng..Kết nối với nền tảng thương mại điện tử (Shopee, Lazada, Tiktok, Tiki...).Tích hợp hệ thống chat realtime sử dụng WebSocket', 'Lương tháng 13BHXH/BHYT theo quy địnhMôi trường thân thiện, gần gũiNghỉ phép theo quy định 12 ngày/nămLương/thưởng theo năng lực, review lương định kỳDu lịch/team building hàng năm', 'Trụ sở chính công ty', 835, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (100, 88, '2028375', 'Bridge Engineer (Tiếng Nhật N2 Trở Lên) - Nghỉ T7 CN', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-19 19:07:55.655775', '2026-05-28 19:07:55.655775', 5, '- Quản lý dự án xuyên suốt các giai đoạn phát triển, phối hợp chặt chẽ với PM phía khách hàng và đội ngũ phát triển.- Đóng vai trò cầu nối giữa khách hàng và team kỹ thuật: truyền đạt yêu cầu, dịch/phiên dịch khi cần.- Lập kế hoạch dự án, quản lý tiến độ, theo dõi và xử lý các vấn đề phát sinh trong quá trình triển khai.- Tự chủ trong việc điều hành dự án; với các dự án bảo trì, có thể đảm nhiệm độc lập mà không cần hỗ trợ quản lý.- Chịu trách nhiệm về chất lượng của dự án từ khi bắt đầu triển khai tới khi dự án hoàn thành và sản phẩm được nghiệm thu.', '- Có từ 3 năm kinh nghiệm PM/ Brse trở lên hoặc kinh nghiệm tham gia/quản lý nhiều dự án- Có kinh nghiệm xuyên suốt toàn bộ chu trình dự án, từ lập kế hoạch đến khi hoàn thành- Có kinh nghiệm thực tế trong quản lý issue, giải quyết vấn đề và xác nhận/ nghiệm thu sản phẩm bàn giao- Có kinh nghiệm điều phối và làm việc với nhiều bên liên quan (stakeholders)[Nice to have]- Có kiến thức cơ bản về IT- Có kinh nghiệm làm việc ở vị trí Developer hoặc Tester- Đã từng học tập hoặc làm việc tại NhậtYÊU CẦU NỘP CV BẰNG TIẾNG NHẬT', '- Chế độ làm việc linh hoạt Flexible time (7:30 AM - 06:30PM) làm việc 8h/ngày, chế độ work from home 1 ngày/ tuần- Xét tăng lương và thưởng 2 lần/năm- Bảo hiểm sức khỏe Bảo Việt, khám sức khỏe hàng năm ở bệnh viện uy tín- Chế độ chăm sóc phụ nữ: nghỉ phụ nữ tối đa 5h/tháng; nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi 1h/ngày.- Trợ cấp chứng chỉ Năng lực tiếng Nhật JLPT một lần (tối đa 10 triệu VND)- Du lịch Công ty, các câu lạc bộ bóng đá, bơi, gym ...', 'Trụ sở chính công ty', 397, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (101, 88, '1889547', 'IT Comtor (Tiếng Nhật N2 Trở Lên) - Nghỉ T7 CN', NULL, NULL, '1 năm', 'Nhân viên', '2026-04-13 19:07:55.655775', '2026-04-28 19:07:55.655775', 5, '- Thực hiện dịch thuật tài liệu, biên – phiên dịch trong phạm vi dự án được phân công;- Phân tích, làm rõ và truyền đạt yêu cầu giữa các bên liên quan, đảm bảo thông tin đầy đủ, rõ ràng và chính xác;- Hỗ trợ thiết lập và duy trì kênh giao tiếp thông suốt trong quá trình triển khai dự án;- Tham gia hỗ trợ các công việc vận hành dự án ở mức cơ bản, đồng thời học hỏi kiến thức, kỹ năng về quản lý dự án;- Hỗ trợ theo dõi và quản lý tiến độ dự án từ giai đoạn lập kế hoạch đến khi bàn giao sản phẩm;- Hỗ trợ quản lý, phối hợp xử lý các vấn đề phát sinh và tham gia xác nhận nghiệm thu sản phẩm.', '[Yêu cầu chung]- Trên 1 năm kinh nghiệm làm việc có liên quan- Trình độ học vấn tối thiểu: cử nhân- Tiếng Nhật tương đương N2 trở lên- Kỹ năng giao tiếp tốt[Nice to have]- Có kiến thức cơ bản về IT- Có kinh nghiệm làm việc ở vị trí Developer hoặc Tester- Đã từng học tập hoặc làm việc tại NhậtYÊU CẦU NỘP CV BẰNG TIẾNG NHẬT', '- Chế độ làm việc linh hoạt Flexible time (7:30 AM - 06:30PM) làm việc 8h/ngày, chế độ work from home 1 ngày/ tuần- Xét tăng lương và thưởng 2 lần/năm- Bảo hiểm sức khỏe Bảo Việt, khám sức khỏe hàng năm ở bệnh viện uy tín- Chế độ chăm sóc phụ nữ: nghỉ phụ nữ tối đa 5h/tháng; nghỉ sau sinh cho nhân viên nữ có con dưới 1 tuổi 1h/ngày.- Trợ cấp chứng chỉ Năng lực tiếng Nhật JLPT một lần (tối đa 10 triệu VND)- Du lịch Công ty, các câu lạc bộ bóng đá, bơi, gym ...', 'Trụ sở chính công ty', 946, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (102, 89, '1984531', 'Nhân Viên Edit Video', 8.00, 12.00, 'Không yêu cầu', 'Nhân viên', '2026-04-09 19:07:55.655775', '2026-05-14 19:07:55.655775', 6, 'Nhận video, lọc bỏ cảnh thừa.Thêm âm thanh, hình ảnh, hiệu ứng cho video.Hoàn thiện và chỉnh sửa (nếu cần).Thiết kế ảnh đại diện cho video (khi phát sinh).Thực hiện các công việc khác theo chỉ đạo của cấp trên.', 'Bằng cấp: Ưu tiên tốt nghiệp ngành liên quan đến công nghệ thông tin.Kiến thức: Ưu tiên có hiểu biết về kịch bản, nội dung cho trẻ em.Kĩ năng: Thành thạo Pre, biết sử dụng thêm Pts là một lợi thế.Biết sử dụng AI cơ bản, tiếng Anh là một lợi thế. Kinh nghiệm: Không yêu cầu sẽ được đào tạo khi làm. Phẩm chất, thái độ:+ Tư duy tốt, sáng tạo, hài hước nhanh nhẹn.+ Chủ động trong công việc.+ Luôn sẵn sàng học hỏi, kiến thức mới.+ Đam mê với công việc, định hướng gắn bó lâu dài.', 'Thu nhập cạnh tranh theo năng lực: 8.000.000 - 12.000.000 đồng.Thử việc tối đa 1 tháng, bảo hiểm đóng ngay khi lên chính thức.Hơn 20 loại thưởng, trợ cấp mỗi năm các dịp: Lễ, Tết, sinh nhật, ngày phụ nữ, đàn ông,...Được đào tạo thường xuyên, lộ trình thăng tiến rõ ràng, xét tăng lương hàng năm.Môi trường làm việc khuyến khích sự chủ động học hỏi, sáng tạo, phát triển bản thân.Chế độ chăm sóc sức khỏe (đồ ăn vặt, khám sức khỏe định kì, bảo hiểm sức khỏe).Du lịch hàng năm và các hoạt động vui chơi tập thể thường xuyên.', 'Trụ sở chính công ty', 607, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (104, 92, '1761483', '3D Designer', NULL, NULL, '2 năm', 'Nhân viên', '2026-04-27 19:07:55.655775', '2026-05-17 19:07:55.655775', 7, '1. Thiết kế và dựng background cho livestream trên các nền tảng như TikTok, Shopee, Lazada…, đảm bảo không gian trực quan, hấp dẫn và phù hợp với concept từng chiến dịch.2. Thiết kế các ấn phẩm khác theo yêu cầu, phục vụ cho nội dung video, truyền thông, sự kiện...3. Phối hợp cùng các team Creative, Marketing, Account, Operation... để phát triển ý tưởng, concept, đảm bảo bám sát brief và yêu cầu từ khách hàng/nhãn hàng.4. Cập nhật xu hướng thiết kế mới nhất, ứng dụng sáng tạo vào công việc nhằm nâng cao chất lượng hình ảnh và trải nghiệm người xem.5. Đảm bảo sản phẩm thiết kế đúng tiến độ, chất lượng và nhận diện thương hiệu.', '1. Trình độ học vấn: Cử nhân hoặc có kinh nghiệm liên quan2. Kinh nghiệm:- Kinh nghiệm thiết kế cho các dự án Livestream, ecommerce là một lợi thế- Có khả năng sử dụng Photoshop, Illustrator, InDesign và các kỹ năng khác để tạo ra 2D, 3D, Motion Graphic Design.- Khả năng làm việc độc lập và làm việc nhóm.- Khả năng giao tiếp và đàm phán tốt, hướng ngoại- Tư duy tích cực, chịu được áp lực môi trường agency- Đính kèm Portfolio trong đơn ứng tuyển', 'BHXH theo quy định, phép nămBảo hiểm sức khỏeHoạt động nội bộ: Team Building, Happy Friday, khu vực Pantry,...Phát triển cùng TSP tiềm năng hàng đầu, làm việc với các đối tác, tập đoàn đa quốc gia uy tín tại Việt NamMôi trường làm việc năng động, sáng tạoPhong cách làm việc linh hoạt, khuyến khích đưa ra các đề xuất, dự án sáng tạoCơ hội thăng tiến rõ ràng dựa trên năng lực', 'Trụ sở chính công ty', 793, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (112, 98, '1997056', 'Frontend Reactjs Developer', NULL, NULL, '4 năm', 'Nhân viên', '2026-05-07 19:07:55.655775', '2026-06-01 19:07:55.655775', 5, 'Leading the way in financial IT service market in Korea, we now seek to expand our expertise to the APACParticipation in R&D AI Agent development Project Solution DevelopmentFrontend DevelopmentRequirements analysis and designEnsuring own program quality', 'Experience in other SPAs (Vue, TypeScript, etc)Hybrid app experienceCommunicate in English at an average levelWeb application development experience (4 years or more)React experienceCan develop HTML, CSS, Javascript, jQueryExperience with collaboration tools such as Git, Jira and Confluence', 'Attractive salary and bonus will be discussed after going through CV & InterviewTopik allowanceReview capacity annually and adjust salary increases according to work performance.Health care: Premium health insurance, Annual health check-upYoung working environmentGood career development opportunities with interesting and challenging projects.English, Korean, technical, soft skills training courses.Opportunity to learn special courses from LG CNS, new technology and security.Gifts on holidays (April 30th - May 1st, September 2nd, Tet, etc.)Outdoor activities with company support: sports clubs, team building, happy hour parties, birthdays, travel, employee and family events, etc.Working hours: 8 hours from Monday - Friday (8 hours/day)Location: Keangnam Landmark 72, Pham Hung, Yen Hoa, Hanoi', 'Trụ sở chính công ty', 647, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (142, 127, '2029479', 'Graphic Designer', NULL, NULL, '2 năm', 'Nhân viên', '2026-04-30 19:07:55.655775', '2026-06-01 19:07:55.655775', 2, '1. Thiết kế hình ảnh truyền thông và POSM- Thiết kế các ấn phẩm phục vụ truyền thông online (Facebook, Website, Digital Ads…) và POSM offline tại hệ thống nhà thuốc (poster, standee, wobbler, banner, leaflet…).- Đảm bảo nội dung hình ảnh rõ ràng, dễ hiểu, phù hợp đặc thù ngành dược – chăm sóc sức khỏe.- Phối hợp với các bộ phận liên quan để chỉnh sửa, hoàn thiện thiết kế theo yêu cầu2. Video và Nội dung số- Thực hiện quay dựng, chỉnh sửa hậu kỳ video cho các nền tảng TikTok, YouTube và các kênh truyền thông khác.- Sản xuất video ngắn phục vụ truyền thông sản phẩm, thương hiệu, hoạt động nhà thuốc và các chiến dịch marketing.- Đảm bảo video đúng định hướng nội dung, hình ảnh thương hiệu và tiến độ triển khai.3. Phối hợp sáng tạo nội dung- Phối hợp với bộ phận Content/Marketing để chuyển hóa ý tưởng sáng tạo thành sản phẩm hình ảnh và video hoàn chỉnh.- Góp ý, đề xuất phương án thể hiện hình ảnh phù hợp với từng chiến dịch truyền thông4. Hỗ trợ dự án thương hiệu và sự kiện- Hỗ trợ thiết kế hình ảnh cho các hoạt động branding, sự kiện, activation, co-marketing với đối tác.- Tham gia thiết kế ấn phẩm cho chương trình khuyến mãi, khai trương nhà thuốc, hội thảo, truyền thông nội bộ.5. Quản lý và tuân thủ nhận diện thương hiệu- Đảm bảo toàn bộ sản phẩm thiết kế tuân thủ nghiêm ngặt bộ nhận diện thương hiệu Trung Sơn.- Quản lý, lưu trữ file thiết kế khoa học, phục vụ cho các phòng ban và dự án liên quan6. Báo cáo và công việc khác- Thực hiện báo cáo công việc định kỳ/đột xuất theo yêu cầu của Quản lý trực tiếp.- Thực hiện các công việc khác liên quan đến thiết kế theo phân công', '1. Trình độ học vấn- Tốt nghiệp Cao đẳng/Đại học chuyên ngành Thiết kế đồ họa, Mỹ thuật, Truyền thông đa phương tiện hoặc các ngành liên quan2. Kinh nghiệm- Có tối thiểu 02 năm kinh nghiệm ở vị trí Thiết kế.- Ưu tiên ứng viên có kinh nghiệm trong bán lẻ, FMCG, dược phẩm hoặc chuỗi hệ thống3. Kiến thức chuyên môn- Hiểu và áp dụng tốt các nguyên tắc thiết kế đồ họa, bố cục, màu sắc, hình ảnh.- Nắm được yêu cầu hình ảnh truyền thông trong ngành dược – chăm sóc sức khỏe.- Hiểu và tuân thủ quy chuẩn nhận diện thương hiệu4. Kỹ năng- Thành thạo Photoshop, Illustrator; ưu tiên biết Premiere/CapCut/After Effects (cơ bản).- Có khả năng quay – dựng – chỉnh sửa video ngắn.- Kỹ năng làm việc nhóm, phối hợp tốt với nhiều phòng ban.- Quản lý thời gian, đảm bảo tiến độ công việc5. Phẩm chất cá nhân- Cẩn thận, tỉ mỉ, có trách nhiệm với sản phẩm.- Chủ động, tinh thần học hỏi và cải tiến.- Chịu được áp lực công việc và deadline.- Ưu tiên ứng viên nữ', 'Môi trường làm việc trẻ trung, năng động, chuyên nghiệp.Cơ hội phát triển bản thân và nâng cao kỹ năng.Được tham gia các khóa đào tạo chuyên môn.Các chế độ bảo hiểm theo quy định của pháp luật.Các hoạt động teambuilding, du lịch hàng năm.', 'Trụ sở chính công ty', 437, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (116, 101, '2030272', 'Game Artist', NULL, NULL, '1 năm', 'Nhân viên', '2026-04-12 19:07:55.655775', '2026-05-18 19:07:55.655775', 7, 'Mega Combat Studio là một studio làm game nhỏ tại Hồ Chí Minh, chuyên phát triển dòng game MMORPG 2D pixel, thành công với tựa game Treasure Hunter hiện đang có mặt trên Apple Store và CHPlay.
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (117, 102, '2036545', 'Drafting Specialist - AUS Market - Revit Software', NULL, NULL, '3 năm', 'Nhân viên', '2026-05-08 19:07:55.655775', '2026-06-05 19:07:55.655775', 3, 'Translate architectural drawings into detailed Revit modelsProduce documentation aligned with Australian standardsCoordinate with Australian project managersApply timber construction knowledge in drafting workflowIdentify errors before documentation reaches siteMaintain drafting accuracy and system compliance', '3–5+ years’ experience in Australian residential constructionStrong proficiency in RevitKnowledge of Australian building codes (NCC exposure preferred)Timber framing experience highly regardedStrong English communication skillsStructured, deadline-focused mindset', '-13th-month salary bonus + attractive performance bonus (14th-month salary) + annual performance appraisal-Monthly snack for staff, monthly meal allowance, have a clean spacious pantry-Company''s labor policy completely pursuant to Vietnamese labor legislation plus other benefits offered by the company (Company trip, Anniversary, Holiday, etc.)-Young and dynamic international working environment with modern equipment for staff-Annual Health Check paid for and organized by MyTeam ; An annual Private Health Insurance policy provided by MyTeam.-Exciting leisure: sport and art events (English training class with in-house teacher, football club...)-Competitive salary based on ability and experience.-Annual Anniversary party together Teambuilding event', 'Trụ sở chính công ty', 418, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (118, 103, '1948485', 'Graphic Designer POD', 9.00, 15.00, 'Dưới 1 năm', 'Nhân viên', '2026-05-12 19:07:55.655775', '2026-06-03 19:07:55.655775', 7, 'Redesign lại các mẫu sản phẩm POD theo yêu cầu của team ideasLên mockup trực quan, đảm bảo thể hiện đúng màu sắc, bố cục và phong cách sản phẩm trên các nền tảng bán hàng (Etsy, TikTok Shop, v.v).Phối hợp chặt chẽ với team Ideas để phát triển thiết kế, tối ưu hình ảnh cho từng dòng sản phẩm (áo thun, poster, sticker, v.v).Theo dõi và cập nhật xu hướng thiết kế POD, đóng góp ý tưởng sáng tạo', 'Có kinh nghiệm hoặc hiểu biết về lĩnh vực POD (Chưa có kinh nghiệm sẽ được đào tạo).Sử dụng thành thạo Photoshop, Illustrator hoặc các công cụ thiết kế tương tự.Có gu thẩm mỹ tốt, khả năng sáng tạo và làm việc nhóm hiệu quả.', 'Lương: 9 – 15 triệuThử việc nhận 85% lươngTrợ cấp ăn trưa: 30.000đ/ngàyThưởng theo hiệu suất và sản phẩm bán chạyCơ hội thăng tiến rõ ràng lên vị trí LeaderMôi trường trẻ, năng động, được hỗ trợ tối đa về ý tưởng và công cụ', 'Trụ sở chính công ty', 762, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (138, 122, '2011381', 'Backend Lead Engineer', 50.00, 70.00, '3 năm', 'Nhân viên', '2026-05-20 19:07:55.655775', '2026-06-20 19:07:55.655775', 5, 'NHỮNG KẾT QUẢ CỤ THỂ CẦN ĐẠT TRONG 6 - 18 THÁNGLàm chủ và tối ưu hóa thành công các ETL/ELT jobs và event pipelines để dữ liệu từ TikTok Shop, Shopify, Facebook đổ về hệ thống luôn chính xác và thời gian thực (Real-time).Thiết kế và chuẩn hóa lại Schema Data tối ưu cho việc truy vấn báo cáo hiệu suất (Product performance, Ads metrics).Dẫn dắt việc nâng cấp kiến trúc (Refactor/Microservices) giúp hệ thống chịu tải tốt hơn khi quy mô SKU và đơn hàng tăng trưởng đột biến.Xây dựng đội ngũ backend kế thừa thông qua việc thiết lập coding guidelines và mentoring.CHỈ SỐ ĐO LƯỜNG THÀNH CÔNGData Accuracy & Integrity: Tỷ lệ sai lệch dữ liệu giữa các nền tảng tích hợp (TikTok/Shopify) và hệ thống nội bộ < 1%.System Performance: Giảm thời gian phản hồi API và tối ưu hóa query plan cho các tập dữ liệu lớn (Heavy Data).Time-to-Market: Tốc độ chuyển hóa từ yêu cầu kinh doanh sang giải pháp kỹ thuật thực tế mà không cần qua trung gian PM.Engineering Quality: Tỷ lệ bug nghiêm trọng phát sinh sau release và hiệu quả của các buổi Code Review.', 'Thành thạo PHP/Laravel (bắt buộc) và có tư duy tốt về MySQL/Postgres (JSONB, Indexing, Transaction design).Khả năng nhìn bức tranh tổng thể để tìm "điểm gãy" của hệ thống trên nhiều phương diện: vận hành, logistics, marketing.Tự bóc tách logic kinh doanh thành phương án kỹ thuật khả thi, biết cân bằng giữa tốc độ triển khai và rủi ro kỹ thuật (Trade-off).Kinh nghiệm xây dựng Pipeline xử lý dữ liệu lớn và các hệ thống bất đồng bộ (Asynchronous pipeline, Queue/Worker).Phải xử lý vấn đề ngay cả khi yêu cầu từ phía Business chưa rõ ràng hoặc liên tục thay đổi theo thị trường eCommerce.Giải quyết bài toán hiệu năng khi đối mặt với lượng dữ liệu "khủng" từ các nền tảng quảng cáo và vận hành.Duy trì sự ổn định của hệ thống khi tích hợp với nhiều API bên thứ ba có độ phức tạp cao.', 'Môi trường "Thực chiến": Không làm outsourcing lẻ tẻ, bạn xây dựng sản phẩm cho hệ thống eCommerce thực tế, đa thị trường, đa nền tảng.Lộ trình phát triển đột phá: Cơ hội thăng tiến lên Solution Architect, nơi bạn không chỉ giỏi code mà còn am hiểu sâu sắc về cách vận hành một doanh nghiệp công nghệ toàn diện.Thu nhập cạnh tranh nhất thị trường, tương xứng với năng lực và hiệu quả công việc. Chúng tôi không giới hạn thu nhập vị trí này – giới hạn duy nhất chính là năng lực của bạn. Thưởng tháng 13 và thưởng kinh doanh cuối năm rõ ràng, minh bạchChính sách làm việc linh hoạt (Hybrid / Work From Home), đảm bảo cân bằng giữa công việc và cuộc sốngMôi trường làm việc hạnh phúc & hiện đại. Ghế công thái học 100% nhân viên. Pantry luôn đầy đồ ăn. Tiệc sinh nhật hàng tháng, du lịch nước ngoài. Bàn bi-a, không gian giải trí và văn phòng view tàu điện trên cao cực chillLàm việc với hệ thống eCommerce thực chiến, dữ liệu lớn, đa thị trường. Tiếp cận nhiều API lớn: TikTok Shop, Shopify, Facebook…', 'Trụ sở chính công ty', 173, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (123, 108, '2023214', 'Nhân Viên Business Analyst', 15.00, 25.00, '2 năm', 'Nhân viên', '2026-05-04 19:07:55.655775', '2026-05-19 19:07:55.655775', 5, '-Khảo sát quy trình, nghiệp vụ, thu thập và phân tích yêu cầu để thiết kế User Stories
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (128, 111, '2025901', 'Nhân Viên Thiết Kế Đồ Họa (Upto 15M + Thưởng)', 13.00, 15.00, '2 năm', 'Nhân viên', '2026-05-21 19:07:55.655775', '2026-06-22 19:07:55.655775', 7, 'Chịu trách nhiệm thiết kế và sản xuất POSM: Hồ sơ năng lực, catalogue, poster, banner, backdrop, bandroll…Thiết kế các ấn phẩm online theo kế hoạch Marketing và phối hợp với content, digital trong việc lên ý tưởng và thiết kế các ấn phẩm hỗ trợ kênh thương mại điện tử: hình ảnh sản phẩm, banner livestream, các ấn phẩm hỗ trợ các chiến dịch bán hàng của thương mại điện tử.Chụp hình, quay video sản phẩm hiện tại và mới ra mắt, xây dựng nguồn hình ảnh có chất lượng.Thực hiện các công việc khác theo sự phân công của cấp trên.', 'Tốt nghiệp CĐ/ ĐH chuyên ngành thiết kế đồ họa, hoặc các chuyên ngành có liên quan. Ưu tiên ứng viên nam đã từng làm trong ngành nội thất, bán lẻTừ 2 năm kinh nghiệmCó khả năng thẩm mỹ cao và sáng tạo trong công việc, liên tục cập nhật xu hướng thiết kế mới phù hợp với ngành hàng.Có kỹ năng chụp hình, quay video tốt.Chuyên về Graphic. Thành thạo: Ai, Ps, Indesign và có kiến thức về SketchupCó khả năng làm việc theo nhóm, có trách nhiệm cao và chủ động trong công việc', 'Lương cứng từ 12-15 triệu/ tháng tùy kinh nghiệm, Thưởng KPI sáng tạoThử việc full lươngBHXH đầy đủ theo quy định của pháp luật hiện hànhCơ hội phát triển bản thân & làm việc tại công ty quy mô lớn, thương hiệu quốc gia', 'Trụ sở chính công ty', 977, NULL, 1);
