INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (133, 117, '2031357', 'Effect-Animation (Unity) - Thu Nhập Đến 35 Triệu Tại Hồ Chí Minh', NULL, 35.00, '3 năm', 'Nhân viên', '2026-05-09 19:07:55.655775', '2026-06-17 19:07:55.655775', 7, 'Tham gia phát triển game 3D trên nền tảng smartphone, ứng viên sẽ đảm nhận các công việc sau:
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (134, 118, '1935075', 'Graphic Design (Channel Marketing)', NULL, NULL, '1 năm', 'Nhân viên', '2026-05-05 19:07:55.655775', '2026-05-27 19:07:55.655775', 5, 'Thiết kế hình ảnh cho các kênh truyền thông website, social media (Facebook, TikTok, v.v.), đảm bảo đồng nhất nhận diện thương hiệu cho cửa hàng và DealerThiết kế POSM (poster, standee, backdrop, banner, tờ rơi, leaflet, shelf talker...) phục vụ các chiến dịch marketing, trưng bày và sự kiệnPhối hợp cùng team Digital Marketing trong việc phát triển KV, banner quảng cáo, Meta Ads, TikTok AdsTham gia xây dựng và đề xuất concept visual cho các chiến dịch truyền thông của DealerĐảm bảo tiến độ và chất lượng thiết kế theo brief từ Marketing team hoặc Brand team', 'Sử dụng thành thạo Photoshop, Illustrator (Biết sử dụng After Effects, Premiere Pro là lợi thế)Có thẩm mỹ tốt, khả năng cảm nhận layout, màu sắc và hình ảnh phù hợp với từng nhóm khách hàng mục tiêu.Có 1 năm kinh nghiệm ở vị trí liên quanHiểu cơ bản về branding, digital ads và xu hướng thiết kếTinh thần trách nhiệm cao, làm việc nhóm tốt, có khả năng tự chủ và quản lý deadline', 'Thưởng tháng 13,BHXH, BHYT, BHTN đầy đủ theo quy định của pháp luậtBảo hiểm sức khỏe GeneraliTham gia Team building, New-year party và các sự kiện có liên quan do công ty tổ chứcLàm việc trong môi trường trẻ trung, năng động và linh hoạtĐược đào tạo, phát triển, môi trường và có nhiều cơ hội thăng tiếnMua sản phẩm công ty với giá ưu đãiCác chế độ khác theo quy định của pháp luật', 'Trụ sở chính công ty', 688, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (135, 120, '1763565', 'Thực Tập Sinh Backend AI', 3.00, NULL, 'Không yêu cầu', 'Nhân viên', '2026-04-15 19:07:55.655775', '2026-05-22 19:07:55.655775', 3, 'MỤC TIÊUChương trình thực tập tại MekongAI không chỉ là cơ hội học tập ngắn hạn mà là hành trình tham gia trực tiếp vào quá trình xây dựng các giải pháp AI tùy chỉnh thực tế cho doanh nghiệp SME Việt Nam – từ backend hệ thống đến triển khai sản phẩm vận hành thực tế.Bạn sẽ đồng hành cùng đội ngũ MekongAI trong việc phát triển:- Chatbot RAG có khả năng đọc hiểu dữ liệu nội bộ và tư vấn chính xác theo ngữ cảnh.- AI Agent tự động hóa quy trình làm việc theo workflow linh hoạt.- Hệ thống backend tích hợp sâu với LLM, dữ liệu và các công cụ automation.- Ưu tiên các ứng viên có quan tâm hoặc hiểu biết về IoT, đặc biệt nền tảng ESP32.NỘI DUNG CÔNG VIỆCTrong quá trình thực tập, bạn sẽ tham gia và hỗ trợ các nhiệm vụ sau:1. Xây dựng backend phục vụ hệ thống AI:- Tham gia phát triển  RAG, xử lý prompting và tích hợp LLM.- Thiết kế, triển khai và tối ưu API phục vụ các chức năng AI.3. Xử lý và khai thác dữ liệu:- Xây dựng pipeline ingestion dữ liệu từ nhiều định dạng (PDF, DOCX, HTML…).- Triển khai vector database (Qdrant / OpenSearch).5. Phối hợp triển khai sản phẩm:- Tham gia quá trình thiết kế, thử nghiệm và cải tiến sản phẩm thực tế.Môi trường tại MekongAI khuyến khích tinh thần học hỏi, tư duy hệ thống và khả năng triển khai thực chiến. Đây là cơ hội để bạn phát triển năng lực kỹ thuật, hiểu đúng cách AI vận hành trong doanh nghiệp, và tham gia trực tiếp vào các dự án mang giá trị ứng dụng cao.', 'Sinh viên năm 3, 4 hoặc đã tốt nghiệp ngành Khoa học Máy tính, Trí tuệ nhân tạo, Công nghệ thông tin hoặc các ngành liên quanCó nền tảng backendBiết Python, Git, RESTful API, SQL NoSQL Vector DB, kiến thức cơ bản về AI, LLM, Prompt Engineering, Machine Learning workflowsBiết cách tối ưu hệ thống backend (performance, chi phí, bảo mậtTư duy logic, chủ động học hỏi, có khả năng làm việc nhóm tốtYêu thích và có thể gắn bó lâu dài với đơn vị nếu hoàn thành tốt kỳ thực tập và trở thành nhân viên chính thứcƯu tiên nếu cóƯu tiên ứng viên có hiểu biết  đam mê IOT (Internet Of Things), đặc biệt liên quan đến ESP32Từng làm việc với Qdrant, LangChain, LlamaIndex hoặc các RAG frameworkCó hiểu biết về LLM, Prompt Engineering hoặc từng thử nghiệm Agent', 'Trợ cấp thực tập: 3 triệu thángHỗ trợ cơm trưaĐược tham gia dự án thật cùng đội ngũ devCó mentor hướng dẫn, lộ trình phát triển nghề nghiệp rõ ràngMôi trường startup năng động, linh hoạt thời gian, đề cao tinh thần học hỏiCơ hội trở thành thành viên chính thức Team Dev tại MekongAI sau kỳ thực tập', 'Trụ sở chính công ty', 495, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (136, 122, '2011863', 'Backend Lead Engineer', 50.00, 70.00, '3 năm', 'Nhân viên', '2026-04-30 19:07:55.655775', '2026-05-18 19:07:55.655775', 5, 'KEY OUTCOMES: NHỮNG KẾT QUẢ CỤ THỂ CẦN ĐẠT TRONG 6 - 18 THÁNGLàm chủ và tối ưu hóa thành công các ETL/ELT jobs và event pipelines để dữ liệu từ TikTok Shop, Shopify, Facebook đổ về hệ thống luôn chính xác và thời gian thực (Real-time).Thiết kế và chuẩn hóa lại Schema Data tối ưu cho việc truy vấn báo cáo hiệu suất (Product performance, Ads metrics).Dẫn dắt việc nâng cấp kiến trúc (Refactor/Microservices) giúp hệ thống chịu tải tốt hơn khi quy mô SKU và đơn hàng tăng trưởng đột biến.Xây dựng đội ngũ backend kế thừa thông qua việc thiết lập coding guidelines và mentoring.SUCCESS INDICATORS: CHỈ SỐ ĐO LƯỜNG THÀNH CÔNGData Accuracy & Integrity: Tỷ lệ sai lệch dữ liệu giữa các nền tảng tích hợp (TikTok/Shopify) và hệ thống nội bộ < 1%.System Performance: Giảm thời gian phản hồi API và tối ưu hóa query plan cho các tập dữ liệu lớn (Heavy Data).Time-to-Market: Tốc độ chuyển hóa từ yêu cầu kinh doanh sang giải pháp kỹ thuật thực tế mà không cần qua trung gian PM.Engineering Quality: Tỷ lệ bug nghiêm trọng phát sinh sau release và hiệu quả của các buổi Code Review.', 'NĂNG LỰC & KỸ NĂNG CẦN CÓExpert Backend Stack: Thành thạo PHP/Laravel (bắt buộc) và có tư duy tốt về MySQL/Postgres (JSONB, Indexing, Transaction design).System Thinking: Khả năng nhìn bức tranh tổng thể để tìm "điểm gãy" của hệ thống trên nhiều phương diện: vận hành, logistics, marketing.Problem Solving: Tự bóc tách logic kinh doanh thành phương án kỹ thuật khả thi, biết cân bằng giữa tốc độ triển khai và rủi ro kỹ thuật (Trade-off).Data Engineering: Kinh nghiệm xây dựng Pipeline xử lý dữ liệu lớn và các hệ thống bất đồng bộ (Asynchronous pipeline, Queue/Worker).CHALLENGES: NHỮNG THÁCH THỨC LỚN CỦA VỊ TRÍComplexity & Ambiguity: Phải xử lý vấn đề ngay cả khi yêu cầu từ phía Business chưa rõ ràng hoặc liên tục thay đổi theo thị trường eCommerce.Data Volume: Giải quyết bài toán hiệu năng khi đối mặt với lượng dữ liệu "khủng" từ các nền tảng quảng cáo và vận hành.Integration Maze: Duy trì sự ổn định của hệ thống khi tích hợp với nhiều API bên thứ ba có độ phức tạp cao.', 'Bạn là "chủ sở hữu" hệ thống Backend, mỗi dòng code của bạn ảnh hưởng trực tiếp đến doanh thu và sự tăng trưởng của các thương hiệu.Môi trường "Thực chiến": Không làm outsourcing lẻ tẻ, bạn xây dựng sản phẩm cho hệ thống eCommerce thực tế, đa thị trường, đa nền tảng.Lộ trình phát triển đột phá: Cơ hội thăng tiến lên Solution Architect, nơi bạn không chỉ giỏi code mà còn am hiểu sâu sắc về cách vận hành một doanh nghiệp công nghệ toàn diện.Thu nhập cạnh tranh nhất thị trường, tương xứng với năng lực và hiệu quả công việc. Chúng tôi không giới hạn thu nhập vị trí này – giới hạn duy nhất chính là năng lực của bạn. Thưởng tháng 13 và thưởng kinh doanh cuối năm rõ ràng, minh bạch.Chính sách làm việc linh hoạt (Hybrid / Work From Home), đảm bảo cân bằng giữa công việc và cuộc sống.Môi trường làm việc hạnh phúc & hiện đại. Ghế công thái học 100% nhân viên. Pantry luôn đầy đồ ăn. Tiệc sinh nhật hàng tháng, du lịch nước ngoài. Bàn bi-a, không gian giải trí và văn phòng view tàu điện trên cao cực chill.Làm việc với hệ thống eCommerce thực chiến, dữ liệu lớn, đa thị trường. Tiếp cận nhiều API lớn: TikTok Shop, Shopify, Facebook…', 'Trụ sở chính công ty', 855, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (137, 123, '2011863', 'Backend Lead Engineer', 50.00, 70.00, '3 năm', 'Nhân viên', '2026-04-12 19:07:55.655775', '2026-05-21 19:07:55.655775', 5, 'KEY OUTCOMES: NHỮNG KẾT QUẢ CỤ THỂ CẦN ĐẠT TRONG 6 - 18 THÁNGLàm chủ và tối ưu hóa thành công các ETL/ELT jobs và event pipelines để dữ liệu từ TikTok Shop, Shopify, Facebook đổ về hệ thống luôn chính xác và thời gian thực (Real-time).Thiết kế và chuẩn hóa lại Schema Data tối ưu cho việc truy vấn báo cáo hiệu suất (Product performance, Ads metrics).Dẫn dắt việc nâng cấp kiến trúc (Refactor/Microservices) giúp hệ thống chịu tải tốt hơn khi quy mô SKU và đơn hàng tăng trưởng đột biến.Xây dựng đội ngũ backend kế thừa thông qua việc thiết lập coding guidelines và mentoring.SUCCESS INDICATORS: CHỈ SỐ ĐO LƯỜNG THÀNH CÔNGData Accuracy & Integrity: Tỷ lệ sai lệch dữ liệu giữa các nền tảng tích hợp (TikTok/Shopify) và hệ thống nội bộ < 1%.System Performance: Giảm thời gian phản hồi API và tối ưu hóa query plan cho các tập dữ liệu lớn (Heavy Data).Time-to-Market: Tốc độ chuyển hóa từ yêu cầu kinh doanh sang giải pháp kỹ thuật thực tế mà không cần qua trung gian PM.Engineering Quality: Tỷ lệ bug nghiêm trọng phát sinh sau release và hiệu quả của các buổi Code Review.', 'NĂNG LỰC & KỸ NĂNG CẦN CÓExpert Backend Stack: Thành thạo PHP/Laravel (bắt buộc) và có tư duy tốt về MySQL/Postgres (JSONB, Indexing, Transaction design).System Thinking: Khả năng nhìn bức tranh tổng thể để tìm "điểm gãy" của hệ thống trên nhiều phương diện: vận hành, logistics, marketing.Problem Solving: Tự bóc tách logic kinh doanh thành phương án kỹ thuật khả thi, biết cân bằng giữa tốc độ triển khai và rủi ro kỹ thuật (Trade-off).Data Engineering: Kinh nghiệm xây dựng Pipeline xử lý dữ liệu lớn và các hệ thống bất đồng bộ (Asynchronous pipeline, Queue