INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (140, 125, '2028871', 'Mobile Developer (IOS / Android)', 55.00, 75.00, '3 năm', 'Nhân viên', '2026-04-24 19:07:55.655775', '2026-05-24 19:07:55.655775', 5, 'Design, develop, and maintain mobile applications for Android or iOS platforms.Work closely with the product team to deliver high-quality apps with a user-centric approach.Implement clean, maintainable, and efficient code for Android or iOS platforms.Collaborate with cross-functional teams to define and implement new features andimprovements.Debug, troubleshoot, and optimize application performance to ensure smooth userexperiences.Integrate third-party APIs and libraries to enhance app functionality.Ensure the technical feasibility of UI/UX designs and optimize for performance andscalability.Stay updated with the latest mobile development trends and technologies.Conduct unit testing, code reviews, and ensure high code quality standards.', 'Bachelor’s degree in Computer Science, Information Technology, or a related field.Strong experience with Android development (Java/Kotlin) or iOS development (Swift/Objective-C).Proven experience in building and deploying apps on the Google Play Store and Apple App Store.Solid understanding of mobile application architecture, design patterns (MVVM, MVC), and best practices.Proficiency with IDEs like Android Studio and Xcode.Strong knowledge of RESTful APIs and third-party libraries.Experience with mobile app performance optimization.Familiarity with Firebase, push notifications, and cloud services.Ability to handle state management in mobile applications.Good understanding of UI/UX design principles and ability to implement complex animations.Experience with automated testing and debugging tools.Can communicate in English', 'Working hours: 9:00 - 17:00 (5 days per week); Breaking time: 12:00-13:00Salary: Open to Negotiate100% Offered Salary in probation timeModern working equipment (Macbook,...)Salary Review: 2 times/year based on employee''s performance and contribution;Well-equipped with insurance package as stated by Labor codePremium Health Insurance Package for all membersTransportation allowance and free parking included.Technical seminars and workshops annually.Free snack, coffee, tea available.Variety of corporate events: weekly tea-break, monthly birthday parties, quarterly team building to New Year party, company trip etc. Friendly, open and fast-paced environment where every idea is welcomed.Other benefits as per stated in Vietnamese Labor Law', 'Trụ sở chính công ty', 492, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (141, 126, '2022173', 'IT UI/UX Designer Biết Tiếng Hàn', 18.00, 20.00, '1 năm', 'Nhân viên', '2026-05-16 19:07:55.655775', '2026-06-22 19:07:55.655775', 5, 'Tiếp nhận yêu cầu và trao đổi thông tin từ khách hàng (Hàn Quốc); dịch và truyền đạt, mô tả lại cho developerTham gia design giao diện sản phẩm (Figma) Theo dõi tiến độ dự án và chất lượng sản phẩm trong suốt quá trình phát triểnHỗ trợ các công việc HCNS đơn giản tại công ty', 'Trình độ tiếng Hàn: Topik 5 trở lênTốt nghiệp đại học chính quy (4 năm, không quan trọng chuyên ngành)Thành thạo tin học văn phòngNăng động, tích cực trong công việc, kỹ năng giao tiếp, làm việc nhóm tốtBiết tiếng Anh, biết sử dụng các phần mềm thiết kế là một lợi thếCó kinh nghiệm làm việc liên quan đến IT là một lợi thế', 'Mức lương hấp dẫn, có thể tự do thỏa thuậnLàm việc 5 ngày / tuần, không tăng caKhông gian làm việc thoải mái, đồng nghiệp thân thiệnCó cơ hội học hỏi kiến thức mới và nâng cao năng lực chuyên mônThử việc 100% lương, lương tháng thứ 13, có xét nâng lương 6 tháng 1 lầnCó chế độ nghỉ hè, nghỉ Trung Thu, Giáng SinhBảo hiểm xã hội, khám sức khỏe định kỳ.', 'Trụ sở chính công ty', 612, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (145, 130, '2027450', 'Sales Online Sàn TMĐT & Showroom', 7.00, 8.00, '1 năm', 'Nhân viên', '2026-04-27 19:07:55.655775', '2026-05-16 19:07:55.655775', 7, 'Tư vấn, giới thiệu và bán các sản phẩm CNTT của công ty:(máy tính, linh kiện, thiết bị văn phòng, giải pháp công nghệ…)Tìm kiếm, phát triển và chăm sóc khách hàng mới & khách hàng hiện hữu.Tiếp nhận nhu cầu khách hàng, báo giá, đàm phán và chốt đơn hàng.Theo dõi tiến độ giao hàng, thanh toán và hỗ trợ sau bán hàng.Phối hợp với các bộ phận liên quan (kho, kỹ thuật, kế toán) để đảm bảo chất lượng dịch vụ.Thực hiện báo cáo doanh số, tình hình khách hàng theo định kỳ.Thực hiện các công việc khác theo phân công của Quản lý.', 'Nam/Nữ, độ tuổi từ 20 – 35.Tốt nghiệp Trung cấp/Cao đẳng/Đại học (ưu tiên các ngành Kinh doanh, CNTT, Marketing…).Có kỹ năng giao tiếp, thuyết phục và chăm sóc khách hàng tốt.Yêu thích công việc kinh doanh, có tinh thần cầu tiến, chịu được áp lực doanh số.Ưu tiên ứng viên có kinh nghiệm bán hàng lĩnh vực CNTT, thiết bị công nghệ.Thành thạo tin học văn phòng cơ bản (Word, Excel).', 'Đồng phục, điện thoại, công cụ dụng cụ làm việc...Được đào tạo kỹ năng mềm, kiến thức chuyên mônLương tháng 13, 12 ngày phép...Thưởng đóng góp sáng kiến, ý tưởng mới trong công việcThưởng thâm niên 3 năm, 5 năm, 10 năm.Chính sách phúc lợi cưới hỏi, ốm đau, thai sảnQuà trong các dịp Tết, Trung thu, sinh nhậtCơm canh trưa, mì gói, trứng, chà bông...BHXH, BHYT, BHTN, BH 24/24, Bảo hiểm cao cấpTiêm ngừa Cúm.....Khám sức khỏe định kỳPhòng tập GYM miễn phíDu lịch hàng năm trong/ngoài nước', 'Trụ sở chính công ty', 810, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (161, 143, '2030226', 'Business Analyst (Tiếng Anh Giao Tiếp Tốt)', NULL, NULL, '3 năm', 'Nhân viên', '2026-05-01 19:07:55.655775', '2026-05-25 19:07:55.655775', 5, 'Giao tiếp trực tiếp với Khách hàng để tìm hiểu yêu cầu và xây product roadmapTiến hành xử lý yêu cầu, phân tích nghiệp vụ và truyền đạt requirement cho teamTài liệu hóa các giải pháp thiết kế nghiệp vụ, bao gồm: Mockup/Wireframes/Prototype, tài liệu URD, SRS...Quản lý các yêu cầu thay đổi (CR) về nghiệp vụ trong quá trình Thực hiện dự án.Tham gia quá trình nghiệm thu & bàn giao sản phẩm cho khách hàng.Các công việc khác theo yêu cầu của bộ phận chuyên môn', 'Must haveTiếng Anh giao tiếp thành thạo Ít nhất 3 năm kinh nghiệm làm việc với vai trò Business Analyst trong môi trường OutsourcingKinh nghiệm làm việc với các phương pháp quản lý dự án khác nhau, bao gồm agile, waterfall, và hybrid.Thạo việc viết các tài liệu yêu cầu kinh doanh (BRD), User Stories/Use Case Specification Document, Functional Requirement Document.Thạo việc sử dụng các công cụ mockup/wireframe như draw, Figma.Kinh nghiệm với quy trình và phương pháp phát triển phần mềm.Kinh nghiệm trong việc hướng dẫn và đào tạo các thành viên nhóm ít kinh nghiệm hơn.Nice to haveKinh nghiệm trong domain Education, làm app/web học ngoại ngữChứng chỉ BA như CBAP, PBA, CCBA là lợi thế', 'Mức lương cạnh tranh, xem xét tăng lương dựa trên năng lực và hiệu quả công việc.Chương trình và chế độ ghi nhận đặc biệt cho nhân sự gắn bó lâu dàiChương trình NTQ Ranking giúp định hình lộ trình phát triển rõ ràng cho nhân sự khi gia nhậpĐược định hướng phát triển công nghệ chuyên sâu, tham gia nhiều dự án lớn và áp dụng công nghệ mới nhất.Cân bằng cuộc sống và công việc với các CLB ngoại khóa, hoạt động Teambuilding, nghỉ mát hàng năm, khu vực làm việc Open Space, Pantry và Board gameĐược đóng bảo hiểm theo quy định, kèm theo bảo hiểm sức khỏe cá nhân, bảo hiểm sức khỏe cho người thân, và chế độ thai sản tương đương 75% mức lương, khám sức khỏe 1 năm/1 lần.Văn hóa học tập & nghiên cứu: Hỗ trợ chi phí thi các chứng chỉ chuyên môn, tham gia các khóa học nội bộ up skills, khóa học phát triển lên quản lý cùng các chuyên gia có 15 năm kinh nghiệm trong lĩnh vực phần mềm.', 'Trụ sở chính công ty', 347, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (148, 132, '1940429', 'Nhân Viên Thiết Kế (Designer)', 10.00, 15.00, '1 năm', 'Nhân viên', '2026-05-17 19:07:55.655775', '2026-06-25 19:07:55.655775', 5, 'Thiết kế ấn phẩm truyền thông cho các kênh Facebook, TikTok, Website, sàn TMĐTThiết kế POSM, banner, standee, tờ rơi, catalogue, bao bì sản phẩm phục vụ hoạt động Marketing và bán hàng.Phối hợp với Content, TMĐT, CSKH để phát triển ý tưởng hình ảnh cho chiến dịch quảng bá, ra mắt sản phẩm.Đảm bảo hình ảnh thương hiệu nhất quán, sáng tạo và chuyên nghiệp.', 'Nam / Nữ, tuổi dưới 35.Tốt nghiệp chuyên ngành Thiết kế đồ họa, Marketing, Truyền thông hoặc liên quan.Có kinh nghiệm từ 1 năm trở lên trong lĩnh vực thiết kế (ưu tiên ngành Mỹ phẩm, Dược, FMCG, TMĐT).Thành thạo Photoshop, Illustrator (biết thêm Premiere/After Effects là lợi thế).Tư duy sáng tạo, chủ động, làm việc nhóm tốt và có tinh thần gắn bó lâu dài.', 'Thu nhập: 10 – 15 triệu/tháng (thỏa thuận theo năng lực).Lương tháng 13, thưởng đạt KPIs cá nhân, KPIs phòng, thưởng nóng kinh doanh toàn công ty, thưởng đột xuất sáng kiến sáng tạoBữa trưa miễn phí tại nhà ăn công tyLàm việc trong môi trường năng động, sáng tạo, cơ hội thăng tiến rõ ràng.Hưởng đầy đủ chế độ Bảo hiểm, nghỉ lễ, phép năm theo quy định.', 'Trụ sở chính công ty', 70, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (149, 133, '2036473', 'Nhân Viên Thiết Kế (Graphic Design)', 12.00, 16.00, '2 năm', 'Nhân viên', '2026-05-03 19:07:55.655775', '2026-06-14 19:07:55.655775', 5, '1. Thiết kế Digital & CampaignThiết kế ấn phẩm truyền thông trên Facebook, Instagram, TikTok, E-commerce.Phát triển Key Visual và concept hình ảnh cho các campaign, ra mắt sản phẩm mới.Đảm bảo hình ảnh đúng định hướng thương hiệu và đồng bộ trên các nền tảng.2. Thiết kế Print & POSMThiết kế banner, poster, backdrop, standee, booth… cho sự kiện và activation.Thiết kế POSM và tài liệu bán hàng: leaflet, sales kit, catalogue, giấy chứng nhận đại lý…Phối hợp với nhà in để đảm bảo chất lượng file và sản phẩm thực tế.3. Thiết kế tem nhãn & ấn phẩm sản phẩmThiết kế/điều chỉnh tem phụ, tem QR, tem treo và các ấn phẩm liên quan đến sản phẩm.Đảm bảo bố cục rõ ràng, thẩm mỹ và phù hợp đặc thù ngành dược mỹ phẩm.4. Phối hợp & hỗ trợ sáng tạoPhối hợp cùng Creative, Content, Digital, Sale để triển khai hình ảnh đồng bộ.Tham gia đề xuất ý tưởng, nâng cao tiêu chuẩn thẩm mỹ cho thương hiệu trong các chiến dịch, dự án, hoạt động,...Hỗ trợ chỉnh sửa video cơ bản (cắt ghép, chèn text, hiệu ứng đơn giản) phục vụ social và quảng cáo', 'Tốt nghiệp Cao đẳng/Đại học trở lên các ngành liên quan, ưu tiên các trường mỹ thuậtCó 02 năm kinh nghiệm ở vị trí tương đương. Ưu tiên ứng viên có kinh nghiệm trong ngành Beauty, Fashion, FMCG hoặc Agency.Kỹ năng chuyên môn:Sử dụng thành thạo Adobe Creative Suite (Photoshop, Illustrator, InDesign).Có kiến thức vững chắc về kỹ thuật in ấn, chất liệu và bao bì.Tư duy bố cục, màu sắc và Typography hiện đại, tinh tế.Tư duy công việc:Khả năng làm việc độc lập và chịu áp lực tiến độ.Tư duy giải quyết vấn đề qua thiết kế (Design Thinking).Điểm cộng: Có khả năng vẽ minh họa (Illustration) hoặc thiết kế 3D cơ bản (Mockup sản phẩm/Booth).', 'Mức lương: từ 12-16 triệuThử việc 2 tháng, hưởng 85% lươngThu nhập ổn định và cạnh tranh:Mức lương theo thỏa thuận, tương xứng năng lực.Thưởng lễ, Tết, thưởng hiệu suất, thưởng lương tháng 13 và các khoản phụ cấp khác (ăn trưa, thâm niên, công tác...).Phụ cấp thâm niên cho nhân sự từ 12 tháng chính thức trở lênChính sách bảo hiểm & nghỉ phép đầy đủ:Đóng BHXH, BHYT, BHTN sau thời gian thử việc.Nghỉ phép năm, nghỉ Lễ Tết theo quy định Nhà nước và chính sách công ty.Xét tăng lương định kỳ:Review lương 2 lần/năm dựa trên hiệu quả công việc và mức độ đóng góp.Phúc lợi nội bộ đa dạng:Du lịch công ty, team building hằng năm.Tổ chức sinh nhật và hoạt động tập thể tháng, liên hoan team hàng quý.Khám sức khỏe định kỳ 1 lần/ nămMôi trường làm việc chuyên nghiệp:Hiện đại, minh bạch, khuyến khích sự chủ động, hiệu quả và phát triển lâu dài, chú trọng đến lợi ích nhân viên.', 'Trụ sở chính công ty', 845, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (76, 66, '2030295', 'Fullstack Developer/ Lập Trình Viên Fullstack- Có Từ Trên 2 Năm Kinh Nghiệm Fullstack', NULL, NULL, '3 năm', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-17 19:07:55.655775', 5, 'airCloset là công ty cung cấp dịch vụ cho thuê thời trang hàng tháng, ra mắt vào tháng 2 năm 2015.Tính đến tháng 07/2023, airCloset đã phát triển lên hơn 1 triệu thành viên.Bên cạnh dịch vụ cốt lõi "airCloset" chúng tôi còn vận hành:"airCloset Mall", một trung tâm cho thuê hàng tháng được nhà sản xuất phê duyệt, nơi khách hàng có thể dùng thử sản phẩm tại nhà."airCloset Spot Rental" dịch vụ cho thuê trang phục cho các dịp như đám cưới và tiệc tùng.Trong giai đoạn sắp tới, airCloset hướng tới mở rộng sang thị trường châu Á, với mục tiêu tăng trưởng nhanh và bền vững.Bạn sẽ làm gì:● Tham gia phát triển và bảo trì các tính năng cho hệ thống airCloset (frontend và backend)● Làm việc với các thành viên team trong việc triển khai yêu cầu nghiệp vụ từ Product Owner● Phát triển giao diện người dùng với React, React Native, Flutter● Xây dựng và tối ưu API backend với Node.js● Viết unit test và tham gia vào các hoạt động testing, quality assurance● Debug và fix các vấn đề kỹ thuật trong codebase hiện có● Tham gia các buổi họp trao đổi và chia sẻ kiến thức● Viết documentation cho code và quy trình phát triển● Học hỏi và áp dụng các best practices trong phát triển phần mềmMôi trường phát triển:● Backend: NodeJS, Frontend: React, React Native, Flutter● Quản lý source-code: Github● Quản lý dự án: Backlog● CI: CircleCi● Infrastructure (cơ sở hạ tầng): AWS, GCP● Giao tiếp nội bộ: Slack', 'Yêu cầu chung:
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (151, 136, '2011788', 'Nhân Viên Developer – Hàng Len (Knitwear)', 15.00, 25.00, '2 năm', 'Nhân viên', '2026-04-27 19:07:55.655775', '2026-05-28 19:07:55.655775', 4, 'Phát triển mẫu (development) sản phẩm hàng len / knitwear theo yêu cầu khách hàngLàm việc với bộ phận thiết kế, kỹ thuật và sản xuất để hoàn thiện mẫuNghiên cứu nguyên phụ liệu: sợi, yarn, gauge, cấu trúc đanLàm BOM, tech pack, thông số kỹ thuật liên quan đến hàng lenTheo dõi quá trình làm mẫu, xử lý các vấn đề kỹ thuật phát sinhPhối hợp với khách hàng/Merchandiser trong giai đoạn phát triển sản phẩm', 'Có kinh nghiệm Developer hàng len từ 2 năm trở lênHiểu rõ quy trình sản xuất hàng len (flat knit / circular knit là lợi thế)Có kiến thức về sợi, cấu trúc đan, wash, finishingƯu tiên ứng viên đã làm việc với khách hàng quốc tếBiết tiếng Anh chuyên ngành là lợi thếCẩn thận, chủ động, có tinh thần làm việc nhóm', 'Mức lương: Thỏa thuận theo năng lựcTăng lương hàng năm, lương tháng 13, 14 ngày phép năm  trong nămĐược đào tạo, làm việc trong môi trường sản xuất chuyên nghiệpChế độ BHXH, BHYT, BHTN đầy đủ theo quy địnhCác phúc lợi khác theo chính sách công ty', 'Trụ sở chính công ty', 489, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (153, 165, '2025590', 'Lập Trình Viên IOS', 15.00, 25.00, '1 năm', 'Nhân viên', '2026-05-19 19:07:55.655775', '2026-06-07 19:07:55.655775', 5, 'Tham gia vào các dự án phát triển ứng dụng trên mobileNghiên cứu và phát triển các ứng dụng mới trên nền tảng iOSTham gia nghiên cứu - phát triển ứng dụng vào dự án mới theo từng thời điểm phát sinh dự án', 'Ưu tiên ứng viên có 1 năm kinh nghiệm lập trình iOSNăng động, trẻ trung, sáng tạo, sẵn sàng học hỏi và nghiên cứu công nghệ mớiTrung thực, có tinh thần trách nhiệm caoKhả năng làm việc độc lập và kỹ năng làm việc nhóm, chịu được áp lực công việc.Làm việc đúng deadline.Có khả năng đọc hiểu tiếng anh là một lợi thế.Ứng viên gửi đường link tham khảo các ứng dụng đã xây dựng trên App Store', '- Lương: 15 - 25tr- Thử việc 100% lương- Làm việc từ T2 – T6 (8h30 đến 17h30), nghỉ T7, CN và các ngày lễ tết theo quy định của nhà nước- Được thưởng lễ tết, xét thưởng- Phụ cấp cơm trưa và gửi xe đầy đủ- Được đóng BHXH, BHYT, BHTN theo quy định của nhà nước- Luôn sẵn sàng hoa quả và snack cho bạn trong thời gian làm việc- Làm việc trong môi trường chuyên nghiệp, năng động, thân thiện- Hỗ trợ cơm trưa', 'Trụ sở chính công ty', 853, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (122, 107, '2030384', 'Chuyên Viên Thiết Kế Đồ Họa (Graphic Designer) - Lương Cứng 14-17tr + Thưởng Dự Án, Doanh Thu - Tại Hà Nội', 14.00, 17.00, '1 năm', 'Nhân viên', '2026-04-26 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, '1. Thiết kế ấn phẩm dự án Bất động sản
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (160, 141, '1995772', '2D Artist', 13.00, 20.00, '1 năm', 'Nhân viên', '2026-04-24 19:07:55.655775', '2026-05-09 19:07:55.655775', 5, 'Thiết kế Concept 2D: nhân vật, vật phẩm, background cho game.
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (162, 144, '2013745', 'Thiết Kế 2D (2D Designer) Công Ty Event', 8.00, 13.00, '2 năm', 'Nhân viên', '2026-05-18 19:07:55.655775', '2026-06-17 19:07:55.655775', 7, 'Thiết kế 2D cho sân khấu, booth, khu vực trưng bày hoặc khu trải nghiệm theo brief của khách hàng.Có khả năng sketch (phác thảo nhanh), tư duy sáng tác, trao đổi, tư vấn thẩm mỹ thiết kế, hiện thực hoá (visualize) ý tưởng chung đã thống nhất.Thiết kế key visual, nhận dạng hình ảnh tổng quan cho sự kiện (POSM (banner, poster, mẫu trang phục, mẫu phụ kiện …) các trang trí khác cho event.Biết khai triển xuất file FA sản xuất. Có kinh nghiệm trong sản xuất in ấn là một lợi thế.Phối hợp với team 3D, Account và Production để đảm bảo thiết kế phù hợp thực tế thi công.Dựng layout, ánh sáng, vật liệu và render hình ảnh chất lượng cao để trình bày concept.Chuẩn bị file trình bày và hỗ trợ pitching với khách hàng.Đảm bảo tiến độ, chất lượng và tính sáng tạo trong từng dự án.', '1. Năng lực chuyên mônThành thạo Adobe Photoshop & Illustrator.Có kinh nghiệm thiết kế 2D cho Event: KV, POSM, ấn phẩm in ấn, trang trí không gian sự kiện.Hiểu rõ quy trình sản xuất – in ấn – thi công thực tế (đây là yêu cầu quan trọng).Ưu tiên / Điểm cộngSử dụng tốt Illustrator / InDesign cho layout in ấn, POSM số lượng lớn.Biết SketchUp cơ bản, AI hỗ trợ thiết kế hoặc After Effects (motion/visual pitching) là lợi thế.Có khả năng phối hợp với team 3D trong giai đoạn phát triển concept.2. Năng lực cốt lõiTinh thần trách nhiệm cao trong từng dự án.Kỹ năng làm việc nhóm, phối hợp đa bộ phận.Tư duy khách hàng – hiểu rõ yêu cầu và mong muốn của client.3. Năng lực chungQuản lý thời gian tốt, đáp ứng deadline.Giao tiếp trực quan và thuyết trình bản vẽ rõ ràng.Linh hoạt, thích ứng nhanh với thay đổi brief và timeline.Kinh nghiệm & Kiến thứcTốt nghiệp các ngành: Thiết kế , Mỹ thuật hoặc các ngành liên quan.Có ít nhất 2 năm kinh nghiệm thiết kế 2D trong lĩnh vực sự kiện, triển lãm, hội nghị, gian hàng.Có tư duy thẩm mỹ và không gian tốt, nhạy bén trong việc thể hiện ý tưởng sáng tạo dưới dạng hình ảnh trực quan.Có thêm các kinh nghiệm về 3D, motion là 1 lợi thếCó hiểu biết về quy trình thi công và thực tế sản xuất.Cập nhật xu hướng thiết kế và công nghệ hiển thị mới phục vụ công việc.', 'Lương 8 -13 Triệu, có nhiều cơ hội thăng tiến, Chế độ tăng lương, thưởng linh hoạt theo dự án dựa trên taget và sự đóng góp của nhân viên trong công việc.Phụ cấp, BHXH, BHYT, BH Thất nghiệp, Nghỉ phép >=12 ngày/năm.Company Trip, Đào tạo chuyên môn, kỹ năng, Có nhiều cơ hội thăng tiến.', 'Trụ sở chính công ty', 738, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (163, 145, '2010194', 'Product Owner/Product Manager (Robot AI_Edtech)', 20.00, 35.00, '2 năm', 'Nhân viên', '2026-05-03 19:07:55.655775', '2026-06-06 19:07:55.655775', 5, 'Gần đây nhất, Step Up vừa ra mắt Pika Robot – Robot AI học tiếng Anh đầu tiên cho các bạn nhỏ 6 - 12 tuổi tại Việt Nam.Chúng mình đang tìm kiếm những cộng sự chung chí hướng, đam mê tạo ra sản phẩm AI-native có giá trị thực, để cùng nhau phát triển Pika Robot và định hình tương lai của Edtech trong một môi trường lành mạnh, không gossip, và luôn win-win.Trong vai trò này, bạn sẽ là người định hình và dẫn dắt sự phát triển của Pika Robot, biến nó thành người bạn đồng hành học tiếng Anh thông minh, hấp dẫn và hiệu quả nhất cho trẻ em. Bạn sẽ không chỉ quản lý một backlog, mà sẽ thực sự sở hữu (own) các chỉ số quan trọng nhất và nắm bắt các hệ thống phức tạp, kết nối giữa Product, AI, và Dev Nhúng.Những bài toán và hệ thống chiến lược bạn sẽ giải quyết:VAI TRÒ CỦA BẠN: 1. Own chỉ số Retention & Engagement:- Thiết kế và dẫn dắt Epic Gamification: Xây dựng hệ thống ranking, vật phẩm, và các vòng lặp (loops) dựa trên tâm lý học hành vi để tạo thói quen học tập bền vững- Phân tích và tối ưu: Sử dụng dữ liệu để tìm ra các "aha moment", thiết kế và chạy các A/B test để cải thiện chỉ số retention (D1, D7, D30) 2. Dẫn dắt các hệ thống AI-native cốt lõi:- Buddy System (Memory & Personality): Làm việc sâu với team AI để xây dựng cho Pika một "trí nhớ" (memory) dài hạn, một tính cách (personality) nhất quán và khả năng trò chuyện tự nhiên, hấp dẫn- AI-driven Personalization: Dẫn dắt việc phát triển hệ thống Assessment và các Agent học tập chuyên biệt, cá nhân hóa lộ trình học cho từng đứa trẻ3. Làm cầu nối Product - AI - Embedded:- Chuyển hóa các ý tưởng sản phẩm thành các yêu cầu kỹ thuật (technical requirements) rõ ràng cho team AI và Dev Nhúng (Embedded)- Hiểu và đánh giá được các giới hạn, khả năng của model AI và phần cứng robot để đưa ra các quyết định sản phẩm thông minh- Thiết lập các framework để đánh giá (evaluate) chất lượng của các tính năng AI', 'Chúng mình tìm kiếm một người có tư duy của một founder cho chính sản phẩm mình làm, không chỉ là một người thực thi. Attitude là yếu tố quan trọng nhất.1. Attitude (Thái độ & Tư duy):- High Ownership & Excellence-Driven: Bạn ám ảnh về kết quả cuối cùng, xem chỉ số retention là của mình. Bạn đi sâu đi sát vào vấn đề và luôn tìm cách làm một việc cho thông minh và xuất sắc.- User-Centric Obsession: Bạn đam mê tạo ra giá trị thực cho người dùng cuối. Bạn là người đại diện cho tiếng nói của trẻ em và phụ huynh trong mọi quyết định.- Growth Mindset & Resilience: Bạn xem môi trường quy trình chưa rõ ràng là cơ hội để xây dựng. Bạn có khả năng xoay sở và học hỏi cực nhanh các domain mới (AI, learning science, embedded systems).- Probabilistic & Systems Thinking: Bạn cảm thấy thoải mái với sự không chắc chắn của các hệ thống AI (probabilistic) và có khả năng suy nghĩ ở cấp độ hệ thống, hiểu rằng việc thay đổi một model có thể ảnh hưởng đến toàn bộ trải nghiệm. 2. Skill (Kỹ năng  & Kinh nghiệm):Product Management Fundamentals (Must-have):- Kinh nghiệm tối thiểu 2-3 năm làm sản phẩm công nghệ, có case study thực tế đã build và scale sản phẩm B2C thành công (có outcome retention/engagement đo được.)- Kỹ năng phân tích dữ liệu, thiết kế và phân tích A/B test để ra quyết định.- Khả năng viết PRD, user stories chi tiết, rõ ràng, lường trước các edge casesTechnical Literacy (Rất quan trọng):- AI/ML Concepts: Hiểu các khái niệm về model, training data, evaluation, personalization để làm việc hiệu quả với team AI- Embedded Systems/IoT Basics: Hiểu các giới hạn về phần cứng (CPU, memory, pin) để đưa ra các quyết định thiết kế phù hợp User Psychology & Engagement Design (Must-have):- Có kinh nghiệm thực tế trong việc thiết kế hệ thống Gamification và hiểu các nguyên lý về động lực (intrinsic vs. extrinsic)- Có kiến thức về các mô hình tạo thói quen (VD: Hooked Model) 3. Knowledge (Kiến thức):- AI Know-How: Biết về các cơ chế nền tảng của các loại giải pháp AI ứng dụng (Generative AI, Predictive AI, Agentic AI). Chủ động sử dụng linh hoạt các giải pháp AI để tăng cường hiệu suất công việc hoặc gia tăng tốc độ phát triển sản phẩm.- User Experience & Interaction Psychology: Có kiến thức cơ bản về tâm lý trẻ em là một lợi thế lớn.- Tiếng Anh: Giao tiếp và đọc hiểu tự tin (tương đương IELTS 7.0+) để nghiên cứu tài liệu và làm việc với các đối tác/công nghệ toàn cầu.', 'Lương thưởng:- Lương tháng: 20M - 35M tùy level- Thưởng theo OKR dự án, thưởng hiệu quả kinh doanh của sản phẩm- Thưởng cải tiến, thưởng sáng tạo, lương tháng 13 Cơ hội phát triển:- Ownership thực sự: Bạn sẽ được trao quyền để sở hữu các hệ thống quan trọng nhất của một sản phẩm AI-native đột phá- Lộ trình thăng tiến rõ ràng: Cơ hội thăng tiến lên các vị trí Product Lead / Principal Product Manager- Được đầu tư để trở thành AI PM hàng đầu: Tham gia các khóa học chuyên sâu, workshop hàng tuần về AI, và làm việc trực tiếp với các chuyên gia hàng đầu trong lĩnh vực Chế độ khác:- Ăn trưa miễn phí tại Công ty, chế độ nghỉ phép, BHXH đầy đủ- Môi trường làm việc trẻ trung, năng động, không gossip, tập trung vào việc tạo ra sản phẩm xuất sắc CÁCH THỨC ỨNG TUYỂN:Ứng viên vui lòng gửi CV + Portfolio (nếu có).Quy trình tuyển dụng cho vị trí Product Owner tại Step Up (within 7 days):- Vòng 1: Review CV + Portfolio (Chúng mình đặc biệt quan tâm đến các case study, outcome nổi trội và cách bạn đã giải quyết các bài toán khó trong portfolio của mình)- Vòng 2: Test Submission (Công ty sẽ email bài test chuyên môn qua email sau 1-3 ngày, khi duyệt CV bạn phù hợp)- Vòng 3: Phone screen với HR (10 - 15 phút)- Vòng 4: Phỏng vấn chuyên môn (offline hoặc Google Meet) (60 - 90 phút).', 'Trụ sở chính công ty', 697, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (164, 146, '955292', 'System Admin', 20.00, 40.00, '2 năm', 'Nhân viên', '2026-05-19 19:07:55.655775', '2026-06-09 19:07:55.655775', 5, 'Triển khai cài đặt, cấu hình, tối ưu các hệ thống phần mềm như hệ điều hành, csdl, web server, app server, message queue, các hệ thống cân bằng tải, các hệ thống quản lý logs, các hệ thống monitoring, các hệ thống bảo mật, Data Platform, AI Platform, nền tảng cho devops, ci/cd, container và các hệ thống giải pháp khác khi có yêu cầu.Triển khai hạ tầng hybrid giữa on-prem và public cloud.Làm việc với khách hàng, bộ phận phân tích nghiệp vụ để chuyển các yêu cầu sang thiết kế kỹ thuật. Triển khai các giải pháp tự động hóa trong doanh nghiệp như Workload Automation, APM, AIOPsTriển khai các giải pháp tích hợp trong doanh nghiệp như APIs, ESB.Triển khai các nền tảng dữ liệu lớn như datalake, lakehouse, hạ tầng cho AI.Viết các shell script để tự động hóa hoặc đáp ứng yêu cầu quản trị, vận hành các hệ thống CNTT.', 'Tốt nghiệp ĐH, chuyên ngành CNTTCó ít nhất 2 năm kinh nghiệm liên quan đến công việc quản trị vận hành hệ thống. Có kinh nghiệm triển khai hạ tầng các hệ thống như Monitoring, LogsƯu tiênCó kiến thức về bảo mật, sql. Hiểu rõ SSO/SAML 2.0, LDAP, Active Directory, DNS Có kinh nghiệm triển khai các hệ thống CNTT trên Cloud như AWS, Azure, GCP, OCI, IBMCó kinh nghiệm viết shell script để thực hiện tự động hóa các tác vụ quản trị hệ thống.Có kinh nghiệm với các hệ thống Containers như K8s, Openshift.Có kinh nghiệp sử dụng các công cụ DevOps, ELK stack, Grafana, Prometheus, Git, CI/CD, Jenkins.Có khả năng lựa chọn giải pháp và công nghệ phù hợp dựa trên budgets, kiến trúc hiện tại và nhu cầu kinh doanh.Có khả năng thích nghi nhanh với thay đổi của công nghệ, các môi trường kiến trúc phức tạpTrách nhiệm, ham học hỏi, kỹ năng phân tích và giải quyết vấn đề tốtTiếng Anh: Toeic min 500', 'Lương: Thỏa thuận + các khoản thưởng cuối năm, thưởng HQKD (14-16 tháng lương/năm)Lộ trình phát triển và thăng tiến rõ ràng với kế hoạch đào tạo bài bản.Làm việc với đồng đội chuyên gia, xuất sắc trong lĩnh vực System, Cloud.Ngân sách đào tạo lên đến $5000/năm, bao gồm chi phí tài trợ học & thi các chứng chỉquốc tế.Hưởng mức lương cạnh tranh, thưởng hấp dẫn trực tiếp từ lợi nhuận Công ty (cam kếttối thiểu 14 tháng lương/năm).Gói Bảo hiểm sức khỏe cho bản thân và gia đình lên đến $3000/người.Làm việc trong môi trường chuyên nghiệp, thân thiện với 4 giá trị cốt lõi: Trust,Teamwork, Knowledge & Creativity, Customer.Sống & làm việc cân bằng với 4 giá trị: Health, Heart, Mind, Spirit cùng chính sách làmviệc linh hoạt.Mối quan hệ đồng hành giữa sếp & nhân viên. Công ty là ngôi nhà thứ hai nơi các thànhviên sống và làm việc cùng nhau với trái tim nhiệt huyết, chân thành và tinh thần học hỏikhông ngừngCác hoạt động văn hóa, giải trí phong phú: Team building, CLB Thể thao, âm nhạc,chương trình Sun-flower, Happy Hour...', 'Trụ sở chính công ty', 509, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (168, 149, '2029823', 'IT Comtor [Hà Nội] - Thu Nhập Cạnh Tranh, Từ 2 Năm Kinh Nghiệm, Hỗ Trợ Chi Phí Học Ngoại Ngữ & Công Tác Tại Hàn', NULL, NULL, '2 năm', 'Nhân viên', '2026-04-14 19:07:55.655775', '2026-05-13 19:07:55.655775', 5, 'Thực hiện phiên dịch trong các cuộc họp dự án, đảm bảo thông tin dự án được truyền đạt chính xác và kịp thời giữa team phát triển và team QAQuản lý dự án và lập kế hoạch, lịch trình theo yêu cầuThực hiện các công việc khác theo chỉ đạo của cấp trên', 'Trình độ tiếng Hàn TOPIK 5 trở lênTối thiểu 2 năm kinh nghiệm IT Comtor hoặc có kinh nghiệm thực tế trong lĩnh vực IT/Công nghệ thông tin(Ứng viên chưa từng làm IT Comtor nhưng có kinh nghiệm thực tế trong lĩnh vực IT vẫn có thể ứng tuyển)Ưu tiênỨng viên có kinh nghiệm QAKỹ năng giao tiếp tốtCó khả năng lập kế hoạch và quản lý tốt', 'Nghỉ phép & ngày lễ: Nghỉ phép năm, nghỉ lễ, nghỉ hiếu hỉ và ngày nghỉ đặc biệtHỗ trợ sức khỏe & phúc lợi: Khám sức khỏe định kỳ, đồ ăn nhẹ tại văn phòngTrợ cấp bữa trưaHỗ trợ phí gửi xe máyThưởng Tết (tối đa 2 tháng lương)Tiệc sinh nhật & hỗ trợ chi phí liên hoanWorkshop (1 lần/năm)Cơ hội công tác Hàn QuốcHỗ trợ chi phí học ngoại ngữ', 'Trụ sở chính công ty', 985, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (169, 149, '2017736', 'Project Manager [Hà Nội] - Thu Nhập Cạnh Tranh, Hỗ Trợ Chi Phí Học Ngoại Ngữ, Cơ Hội Công Tác Tại Hàn', NULL, NULL, '5 năm', 'Nhân viên', '2026-04-17 19:07:55.655775', '2026-05-03 19:07:55.655775', 5, 'Nstage luôn không ngừng cung cấp những tựa game hấp dẫn, tràn đầy niềm vui dành cho người chơi toàn cầu Nếu bạn hứng thú với vai trò điều phối toàn bộ dự án, quản lý để quá trình phát triển và vận hành game diễn ra suôn sẻ, đồng thời phối hợp chặt chẽ với các bộ phận để cùng nhau nâng cao chất lượng sản phẩm và dịch vụ,đây chính là cơ hội dành cho bạn!Sắp xếp lịch trình và hỗ trợ các công việc phối hợp giữa các phòng ban trong xuyên suốt toàn bộ dự ánTheo dõi và quản lý liên tục tiến độ cũng như lịch trình phát triểnQuản lý các tài liệu liên quan đến dự án và sắp xếp danh sách asset', 'Có tối thiểu 5 năm kinh nghiệm ở vị trí Operation PM hoặc Development PMCó kinh nghiệm tham gia dự án game puzzle casual hoặc game idleCó khả năng nhanh chóng nắm bắt đa dạng nhiều việc và sắp xếp một cách có hệ thốngCó kỹ năng giao tiếp và hợp tác tốtThành thạo công cụ phục vụ cho công việc như Notion, Spreadsheet...Có tinh thần trách nhiệm cao và thái độ làm việc chủ độngKhông gặp trở ngại trong việc đi công tác nước ngoàiƯU TIÊN: Ứng viên giao tiếp thành thạo tiếng Anh hoặc tiếng Hàn', 'Nghỉ phép năm và các ngày lễ theo quy định pháp luật, có nghỉ hiếu/hỉ và nghỉ phép đặc biệtKhám sức khỏe định kỳCung cấp đồ ăn nhẹ tại công tyHỗ trợ chi phí ăn trưaHỗ trợ phí gửi xe máy Thưởng Tết (tối đa 2 tháng lương)Nhân viên sinh nhật được tan làm sớmWorkshop (1 lần/năm)Cơ hội đi công tác Hàn QuốcHỗ trợ chi phí học ngoại ngữ', 'Trụ sở chính công ty', 6, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (165, 146, '1928068', 'Presale Data And Analytics (Banking)', NULL, NULL, '5 năm', 'Nhân viên', '2026-04-29 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, 'Solution Consulting & Pre-Sales- Engage in pre-sales activities, solution consulting, and solution presentations/workshops for customers and partners.- Conduct solution demos and Proof of Concept (PoC) implementations to help customers understand key solution features.- Provide solution support during RFI/RFP processes, including developing technical proposals for RFP responses.- Participate in solution deployment, provide technical support, and deliver training to customers.- Collaborate with Account Managers (AMs) to identify and develop potential business opportunities and maintain long-term client relationships.- Work with AMs to negotiate and finalize contracts with customers.Data Architecture & Implementation- Develop and evolve enterprise data architecture roadmaps aligned with changing business needs.- Design end-to-end analytical data flows, including overall architecture, capabilities, platforms, tools, and governance processes.- Create, maintain, and align current and future strategies for analytical tools and capabilities.- Support the identification and improvement of best practices, guidelines, and integrations across the bank’s data solutions and applications.- Keep up with technology trends, experiment with new tools, and evaluate their relevance to the organization’s analytical capabilities.', '- Minimum of 5 years of experience as a Data Architect, or at least 5 years as a Data Engineer.- Deep understanding of data modeling principles for both structured and unstructured data across physical, logical, and conceptual layers.- Hands-on experience in implementing data warehouse solutions, with knowledge of platforms such as iDecision, SAP, Teradata, Oracle, IBM, etc.- Proven experience implementing lakehouse/data platforms such as Cloudera, Databricks, Hortonworks, etc.- Extensive experience in designing and maintaining ETL/ELT pipelines, with expertise in at least one ETL platform (e.g., SAP BODS, Apache Airflow, Informatica, IBM).- In-depth knowledge of data architecture concepts (e.g., OLAP, Data Warehousing, Data Lake, Data Mesh) and the ability to assess current systems and emerging technologies to propose optimal data architecture solutions.- Strong proficiency with data modeling tools (e.g., Power Designer, SQL Developer Data Modeler, ERwin).- Practical experience in designing and implementing streaming data processing solutions (e.g., Apache Storm, Kafka, Spark Streaming).- Experience in data quality management solutions, including those in distributed environments.- Experience in Business Intelligence (BI) tool development for business requirements is an advantage.- Knowledge of standard financial data models (e.g., FSLDM) is a plus.- Deep understanding of data federation solutions, Master Data Management (MDM), and the entire data lifecycle.- Familiarity with object storage architectures.- English fluency (both written and spoken) is required.PREFERENCES:- Bachelor’s degree in Computer Science, Computer Engineering, Information Technology, or Applied Mathematics; a Master’s or PhD is a plus.- Relevant certifications in ETL, BI, data platforms, data streaming, or cloud computing are bonus points.', 'Why choose SVTECH?- SVTECH is different to lead the System Integration (SI) market, continuously growing over the past 22 years thanks to special people. Each SVTECHer is given the opportunity to understand himself, confidently promote his own strengths to carry out his mission, pursue his passion, and create his own value in the organization and society.1. Peace of mind with an income policy:Enjoy a competitive salary, attractive bonuses from Company profits and performance (average 15-17 months salary/year).Working allowances, OT. Provide laptops and other necessary tools/accounts/phone cards/tools for workMaster your work and enjoy the results. Transparent and frank communication with superiors throughout the working process and annual salary and capacity reviews2. Career development opportunities:Opportunities to receive training at home and abroad from reputable technology companies in the world: Oracle/IBM, Microsoft...Opportunity to work with Big4 customers. Working with extremely large and diverse data of “Big Corp” – national enterprises in the banking and finance industry, telecommunications, government, and businesses; with international stakeholders – Working according to international, standardized and professional standardsDirectly deployed for key technology projects. Participate in large projects spanning many diverse fields, work directly with big data systems of telecommunications, banks... interact with leading domestic and international experts.Become a key member of an important strategic department in the next 5-10 years of a top SI company – Many “stages”, many opportunities to experience and explore capabilities, limit yourself and increase value management, advancement opportunitiesOpportunities for training, unlimited access to resources, official learning materials, and exams for industry-leading certifications. Training budget up to $5000/person/year2 labs are heavily invested, currently, with diverse equipment located in Hanoi & HCMInvest in training budget, learn in addition to expertise soft skills, leadership, maximum awareness and self-development, coaching...3. Special benefits are focused on developing Heart, Body and Mind: All SVTECHers are inspired and motivated to live a meaningful, fulfilling life – Heath, Heart, Mind, SpiritHealth care: Health insurance for employees and relatives with a limit of $3,000/person; Periodic health check-ups in addition to the government’s Social Insurance policy.Together, we contribute to the community with many values and profound meanings with the Company’s major charity programs every year: building schools, building roads, providing learning equipment for children in highland areas...The budget is heavily focused on improving the spiritual life of individuals and families: Team building, union travel, YEP, Family days, Noel, Halloween, ...Diverse playgrounds help you stay healthy with sports clubs: football, badminton, swimming, jogging, yoga, music (Piano, guitar, drums...)4. Young, enthusiastic environment, many good people and experts in related fields. Likeability, solidarity, trust, listening, respect, care and maximum support from superiors, subordinates, and colleagues – these are qualities that seem to flow implicitly in the core cultural blood of the company. organized and passed down from generation to generationFlexible working policy in terms of time, work location and scope of work according to agile.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (53, 45, '2037459', 'Technical Operation Intern', NULL, NULL, 'Dưới 1 năm', 'Nhân viên', '2026-05-04 19:07:55.655775', '2026-05-22 19:07:55.655775', 7, 'Hỗ trợ setup hệ thống kỹ thuật cho livestream: camera, âm thanh, ánh sáng.Hỗ trợ trực set trong quá trình livestream, đảm bảo thiết bị vận hành đúng yêu cầu.Phối hợp với team và các bộ phận liên quan để hỗ trợ kỹ thuật trong ca livestream.Hỗ trợ kiểm tra, chuẩn bị và thu dọn thiết bị trước và sau mỗi buổi livestream.Thực hiện các công việc khác theo sự phân công của quản lý.', 'Sinh viên tốt nghiệp từ các ngành liên quan đến Công nghệ Thông tin, Truyền thông, Thương mại Điện tửBiết hoặc đã từng sử dụng các phần mềm livestream (OBS, Vmix…) là lợi thế.Yêu thích công nghệ, kỹ thuật livestream.Siêng năng, chủ động học hỏi, có tinh thần trách nhiệm.Có khả năng làm việc nhómCó thể sắp xếp thời gian linh hoạt theo lịch livestream.', 'Làm việc trong môi trường làm việc rất năng động & cởi mởTrợ cấp thực tập, hỗ trợ dấu mộc (nếu cần)Xây dựng đội nhóm, Chuyến đi công ty, Hoạt động gắn kết.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (26, 16, '2028837', 'Game Platform Backend Engineer (Senior - Lead)', NULL, 45.00, '2 năm', 'Nhân viên', '2026-05-19 19:07:55.655775', '2026-06-19 19:07:55.655775', 5, 'Phát triển và vận hành các API hỗ trợ cho SDK , BIXây dựng các tool backend phục vụ UA , BI...Phối hợp với frontend/tool engineer để phát triển tool', 'Có 2+ năm kinh nghiệm với Node.js, Express.js hoặc NestJS.Có kinh nghiệm làm việc trong lĩnh vực game (mobile/online), ưu tiên từng tham gia phát triển hoặc vận hành các hệ thống backend/SDK/BI cho game.Có kinh nghiệm dẫn dắt nhóm kỹ thuật (3–6 người) hoặc giữ vai trò Lead/Principal Engineer.Thành thạo làm việc với cơ sở dữ liệu (MongoDB, MySQL hoặc tương đương).Có kinh nghiệm xây dựng API nội bộ hoặc hệ thống hỗ trợ sản phẩm game/app.', 'Thu nhập & Đãi ngộ minh bạch, hấp dẫnThu nhập thỏa thuận theo năng lực, upto 45.000.000 VNĐ Gross.Thưởng ghi nhận & vinh danh nội bộ:Wow Award – giải thưởng “tự khoe thành tích”Super Funner hàng tháng/quý dành cho cá nhân & team xuất sắcThưởng cuối năm & thưởng nóng theo kết quả kinh doanh và hiệu quả công việc.Quà, thưởng các dịp lễ, tếtReview lương định kỳ 6 tháng/lần, ghi nhận đúng năng lực & đóng góp.Phúc lợi đời sống & chăm sóc sức khỏeTrợ cấp ăn trưa coupon 40.000đ/ngày qua ví điện tử nội bộ, sử dụng trực tiếp tại canteen Funtime.Miễn phí vé gửi xe tháng.Khám sức khỏe định kỳ hằng năm tại các bệnh viện.Bảo hiểm đầy đủ: BHXH, BHYT, BHTN theo Luật Lao động.Bảo hiểm sức khỏe cao cấp (từ cấp Lead trở lên, hỗ trợ mua thêm cho người thân).Gắn kết – Phát triển – Trải nghiệmYear End Party, Summer Trip, Outing, team building 2 lần/năm và các sự kiện nội bộ định kỳ.Đào tạo chuyên môn & kỹ năng, chương trình phát triển năng lực rõ ràng.Môi trường làm việc năng động, nhiều hoạt động văn hóa nội bộ.CLB chăm sóc sức khỏe thể chất & tinh thần: Yoga, bóng đá, cầu lông…Thời gian làm việcThứ 2 – Thứ 6 (9:00 – 18:00) và tối đa 2 sáng thứ 7 cách tuần làm việc theo hình thức remote (rất ít khi phát sinh, gần như không làm việc thứ 7).', 'Trụ sở chính công ty', 629, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (27, 18, '1541046', 'Junior/ Middle Business Analyst', NULL, 35.00, '3 năm', 'Nhân viên', '2026-05-03 19:07:55.655775', '2026-06-11 19:07:55.655775', 5, 'Phân tích và hiểu yêu cầu của khách hàng:Thu thập và phân tích yêu cầu từ khách hàng, làm rõ các mục tiêu, nhu cầu và mong muốn của khách hàng.Thực hiện các cuộc phỏng vấn và hội thảo với các bên liên quan.Hỗ trợ lên function list trong giai đoạn presale Xây dựng tài liệu yêu cầu:Soạn thảo và duy trì các tài liệu yêu cầu nghiệp vụ (BRD), tài liệu mô tả quy trình (Use Cases) và tài liệu mô hình hóa quy trình nghiệp vụ.Đảm bảo kết nối giữa khách hàng và đội ngũ phát triển:Hỗ trợ đội ngũ phát triển hiểu rõ yêu cầu của khách hàng và đảm bảo tính khả thi của các giải pháp kỹ thuật.Tham gia họp định kỳ và báo cáo tiến độ dự án với các bên liên quan.Quản lý và kiểm soát thay đổi yêu cầu:Theo dõi và cập nhật các yêu cầu thay đổi, đảm bảo các bên liên quan đều được cập nhật và các yêu cầu được thực hiện chính xác.Đánh giá và cải tiến quy trình:Phân tích hiệu quả của các quy trình nghiệp vụ hiện tại và đề xuất cải tiến.Hỗ trợ kiểm tra và đánh giá sản phẩm trong giai đoạn thử nghiệmQuản lý dự án: Tham gia quản lý dự án với vai trò PM khi cần', 'Kinh nghiệm:Tối thiểu 3 năm kinh nghiệm làm việc ở vị trí Business Analyst hoặc các vị trí liên quan trong ngành công nghệ thông tin, giáo dục, tài chính, hoặc dịch vụ.Ưu tiên ứng viên có kinh nghiệm trong vai trò PM/PO dự ánKỹ năng ngôn ngữ:Tiếng Anh thành thạo (nghe, nói, đọc, viết) tương đương IELTS 6.5 trở lênHoặc  tiếng Hàn - Topik 5 trở lênKỹ năng chuyên môn:Hiểu biết tốt về quy trình phân tích và thiết kế nghiệp vụ, mô hình hóa quy trình (BPMN, UML).Khả năng soạn thảo tài liệu yêu cầu nghiệp vụ và quy trình làm việc.Kỹ năng phân tích dữ liệu và sử dụng thành thạo Excel, SQL là một lợi thế.Kỹ năng mềm:Kỹ năng giao tiếp, thương lượng và giải quyết vấn đề.Khả năng làm việc nhóm và làm việc độc lập hiệu quả.Tư duy logic và kỹ năng tổ chức công việc tốt.', '1.Cơ hội thăng tiếnĐến với UPP Global Technology, ứng viên có cơ hội được:Làm việc trong môi trường trẻ, minh bạch với cơ hội thăng tiến rõ ràngĐược tạo điều kiện tối đa để phát triển năng lực cá nhân, tập thể và năng suất làm việc2. Lương thưởngLương thỏa thuận theo năng lực up to 35M. Nhận 100% lương trong quá trình thử việc.Lương tháng 13, định kỳ đánh giá hiệu quả công việc hàng năm. Thưởng khi có thành tích xuất sắc.Chăm sóc sức khỏe định kỳ hàng năm.Ngoài các gói bảo hiểm cơ bản theo quy định của Luật Lao Động, bạn còn được tham gia gói bảo hiểm sức khỏe của PTI sau thời gian thử việc.Được cấp laptop, máy tính làm việcTiền lương làm thêm giờ theo quy định của nhà nướcCách thức ứng tuyển: Ứng viên gửi 1 bản CV bằng tiếng AnhNgày làm việc: Làm việc từ T2-T6; nghỉ T7, CN, Lễ Tết.Thời gian làm việc linh hoạt: 8 tiếng/ngày, trong khoảng 8h00 - 10h00 và kết thúc trong khoảng 17h00 đến 19h00', '-Hà Nội:Tòa Web3 Số 15 Ngõ 4 Duy Tân, Cầu Giấy, Phường Cầu Giấy', 873, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (44, 41, '2029283', 'Middle Mobile Developer (IOS/Android/Flutter)', NULL, 35.00, '3 năm', 'Nhân viên', '2026-05-17 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, 'Tập đoàn MISA, thành lập năm 1994, là doanh nghiệp CNTT hàng đầu Việt Nam với hơn 350.000 khách hàng tổ chức và gần 3,5 triệu cá nhân, hiện diện tại 22 quốc gia. MISA tiên phong phát triển Agentic AI và nền tảng AIaaS, cung cấp giải pháp số hóa cho doanh nghiệp, hộ kinh doanh và chính phủ. Định vị là tập đoàn dẫn đầu về Agentic AI, MISA cam kết đổi mới sáng tạo, giúp tối ưu vận hành, nâng cao hiệu quả và giảm tải thủ công cho tổ chức. Sứ mệnh của MISA là đồng hành cùng chính phủ, doanh nghiệp và cá nhân trong hành trình chuyển đổi số, khẳng định vị thế công nghệ Việt Nam trên quốc tế.Mô tả công việcPhát triển các sản phẩm của công ty trên nền tảng iOS/Android/FlutterTìm hiểu, nghiên cứu các công nghệ mới theo định hướng phát triển của công ty', 'Trình độ học vấn và thâm niên:Tốt nghiệp CĐ, ĐH chuyên ngành công nghệ thông tin, kỹ thuật phần mềm hoặc các trường đào tạo lập trình viên Quốc tế (NIIT, Aptech) trở lênTối thiểu 3 năm kinh nghiệm lập trình Android/iOS/FlutterKiến thức chuyên môn:Nắm vững OOP, hiểu biết sâu về cấu trúc dữ liệu & giải thuậtThành thạo một trong các ngôn ngữ: Java core/Android, Objective-C/Swift, Flutter/DartSử dụng thành thạo Android Studio (cho Android), Xcode (cho iOS)Thành thạo các công cụ quản lý source code (Git) và quản lý dự án (Jira)Nắm vững các UI control, layout, animation (đặc biệt trên iOS); có khả năng customize và tối ưu giao diệnCó kinh nghiệm lập trình giao tiếp giữa mobile và server qua các giao thức TCP/IP, HTTP; nắm vững XML, JSONCó kinh nghiệm làm việc với database SQLite (Android) hoặc Core Data (iOS)Có hiểu biết về các kiến trúc phát triển di động: MVP, MVVM, Clean ArchitectureCó kinh nghiệm với KMM, Kotlin MultiplatformKĩ năng:Cẩn thận, tỉ mỉ trong công việcHam học hỏi, cập nhật công nghệ mớiTinh thần trách nhiệm caoKhả năng làm việc nhóm tốt', 'Nền tảng vững chắc cho phát triển sự nghiệp, thăng tiến, quyền lợiLương cứng cạnh tranh. Thưởng năng suất dựa trên kết quả công việc từ 2 tháng lương.Đánh giá review lương 2 lần/năm, thưởng sáng kiến...Trợ cấp cơm trưa + gửi xe miễn phíHuấn luyện “Hổ tướng”: chương trình đào tạo quản lý tài năng, bệ phóng trở thành Chiến tướng tinh nhuệGiải thưởng “Gấu vàng": nơi tôn vinh những tài năng xuất sắc nhấtGói chăm sóc sức khỏe toàn diện tại Medlatec, cháy hết mình tại các CLB theo sở thích, chương trình teambuilding, du lịch định kỳTiên phong công nghệ, uy tínMISA là doanh nghiệp CNTT xuất sắc nhất khu vực Châu Á - Châu Đại Dương. Tiên phong xuất khẩu giải pháp SaaSTOP đầu doanh nghiệp CNTT tăng trưởng liên tục với quy mô nhân sự tăng 20%/năm, doanh thu tăng 15%/nămHội tụ 3000 nhân tài cùng khát vọng đưa sản phẩm công nghệ “Make In Vietnam” vươn tầm quốc tếXây dựng niềm tin với 350.000 khách hàng tổ chức và gần 3,5 triệu cá nhân, hiện diện tại 22 quốc gia.Hơn 100 giải thưởng trong ngành CNTT trong nước và quốc tếMôi trường thân thiện, chia sẻ, đồng hànhKết nối tài năng: tập trung phát triển những con người có chung lý tưởng, mục tiêu, cùng trao giá trị và nhận thành côngTư duy đột phá: môi trường tôn trọng sự khác biệt và đề cao sáng tạo, MISA-er được tự do phát triển các ý tưởng tiến bộ, cải tiến công việcCông nghệ cao: trang bị máy tính làm việc, tối ưu hiệu suất công việc bằng ứng dụng công nghệ, phần mềm tự động (AMIS, Jira, Power BI, AI Marketing,...)Nơi làm việc hạnh phúc: MISA mong muốn tạo một môi trường làm việc để bạn luôn cảm thấy hạnh phúc', '-Hà Nội:Tầng 2, Toà N03T1, Khu đô thị Ngoại giao đoàn, Phường Xuân Đỉnh', 765, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (171, 151, '2029086', 'Graphic Designer', 6.00, 12.00, 'Dưới 1 năm', 'Nhân viên', '2026-04-25 19:07:55.655775', '2026-06-01 19:07:55.655775', 5, 'Thiết kế banner quảng cáo (Google Ads, Mintegral,…), ASO (App Store, Google Play)Phối hợp cùng team liên quan để phát triển concept, định hướng hình ảnh cho dự án. Phát triển bộ hình ảnh dành cho store (App/Game): screenshot, icon và các asset liên quan.Đề xuất các ý tưởng sáng tạo, phương án thể hiện mới và tham gia tối ưu quy trình sản xuất để nâng cao chất lượng', '6 tháng - 1 năm kinh nghiệm trong lĩnh vực thiết kế. Ưu tiên ứng viên từng làm tại các Agency hoặc công ty Tech/Startup.Thành thạo Adobe Creative Suite (AI, PS). Biết sử dụng Sketch và Figma là 1 lợi thế.Có tư duy thiết kế, chú trọng vào sự tiện dùng và trải nghiệm. Có kiến thức về thẩm mỹ: bố cục, phối màu,…Tư duy logic tốt, có thể nắm bắt nhanh các giải pháp công nghệ của công ty.Có khả năng sắp xếp công việc, chịu được áp lực khi triển khai nhiều dự án cùng thời điểm.Biết nghiên cứu sản phẩm, insight user là một lợi thế.', 'Thu nhập hấp dẫn: Lương NET 06-12 triệu (Tùy theo năng lực).Thưởng hiệu suất làm việc hàng tháng (Dựa theo performance).Review lương: 2 lần/ 1 năm.Được hưởng đầy đủ các chế độ dành cho người lao động theo quy định pháp luật hiện hành(BHYT, BHXH, BHTN…)Thưởng tết âm lịch, 12 ngày phép năm, thưởng Lễ/tết (theo quy định công ty) (lương thưởng bảo hiểm trả/đóng đúng hạn), thưởng quý, thưởng cuối năm, thưởng Nhân viên xuất sắc,…)Được hưởng các quyền lợi khác theo chính sách của công ty.Trà, cà phê, đồ ăn vặt… miễn phí tại văn phòngTham gia các hoạt động, sự kiện của Wavez: team building, dã ngoại, du lịch, sinh nhật…Môi trường làm việc chuyên nghiệp, thân thiện, tạo điều kiện cho ứng viên phát huy tốt nhất năng lực cá nhân.', 'Trụ sở chính công ty', 631, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (43, 39, '2005526', 'IT Business Development', NULL, 18.00, '1 năm', 'Nhân viên', '2026-04-20 19:07:55.655775', '2026-05-22 19:07:55.655775', 5, 'Identify, prospect, and develop new business opportunities in global and APAC markets.Promote HR services such as Dedicated Teams, RPO, Headhunting, IT Staffing, and more to potential clients.Build and maintain strong relationships with key decision-makers (CTOs, HR Directors, Procurement Managers, etc.).Develop tailored proposals, lead negotiations, and close deals effectively.Collaborate closely with Delivery and Recruitment teams to ensure smooth onboarding and high client satisfaction.Achieve monthly and quarterly sales targets, contributing directly to company revenue.Stay updated on market insights, industry trends, and competitor movements to inform sales strategy.', 'Bachelor’s degree in Business, Marketing, IT, or related fields.From 1 years of proven sales experience in IT Outsourcing, Staffing, HR Services, or Technology Solutions.Strong network or direct experience working with international markets, especially APAC.Excellent communication, negotiation, and presentation skills in English (additional languages are a plus).Results-oriented, with a strong hunter mindset and ability to work independently.Understanding of the software development lifecycle (SDLC), IT services, or HR/recruitment processes is an advantage.', 'Salary range: 18M VND (based on capability) + BonusOpportunity to work with international clients in a dynamic and fast-growing environment.Clear career growth path in Business Development and International Sales.', 'Trụ sở chính công ty', 2, NULL, 1);
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (80, 69, '2025330', 'Senior Fullstack  Engineer (5+ Years Of Experience) - Upto $3000', NULL, NULL, '5 năm', 'Nhân viên', '2026-05-11 19:07:55.655775', '2026-06-02 19:07:55.655775', 5, '1. Fullstack Development & AI Integration• Web & Mobile: Develop and maintain high-quality code for our Consumer Apps (React Native/Flutter) and Provider Portals/Admin Dashboards (React/Next.js).• AI Implementation: Proactive in the integration of AI models into our applications. This includes connecting with LLM APIs, building RAG (Retrieval Augmented Generation) pipelines, and handling image processing workflows in collaboration with our AI Researchers.• Backend Logic: Architect and implement server-side logic using Python (for AI heavy lifting) and Node.js (for application logic).2. The "Dual-Mode" Execution 
INSERT INTO public.jobs (jobid, companyid, originalid, title, salarymin, salarymax, expyear, level, posteddate, deadline, locationid, description, requirement, benefits, address, viewcount, deletedat, status) VALUES (132, 116, '2036976', 'Heads Of Growth & Partnerships (Project-Based)', NULL, NULL, '5 năm', 'Nhân viên', '2026-05-21 19:07:55.655775', '2026-06-19 19:07:55.655775', 7, '1. Market Development StrategyResearch and analyze regional markets, including market size, trends, player behavior, and venue models.Assess direct and indirect competitors.Identify target customer segments (B2C, B2B, venue owners, clubs, etc.).Develop market entry and expansion roadmaps.Propose phased action plans aligned with market development stages.2. Partnership Ecosystem DevelopmentProactively identify, approach, and negotiate partnerships with:Pickleball court ownersSports clubsTournament organizersSponsors and relevant brandsDesign partnership models (revenue sharing, co-branding, sponsorship, etc.).Develop partnership materials (proposals, partner policies, collaboration workflows).Establish and manage the partner pipeline.Maintain long-term partner relationships and optimize partnership performance.3. User Growth & Revenue AccelerationCoordinate and execute activities to attract players and activate communities.Monitor and analyze growth metrics, including:Number of venue owners onboardedSystem adoption rateNumber of new usersConversion ratePartner and user retention ratesOptimize revenue generation models within the ecosystem.Ensure assigned growth KPIs are achieved.4. Scalable Foundation BuildingStandardize partnership development and management processes.Build and manage a partnership opportunity pipeline system.Propose improvements to the business model as market conditions evolve.Recommend market development team structures for subsequent growth phases.Perform other strategic tasks as assigned by the Founder at each development stage.', 'Bachelor’s degree in Business Administration, Marketing, Economics, Commerce, or related fields.Minimum 5 years of experience in business development, market development, growth roles, or tech startup environments.Proven experience in launching and expanding new markets from early stages.Strong negotiation and relationship-building skills.Strategic mindset with strong hands-on execution capability.Existing network in sports, community, or startup ecosystems is a plus.', 'Income based on mutual agreement (including fixed compensation plus growth KPI-based incentives).Opportunity to participate in building a technology platform from the early stage.Direct collaboration with the Founder and Executive Team.Flexible working environment focused on performance and ownership.Opportunity to grow with a project targeting regional and international expansion.', 'Trụ sở chính công ty', 492, NULL, 1);
